/// Canonical 256-bit identity, preserving byte order without native-word conversion.
#[repr(transparent)]
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Hash, Default)]
pub struct Identity256([u8; 32]);

impl Identity256 {
    pub const fn from_bytes(bytes: [u8; 32]) -> Self {
        Self(bytes)
    }
    pub const fn as_bytes(&self) -> &[u8; 32] {
        &self.0
    }
}

/// A native observer executed during cold task binding. Implementations belong to
/// the program executor, not the CUDA substrate. Python accepts executable XLOG
/// source through that executor, never caller-provided answers or receipts.
/// A successful observation must complete all submitted work before returning
/// host results. An error may follow device submission, so the calling session
/// is poisoned and cannot reuse its previous task binding.
pub trait SemanticTaskProgram: fmt::Debug + Send + Sync {
    /// A cold, independently admitted mutable source bank. The observer may
    /// report expected truth but never chooses editable rules or fact order.
    fn editable_program(&self) -> Option<&crate::SemanticProgramAdmission> {
        None
    }

    fn observe(
        &self,
        provider: Arc<CudaKernelProvider>,
    ) -> Result<SemanticTaskObservation, SemanticTransitionError>;
}

/// Actual native observer output and the exact source/input/result custody used
/// to derive it. These bytes describe execution; they grant no application rights.
pub struct SemanticTaskObservation {
    pub program_source: Vec<u8>,
    pub input_bytes: Vec<u8>,
    pub result_bytes: Vec<u8>,
    pub actual_truths: Vec<crate::SemanticTruth>,
}

/// Independently recomputable identities of the exact semantic task content.
/// These values carry no use authority. They let retained symbolic training
/// rows bind the ordered query, admitted theory plus executed observer program,
/// and observed four-valued result to the task that the native owner actually
/// executed during cold binding.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct SemanticTaskContentIdentity {
    pub query: Identity256,
    pub theory_program: Identity256,
    pub result: Identity256,
}

/// Explicit nonnegative coefficients for query agreement and measured work.
/// These coefficients determine the measured value and final return; ordered
/// task priorities, agreement, and cost select the candidate in that order.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct SemanticTaskScoring {
    pub correct_weight: u32,
    pub all_correct_weight: u32,
    pub work_weight: u32,
    pub improvement_weight: u32,
    pub refusal_weight: u32,
    pub spent_weight: u32,
}

/// Task-independent unit and finite cap for native structural work. The unit
/// names the versioned counting law and the resident program mode, not the
/// authority, task identity, or outcome of a sampled candidate.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct SemanticStructuralCostDescriptor {
    pub unit: Identity256,
    pub cap: u64,
}

/// Evaluator interval and objective coefficients frozen by the native task
/// before actions, independently of any future training-group membership.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct SemanticTaskObjectiveLaw {
    pub return_bound: i64,
    pub evaluator_min: f64,
    pub evaluator_max: f64,
    pub coefficients: [f32; 9],
    pub structural_cost: SemanticStructuralCostDescriptor,
}

impl SemanticTaskObjectiveLaw {
    fn require_objective(
        self,
        objective: &SemanticTrainingObjective,
    ) -> Result<(), SemanticTransitionError> {
        if objective.evaluator_min.to_bits() != self.evaluator_min.to_bits()
            || objective.evaluator_max.to_bits() != self.evaluator_max.to_bits()
            || objective.coefficients.map(f32::to_bits) != self.coefficients.map(f32::to_bits)
            || objective.cost_unit != self.structural_cost.unit
            || objective.cost_cap != self.structural_cost.cap
        {
            return Err(publication_input_error(
                "training objective differs from the evaluator, coefficients or cost law frozen before actions",
            ));
        }
        Ok(())
    }
}

/// The only structural-cost law accepted by a cold training objective.
pub fn semantic_structural_cost_descriptor(
    editable_program: bool,
    query_count: u32,
) -> SemanticStructuralCostDescriptor {
    let (support_cap, truth_change_cap) = if editable_program {
        (
            crate::semantic_program::RESIDENT_PROGRAM_FACT_CAPACITY as u64,
            u64::from(query_count),
        )
    } else {
        (2u64, 2u64)
    };
    let cap = 2 + support_cap + truth_change_cap;
    let mut hash = Sha256::new();
    hash.update(b"xlog.semantic.structural-cost.v1\0");
    for word in [
        u64::from(editable_program),
        2,
        support_cap,
        truth_change_cap,
        cap,
    ] {
        hash.update(word.to_le_bytes());
    }
    SemanticStructuralCostDescriptor {
        unit: Identity256::from_bytes(hash.finalize().into()),
        cap,
    }
}

/// One normalized truth-match objective within an ordered task priority level.
/// The native query result contributes one when it equals `target_truth`, zero
/// otherwise; candidate progress subtracts the acquired base's contribution.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct SemanticTaskPriorityGoal {
    pub query: u32,
    pub target_truth: u8,
    pub weight: u32,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct SemanticTaskPriorityLevel {
    pub goals: Vec<SemanticTaskPriorityGoal>,
}

impl SemanticTaskScoring {
    fn words(self) -> [u64; 6] {
        [
            self.correct_weight,
            self.all_correct_weight,
            self.work_weight,
            self.improvement_weight,
            self.refusal_weight,
            self.spent_weight,
        ]
        .map(u64::from)
    }

    fn return_bound(
        self,
        editable_program: bool,
        query_count: u32,
    ) -> Result<i64, SemanticTransitionError> {
        // A rule may derive many facts from one command. Successful resident
        // materialization caps the fact bank at 4096, and a candidate can also
        // change every admitted query truth. The graph-only path retains its smaller
        // support-attachment cap. Priority selection need not maximize value,
        // so both signs of selected-minus-base value must fit.
        let max_cost =
            u128::from(semantic_structural_cost_descriptor(editable_program, query_count).cap);
        let queries = u128::from(query_count);
        let max_spent = if editable_program {
            5 * queries + 4
        } else {
            3 * queries + 8
        };
        let value_span = queries * u128::from(self.correct_weight)
            + u128::from(self.all_correct_weight)
            + max_cost * u128::from(self.work_weight);
        i64::try_from(value_span)
            .map_err(|_| publication_input_error("task value can overflow signed arithmetic"))?;
        let return_bound = value_span * u128::from(self.improvement_weight)
            + 2 * u128::from(self.refusal_weight)
            + max_spent * u128::from(self.spent_weight);
        i64::try_from(return_bound)
            .map_err(|_| publication_input_error("task scoring can overflow the signed return"))
    }

    fn validate(
        self,
        editable_program: bool,
        query_count: u32,
    ) -> Result<(), SemanticTransitionError> {
        self.return_bound(editable_program, query_count).map(|_| ())
    }

    fn objective_law(
        self,
        editable_program: bool,
        query_count: u32,
    ) -> Result<SemanticTaskObjectiveLaw, SemanticTransitionError> {
        let return_bound = self.return_bound(editable_program, query_count)?;
        let mut evaluator_max = return_bound as f64;
        // The integer return bound may exceed exact FP64 integer precision.
        // Never narrow the proven interval when rounding its upper endpoint.
        if (evaluator_max as u128) < return_bound as u128 {
            evaluator_max = f64::from_bits(evaluator_max.to_bits() + 1);
        }
        let evaluator_min = -evaluator_max;
        Ok(SemanticTaskObjectiveLaw {
            return_bound,
            evaluator_min,
            evaluator_max,
            coefficients: frozen_training_coefficients(evaluator_min, evaluator_max),
            structural_cost: semantic_structural_cost_descriptor(editable_program, query_count),
        })
    }

    #[cfg(feature = "semantic-policy")]
    fn completed_law_bytes(
        self,
        task_identity: Identity256,
        editable_program: bool,
        query_count: u32,
    ) -> Result<Vec<u8>, SemanticTransitionError> {
        let mut bytes = b"XLOG-TASK-SCORING-LAW\0".to_vec();
        material_u64(&mut bytes, 2);
        bytes.extend_from_slice(task_identity.as_bytes());
        let structural_cost = semantic_structural_cost_descriptor(editable_program, query_count);
        bytes.extend_from_slice(structural_cost.unit.as_bytes());
        material_u64(&mut bytes, structural_cost.cap);
        for weight in self.words() {
            material_u64(&mut bytes, weight);
        }
        bytes.extend_from_slice(
            &self
                .return_bound(editable_program, query_count)?
                .to_le_bytes(),
        );
        Ok(bytes)
    }
}

fn checkpoint_scoring_law_identity(
    scoring: SemanticTaskScoring,
    task_content: SemanticTaskContentIdentity,
    objective_law: SemanticTaskObjectiveLaw,
    training_domain: Option<&SemanticTrainingDomain>,
) -> Identity256 {
    let mut hash = Sha256::new();
    hash.update(b"xlog.semantic.checkpoint.scoring-law.v4\0");
    // Arena transfer advances authority, not the task's content or evaluator.
    // The checkpoint binds that authority separately from this immutable law.
    for identity in [
        task_content.query,
        task_content.theory_program,
        task_content.result,
    ] {
        hash.update(identity.as_bytes());
    }
    for weight in scoring.words() {
        hash.update(weight.to_le_bytes());
    }
    hash.update(objective_law.return_bound.to_le_bytes());
    hash.update(objective_law.structural_cost.unit.as_bytes());
    hash.update(objective_law.structural_cost.cap.to_le_bytes());
    hash.update(objective_law.evaluator_min.to_bits().to_le_bytes());
    hash.update(objective_law.evaluator_max.to_bits().to_le_bytes());
    for coefficient in objective_law.coefficients {
        hash.update(coefficient.to_bits().to_le_bytes());
    }
    hash.update([u8::from(training_domain.is_some())]);
    if let Some(domain) = training_domain {
        hash.update(domain.identity().as_bytes());
    }
    Identity256::from_bytes(hash.finalize().into())
}

#[cfg(feature = "semantic-policy")]
#[expect(
    clippy::too_many_arguments,
    reason = "completed scoring checks independent task, work, refusal, and result fields"
)]
fn validate_completed_task_scoring(
    scoring: SemanticTaskScoring,
    editable_program: bool,
    queries: u32,
    priority_levels: &[SemanticTaskPriorityLevel],
    facts: &[SemanticTaskFacts; 3],
    work: &[SemanticTransitionWork; 2],
    lane_refusal: [u64; 2],
    query_count: u64,
    winner: u64,
    return_value: i64,
) -> bool {
    if scoring.validate(editable_program, queries).is_err()
        || query_count > 3 * u64::from(queries)
        || winner > 2
        || lane_refusal.iter().any(|&refusal| refusal > 4)
        || (!editable_program && lane_refusal.iter().any(|&refusal| refusal >= 3))
        || work
            .iter()
            .any(|work| !work.is_valid(editable_program, queries))
        || facts
            .iter()
            .any(|facts| facts.g > u64::from(queries) || facts.p > 1 || facts.eligible > 1)
    {
        return false;
    }
    for (slot, facts) in facts.iter().enumerate() {
        let measured = if slot == 0 {
            0
        } else {
            let work = work[slot - 1];
            work.raw_structural_cost()
        };
        let value = i128::from(scoring.correct_weight) * i128::from(facts.g)
            + i128::from(scoring.all_correct_weight) * i128::from(facts.p)
            - i128::from(scoring.work_weight) * i128::from(measured);
        if facts.c != measured || i128::from(facts.v) != value {
            return false;
        }
    }
    let mut selected = 0;
    for slot in 1..3 {
        if facts[slot].eligible == 1
            && (facts[selected].eligible == 0
                || task_candidate_better(priority_levels, facts, slot, selected))
        {
            selected = slot;
        }
    }
    if winner as usize != selected || facts[selected].eligible != 1 {
        return false;
    }
    let refusals = lane_refusal.iter().filter(|&&refusal| refusal != 0).count() as i128;
    let spent = i128::from(query_count)
        + work
            .iter()
            .enumerate()
            .filter(|(lane, _)| lane + 1 != selected)
            .map(|(_, work)| i128::from(work.edit_commands + work.defined_truth_changes))
            .sum::<i128>();
    let expected_return = i128::from(scoring.improvement_weight)
        * (i128::from(facts[selected].v) - i128::from(facts[0].v))
        - i128::from(scoring.refusal_weight) * refusals
        - i128::from(scoring.spent_weight) * spent;
    i128::from(return_value) == expected_return
}

#[cfg(feature = "semantic-policy")]
fn task_candidate_better(
    priority_levels: &[SemanticTaskPriorityLevel],
    facts: &[SemanticTaskFacts; 3],
    candidate: usize,
    incumbent: usize,
) -> bool {
    for level in priority_levels {
        let score = |slot: usize| -> i64 {
            level
                .goals
                .iter()
                .map(|goal| {
                    let query = goal.query as usize;
                    let target = u64::from(goal.target_truth);
                    let achieved = if facts[slot].correct.is_none() {
                        facts[slot].attained.get(query).copied().unwrap_or(0) as i64
                    } else {
                        i64::from(facts[slot].truth[query] == target)
                    };
                    let base = if facts[0].correct.is_none() {
                        facts[0].attained.get(query).copied().unwrap_or(0) as i64
                    } else {
                        i64::from(facts[0].truth[query] == target)
                    };
                    i64::from(goal.weight) * (achieved - base)
                })
                .sum()
        };
        let candidate_score = score(candidate);
        let incumbent_score = score(incumbent);
        if candidate_score != incumbent_score {
            return candidate_score > incumbent_score;
        }
    }
    facts[candidate].g > facts[incumbent].g
        || (facts[candidate].g == facts[incumbent].g && facts[candidate].c < facts[incumbent].c)
}

/// The complete nonempty ordered query selection for a retained task. Predicate,
/// arguments, observer program, eligibility, and scoring are application inputs.
/// This specification carries no authority; only the application controller may
/// attach an authorized task to its retained semantic session.
#[derive(Clone, Debug)]
pub struct SemanticTaskEvaluationSpec {
    pub rule_library: Option<Arc<SemanticEvaluationRuleLibrary>>,
    pub evaluation_intervention: Option<SemanticEvaluationIntervention>,
    /// Original statement records in the retained admission, in observer order.
    pub statement_records: Vec<u32>,
    /// Original logical/reference or coding/verification ground, fixed before draw.
    pub task_ground: SemanticTaskGround,
    /// Admitted support records, each retaining its original statement association.
    pub allowed_support_records: Vec<u32>,
    pub program: Arc<dyn SemanticTaskProgram>,
    pub scoring: SemanticTaskScoring,
    /// Ordered, task-local lexicographic levels; an explicit empty list leaves
    /// predictive agreement and measured cost as the selection cascade.
    pub priority_levels: Vec<SemanticTaskPriorityLevel>,
    /// Bit n permits Truth4 value n for the corresponding candidate query.
    pub admissible_truth_masks: Vec<u8>,
    /// Application-owned ex-ante decision that this episode may contribute an
    /// actor term. It is frozen with the task before any action draw.
    pub actor_eligible: bool,
    /// Original sealed inputs and complete loader geometry, fixed before draw.
    /// None denotes a task with no prospective training arena, not a fallback
    /// domain: subsequent training admission requires an original Some binding.
    pub training_domain: Option<SemanticTrainingDomain>,
}

/// Owner-validated cold read coverage for a task's queried semantic heads.
/// These records grant no use or mutation rights and are not current device
/// query receipts. Runtime feedback must still establish its actual live view.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct SemanticTaskObservationRoots {
    /// Logical root whose canonical insertion material was inspected.
    pub root_digest: Identity256,
    pub root_extents: [u32; 3],
    /// Original admitted query selections, retaining their order.
    pub query_records: Vec<u32>,
    /// Query ordinal, genuine original insertion target (absent for a derived
    /// target), and its original admitted or authenticated support. Ordered by
    /// query, then insertion.
    /// A matching query value never supplies an absent original target.
    pub contributors: Vec<(
        u32,
        Option<u32>,
        crate::semantic_hypergraph::SemanticRootSupport,
    )>,
}

/// The original observation output and the same-pool storage acquired before it.
pub struct SemanticTaskObservationRootsOwner {
    roots: SemanticTaskObservationRoots,
    allocation: SemanticReplayMaterialReservation,
}

impl SemanticTaskObservationRootsOwner {
    pub fn roots(&self) -> &SemanticTaskObservationRoots {
        &self.roots
    }

    pub fn material_budget(&self) -> &SemanticReplayMaterialBudget {
        self.allocation.budget()
    }

    fn reserve_lineage(
        admission: &SemanticAdmission,
        insertions: usize,
        budget: &SemanticReplayMaterialBudget,
    ) -> Result<
        (
            SemanticReplayMaterialReservation,
            SemanticReplayMaterialReservation,
            SemanticReplayMaterialReservation,
            SemanticReplayMaterialReservation,
        ),
        SemanticTransitionError,
    > {
        let records = budget.reserve_admission_records(admission.records())?;
        let symbol_bytes =
            crate::semantic_hypergraph::semantic_material_symbols_allocation_bound(admission)
                .map_err(SemanticTransitionError::Semantic)?;
        let symbols = budget.reserve_auxiliary(
            u64::try_from(symbol_bytes)
                .map_err(|_| SemanticTransitionError::GenerationExhausted)?,
        )?;
        let heads = budget.reserve_ordered_index::<[u8; 32], ([u8; 32], u64)>(insertions)?;
        let supports = budget.reserve_ordered_index::<([u8; 32], [u8; 32]), ()>(insertions)?;
        Ok((records, symbols, heads, supports))
    }

    fn observe(
        material: &crate::semantic_hypergraph::SemanticRootMaterial,
        admission: &SemanticAdmission,
        queries: &[u32],
        budget: &SemanticReplayMaterialBudget,
    ) -> Result<Self, SemanticTransitionError> {
        let lineage = Self::reserve_lineage(admission, material.insertions.len(), budget)?;
        let (roots, allocation) = material.task_observation_roots_with_allocations(
            admission,
            queries,
            lineage,
            |contributors, queries| {
                let output_bytes = contributors
                    .checked_mul(size_of::<(
                        u32,
                        Option<u32>,
                        crate::semantic_hypergraph::SemanticRootSupport,
                    )>())
                    .and_then(|bytes| {
                        queries
                            .checked_mul(size_of::<u32>())
                            .and_then(|queries| bytes.checked_add(queries))
                    })
                    .ok_or(SemanticTransitionError::GenerationExhausted)?;
                budget.reserve_auxiliary(
                    u64::try_from(output_bytes)
                        .map_err(|_| SemanticTransitionError::GenerationExhausted)?,
                )
            },
            SemanticTransitionError::Semantic,
        )?;
        Ok(Self { roots, allocation })
    }
}

/// Native seal of the independently validated goal authority carried by the
/// controller. The semantic root is the exact XLOG root inspected for the task;
/// the remaining roots bind the complete mandatory dependency and constraint
/// closures. These values are derived by the trusted controller after its
/// closure checks, never supplied by the model-update consumer.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct SemanticTaskGoalWitness {
    pub semantic_root: Identity256,
    pub authority_root: Identity256,
    pub mandatory_links_root: Identity256,
    pub constraints_root: Identity256,
    pub mandatory_link_count: u64,
    pub constraint_count: u64,
}

impl SemanticTaskEvaluationSpec {
    fn validate_records(
        &self,
        records: &SemanticAdmissionRecords,
    ) -> Result<(), SemanticTransitionError> {
        let invalid = |detail: &str| SemanticTransitionError::InvalidInput {
            detail: format!("task binding: {detail}"),
        };
        let query_count = self.statement_records.len();
        let query_count_u32 = u32::try_from(query_count)
            .map_err(|_| invalid("query roster exceeds the original record-index domain"))?;
        if query_count == 0 || self.admissible_truth_masks.len() != query_count {
            return Err(invalid(
                "query roster and truth-mask geometry differ from the admission",
            ));
        }
        self.scoring
            .validate(self.program.editable_program().is_some(), query_count_u32)?;
        self.task_ground
            .validate(records, &self.statement_records)?;
        if let Some(domain) = &self.training_domain {
            domain.validate()?;
        }
        if self.priority_levels.len() > query_count {
            return Err(invalid("task priorities exceed the original query roster"));
        }
        let mut seen_queries = vec![false; query_count];
        let mut goal_count = 0usize;
        for level in &self.priority_levels {
            if level.goals.is_empty() {
                return Err(invalid("task priority level must contain a goal"));
            }
            goal_count += level.goals.len();
            if goal_count > query_count {
                return Err(invalid("task priorities exceed the original query roster"));
            }
            for goal in &level.goals {
                let query = goal.query as usize;
                if query >= query_count || goal.target_truth > 3 || goal.weight == 0 {
                    return Err(invalid(
                        "task priority goal has invalid query, truth or weight",
                    ));
                }
                if std::mem::replace(&mut seen_queries[query], true) {
                    return Err(invalid("task priority query appears more than once"));
                }
                if self.admissible_truth_masks[query] & (1 << goal.target_truth) == 0 {
                    return Err(invalid(
                        "task priority target is forbidden by hard truth mask",
                    ));
                }
            }
        }
        if self.task_ground.code() == 1 && seen_queries.iter().any(|seen| !seen) {
            return Err(invalid(
                "coding attainment requires an explicit target for every query",
            ));
        }
        if self
            .admissible_truth_masks
            .iter()
            .any(|mask| *mask == 0 || *mask & !15 != 0)
        {
            return Err(invalid(
                "truth eligibility requires a nonempty four-valued mask",
            ));
        }
        for &index in &self.statement_records {
            let record = records
                .records
                .get(index as usize)
                .ok_or_else(|| invalid("query statement is outside the admission"))?;
            let predicate = records
                .predicates
                .iter()
                .find(|predicate| predicate.predicate == record.predicate)
                .ok_or_else(|| invalid("query predicate is outside the admission"))?;
            if predicate.role != SemanticRecordRole::Statement {
                return Err(invalid("query selection is not a statement"));
            }
        }
        if self.allowed_support_records.len() > records.supports.len() {
            return Err(invalid(
                "support selections exceed the admitted support bank",
            ));
        }
        for &index in &self.allowed_support_records {
            let support = records
                .supports
                .get(index as usize)
                .ok_or_else(|| invalid("support selection is outside the admission"))?;
            if !self.statement_records.contains(&support.statement) {
                return Err(invalid(
                    "support belongs to a statement outside the task scope",
                ));
            }
        }
        Ok(())
    }
}

fn feedback_statement_payload(
    records: &SemanticAdmissionRecords,
    encoded: &[crate::semantic_hypergraph::SemanticRecordEncoding],
    record: u32,
) -> Result<Vec<u8>, SemanticTransitionError> {
    let statement = records
        .records
        .get(record as usize)
        .ok_or(SemanticTransitionError::InvalidTaskBank)?;
    let mut payload = Vec::new();
    let append = |payload: &mut Vec<u8>, index: u32| -> Result<(), SemanticTransitionError> {
        let atom = encoded
            .get(index as usize)
            .ok_or(SemanticTransitionError::InvalidTaskBank)?;
        // Canonical admission retains exact argument ranges. The predicate and
        // arity occupy the eight bytes immediately before the first argument;
        // zero-argument atoms end immediately after those same two u32 values.
        // No symbol lookup, numeric conversion, domain or digest enters features.
        let argument_begin = atom
            .arguments
            .first()
            .map_or(atom.bytes.len(), |range| range.start);
        let value_begin = argument_begin
            .checked_sub(8)
            .ok_or(SemanticTransitionError::InvalidTaskBank)?;
        let values = atom
            .bytes
            .get(value_begin..)
            .ok_or(SemanticTransitionError::InvalidTaskBank)?;
        payload.extend_from_slice(&(values.len() as u64).to_le_bytes());
        payload.extend_from_slice(values);
        Ok(())
    };
    append(&mut payload, record)?;
    let qualifier_count = u32::try_from(statement.qualifiers.len())
        .map_err(|_| SemanticTransitionError::InvalidTaskBank)?;
    payload.extend_from_slice(&qualifier_count.to_le_bytes());
    for &qualifier in &statement.qualifiers {
        append(&mut payload, qualifier)?;
    }
    Ok(payload)
}

/// Immutable native task content, separate from the controller's authority and
/// from every operand visible to the proposal policy.
pub(crate) struct TaskEvaluationBinding {
    admission_identity: Identity256,
    schema_generation: Identity256,
    spec: SemanticTaskEvaluationSpec,
    statements: Vec<crate::SemanticStatementKey>,
    statement_bytes: BTreeMap<u32, Vec<u8>>,
    observation_statements: Vec<(crate::SemanticStatementKey, crate::SemanticProgramFact)>,
    allowed_supports: Vec<(u32, [u8; 32])>,
    observation: SemanticTaskObservation,
    goal_witness: Option<SemanticTaskGoalWitness>,
    objective_law: SemanticTaskObjectiveLaw,
    _requirement_allocation: Option<SemanticReplayMaterialReservation>,
}

type TaskContentSelection = (
    Vec<crate::SemanticStatementKey>,
    BTreeMap<u32, Vec<u8>>,
    Vec<(u32, [u8; 32])>,
);

fn task_content_selection(
    admission: &SemanticAdmission,
    statement_records: &[u32],
    allowed_support_records: &[u32],
) -> Result<TaskContentSelection, SemanticTransitionError> {
    let statements = statement_records.iter().map(|&record| {
        admission
            .statement_key(record)
            .map_err(SemanticTransitionError::Semantic)
    });
    let statements = statements.into_iter().collect::<Result<Vec<_>, _>>()?;
    let mut statement_bytes = BTreeMap::new();
    for &record in statement_records {
        statement_bytes.insert(
            record,
            feedback_statement_payload(admission.records(), &admission.encoded_records, record)?,
        );
    }
    let mut allowed_supports = BTreeSet::new();
    for &index in allowed_support_records {
        let record = admission
            .records()
            .supports
            .get(index as usize)
            .ok_or(SemanticTransitionError::InvalidTaskBank)?;
        if !statement_records.contains(&record.statement) {
            return Err(SemanticTransitionError::InvalidTaskBank);
        }
        let statement = admission
            .statement_key(record.statement)
            .map_err(SemanticTransitionError::Semantic)?;
        let event = admission
            .support_event(index)
            .map_err(SemanticTransitionError::Semantic)?;
        allowed_supports.insert((index, *event.identity(statement.identity()).as_bytes()));
    }
    Ok((
        statements,
        statement_bytes,
        allowed_supports.into_iter().collect(),
    ))
}

#[expect(
    clippy::too_many_arguments,
    reason = "task content identity binds independent admitted and observed materials"
)]
fn task_content_identity(
    admission_identity: Identity256,
    schema_generation: Identity256,
    statement_records: &[u32],
    statements: &[crate::SemanticStatementKey],
    statement_bytes: &BTreeMap<u32, Vec<u8>>,
    allowed_supports: &[(u32, [u8; 32])],
    observation: &SemanticTaskObservation,
    editable: Option<&crate::SemanticProgramAdmission>,
    task_ground: &SemanticTaskGround,
    rule_library: Option<&SemanticEvaluationRuleLibrary>,
) -> SemanticTaskContentIdentity {
    let append_bytes = |hash: &mut Sha256, bytes: &[u8]| {
        hash.update((bytes.len() as u64).to_le_bytes());
        hash.update(bytes);
    };

    let mut query = Sha256::new();
    query.update(b"xlog.semantic.task-query.v1\0");
    query.update((statement_records.len() as u64).to_le_bytes());
    for (record, statement) in statement_records.iter().zip(statements) {
        query.update(record.to_le_bytes());
        query.update(statement.identity().as_bytes());
        append_bytes(
            &mut query,
            statement_bytes
                .get(record)
                .expect("bound query statement retains canonical bytes"),
        );
    }
    append_bytes(&mut query, &observation.input_bytes);
    let query = Identity256::from_bytes(query.finalize().into());

    let mut theory_program = Sha256::new();
    theory_program.update(b"xlog.semantic.task-theory-program.v1\0");
    theory_program.update(admission_identity.as_bytes());
    theory_program.update(schema_generation.as_bytes());
    theory_program.update(b"xlog.semantic.task-ground.v2\0");
    theory_program.update(task_ground.code().to_le_bytes());
    if let Some(library) = rule_library {
        theory_program.update(b"xlog.semantic.frozen-rule-library.v1\0");
        theory_program.update(library.digest().as_bytes());
        theory_program.update(library.binding().as_bytes());
    }
    theory_program.update((task_ground.bindings().len() as u64).to_le_bytes());
    for binding in task_ground.bindings() {
        for word in binding.words() {
            theory_program.update(word.to_le_bytes());
        }
    }
    task_ground.visit_requirement_words(|word| theory_program.update(word.to_le_bytes()));
    theory_program.update((allowed_supports.len() as u64).to_le_bytes());
    for (record, support) in allowed_supports {
        theory_program.update(record.to_le_bytes());
        theory_program.update(support);
    }
    append_bytes(&mut theory_program, &observation.program_source);
    if let Some(editable) = editable {
        theory_program.update(b"xlog.semantic.editable-program.v1\0");
        for word in editable.words() {
            theory_program.update(word.to_le_bytes());
        }
    }
    let theory_program = Identity256::from_bytes(theory_program.finalize().into());

    let mut result = Sha256::new();
    result.update(b"xlog.semantic.task-four-valued-result.v1\0");
    result.update(query.as_bytes());
    result.update(theory_program.as_bytes());
    append_bytes(&mut result, &observation.result_bytes);
    for &truth in &observation.actual_truths {
        result.update((truth as u64).to_le_bytes());
    }

    SemanticTaskContentIdentity {
        query,
        theory_program,
        result: Identity256::from_bytes(result.finalize().into()),
    }
}

impl TaskEvaluationBinding {
    pub(crate) fn bind(
        admission: &SemanticAdmission,
        spec: SemanticTaskEvaluationSpec,
        observation: SemanticTaskObservation,
    ) -> Result<Self, SemanticTransitionError> {
        spec.validate_records(admission.records())?;
        if let Some(program) = spec.program.editable_program() {
            program
                .validate()
                .map_err(|detail| SemanticTransitionError::InvalidInput {
                    detail: format!("task binding: {detail}"),
                })?;
        }
        let (statements, statement_bytes, allowed_supports) = task_content_selection(
            admission,
            &spec.statement_records,
            &spec.allowed_support_records,
        )?;
        let observation_statements = spec
            .task_ground
            .bindings()
            .iter()
            .map(|binding| {
                let statement = admission
                    .statement_key(binding.observation_record)
                    .map_err(SemanticTransitionError::Semantic)?;
                let fact = spec
                    .program
                    .editable_program()
                    .and_then(|program| {
                        program
                            .observation_facts
                            .iter()
                            .find(|(record, _)| *record == binding.observation_record)
                    })
                    .map(|(_, fact)| *fact)
                    .ok_or_else(|| {
                        publication_input_error(
                    "protected observation statement is absent from its original compiled source")
                    })?;
                Ok((statement, fact))
            })
            .collect::<Result<Vec<_>, SemanticTransitionError>>()?;
        if observation.program_source.is_empty()
            || observation.result_bytes.is_empty()
            || observation.actual_truths.len() != spec.statement_records.len()
            || spec
                .program
                .editable_program()
                .is_some_and(|program| program.query_records != spec.statement_records)
        {
            return Err(publication_input_error(
                "native task observer omitted source or result custody",
            ));
        }
        let objective_law = spec.scoring.objective_law(
            spec.program.editable_program().is_some(),
            spec.statement_records.len() as u32,
        )?;
        Ok(Self {
            admission_identity: admission.identity(),
            schema_generation: admission.schema_generation(),
            spec,
            statements,
            statement_bytes,
            observation_statements,
            allowed_supports,
            observation,
            goal_witness: None,
            objective_law,
            _requirement_allocation: None,
        })
    }

    pub(crate) fn identity(&self) -> Identity256 {
        self.identity_with_intervention(self.spec.evaluation_intervention)
    }

    fn identity_with_intervention(
        &self,
        intervention: Option<SemanticEvaluationIntervention>,
    ) -> Identity256 {
        let mut hash = Sha256::new();
        hash.update(if self.spec.program.editable_program().is_some() {
            b"xlog.semantic.task-evaluation.v12\0".as_slice()
        } else {
            b"xlog.semantic.task-evaluation.v11\0".as_slice()
        });
        hash.update(self.admission_identity.as_bytes());
        hash.update(self.schema_generation.as_bytes());
        hash.update(b"xlog.semantic.rule-control.v1\0");
        hash.update([u8::from(intervention.is_some())]);
        hash.update(
            (intervention.unwrap_or(SemanticEvaluationIntervention::Structural) as u64)
                .to_le_bytes(),
        );
        if let Some(library) = &self.spec.rule_library {
            hash.update(library.digest().as_bytes());
            hash.update(library.binding().as_bytes());
        }
        // Keep source occurrence and explicit selection order separate from
        // the distinct original support records consumed by the device policy.
        hash.update((self.spec.statement_records.len() as u64).to_le_bytes());
        for index in &self.spec.statement_records {
            hash.update(index.to_le_bytes());
        }
        hash.update((self.spec.allowed_support_records.len() as u64).to_le_bytes());
        for index in &self.spec.allowed_support_records {
            hash.update(index.to_le_bytes());
        }
        hash.update((self.observation.program_source.len() as u64).to_le_bytes());
        hash.update(&self.observation.program_source);
        hash.update((self.observation.input_bytes.len() as u64).to_le_bytes());
        hash.update(&self.observation.input_bytes);
        hash.update((self.observation.result_bytes.len() as u64).to_le_bytes());
        hash.update(&self.observation.result_bytes);
        for &truth in &self.observation.actual_truths {
            hash.update((truth as u64).to_le_bytes());
        }
        hash.update(&self.spec.admissible_truth_masks);
        hash.update(b"xlog.semantic.task-ground.v2\0");
        hash.update(self.spec.task_ground.code().to_le_bytes());
        hash.update((self.spec.task_ground.bindings().len() as u64).to_le_bytes());
        for binding in self.spec.task_ground.bindings() {
            for word in binding.words() {
                hash.update(word.to_le_bytes());
            }
        }
        self.spec
            .task_ground
            .visit_requirement_words(|word| hash.update(word.to_le_bytes()));
        hash.update([u8::from(self.spec.actor_eligible)]);
        for weight in self.spec.scoring.words() {
            hash.update(weight.to_le_bytes());
        }
        // Checkpoint task/scoring identities retain these cold numerical bits.
        // Restore must reproduce them before an arena or publication is usable.
        hash.update(self.objective_law.evaluator_min.to_bits().to_le_bytes());
        hash.update(self.objective_law.evaluator_max.to_bits().to_le_bytes());
        for coefficient in self.objective_law.coefficients {
            hash.update(coefficient.to_bits().to_le_bytes());
        }
        hash.update(self.objective_law.structural_cost.unit.as_bytes());
        hash.update(self.objective_law.structural_cost.cap.to_le_bytes());
        hash.update([u8::from(self.spec.training_domain.is_some())]);
        if let Some(domain) = &self.spec.training_domain {
            hash.update(domain.identity().as_bytes());
        }
        hash.update(b"xlog.semantic.task-priorities.v1\0");
        hash.update((self.spec.priority_levels.len() as u64).to_le_bytes());
        for level in &self.spec.priority_levels {
            hash.update((level.goals.len() as u64).to_le_bytes());
            for goal in &level.goals {
                hash.update(goal.query.to_le_bytes());
                hash.update([goal.target_truth]);
                hash.update(goal.weight.to_le_bytes());
            }
        }
        if let Some(editable) = self.spec.program.editable_program() {
            hash.update(b"xlog.semantic.editable-program.v1\0");
            editable.visit_words(|word| hash.update(word.to_le_bytes()));
        }
        for statement in &self.statements {
            hash.update(statement.identity().as_bytes());
        }
        for (statement, fact) in &self.observation_statements {
            hash.update(statement.identity().as_bytes());
            hash.update(fact.predicate.to_le_bytes());
            hash.update(fact.arity.to_le_bytes());
            hash.update(fact.first.to_le_bytes());
            hash.update(fact.second.to_le_bytes());
        }
        hash.update((self.allowed_supports.len() as u64).to_le_bytes());
        for (record, support) in &self.allowed_supports {
            hash.update(record.to_le_bytes());
            hash.update(support);
        }
        if let Some(witness) = self.goal_witness {
            hash.update(b"xlog.semantic.goal-witness.v1\0");
            hash.update(witness.semantic_root.as_bytes());
            hash.update(witness.authority_root.as_bytes());
            hash.update(witness.mandatory_links_root.as_bytes());
            hash.update(witness.constraints_root.as_bytes());
            hash.update(witness.mandatory_link_count.to_le_bytes());
            hash.update(witness.constraint_count.to_le_bytes());
        }
        Identity256::from_bytes(hash.finalize().into())
    }

    pub(crate) fn content_identity(&self) -> SemanticTaskContentIdentity {
        task_content_identity(
            self.admission_identity,
            self.schema_generation,
            &self.spec.statement_records,
            &self.statements,
            &self.statement_bytes,
            &self.allowed_supports,
            &self.observation,
            self.spec.program.editable_program(),
            &self.spec.task_ground,
            self.spec.rule_library.as_deref(),
        )
    }

    pub(crate) fn cold_content(
        admission: &SemanticAdmission,
        statement_records: &[u32],
        allowed_support_records: &[u32],
        editable: Option<&crate::SemanticProgramAdmission>,
        observation: SemanticTaskObservation,
        task_ground: &SemanticTaskGround,
        rule_library: Option<&SemanticEvaluationRuleLibrary>,
    ) -> Result<(SemanticTaskContentIdentity, Vec<crate::SemanticTruth>), SemanticTransitionError>
    {
        if observation.program_source.is_empty()
            || observation.result_bytes.is_empty()
            || observation.actual_truths.len() != statement_records.len()
            || statement_records.is_empty()
            || statement_records.len() > u32::MAX as usize
        {
            return Err(publication_input_error(
                "native task observer omitted source or result custody",
            ));
        }
        task_ground.validate(admission.records(), statement_records)?;
        if let Some(program) = editable {
            program
                .validate()
                .map_err(|detail| SemanticTransitionError::InvalidInput {
                    detail: format!("task binding: {detail}"),
                })?;
        }
        let (statements, statement_bytes, allowed_supports) =
            task_content_selection(admission, statement_records, allowed_support_records)?;
        let content = task_content_identity(
            admission.identity(),
            admission.schema_generation(),
            statement_records,
            &statements,
            &statement_bytes,
            &allowed_supports,
            &observation,
            editable,
            task_ground,
            rule_library,
        );
        Ok((content, observation.actual_truths))
    }

    pub(crate) fn expected_truth(&self) -> Option<&[crate::SemanticTruth]> {
        matches!(self.spec.task_ground, SemanticTaskGround::Logical)
            .then_some(self.observation.actual_truths.as_slice())
    }

    #[cfg(feature = "semantic-policy")]
    fn goal_witness(&self) -> Option<SemanticTaskGoalWitness> {
        self.goal_witness
    }

    pub(crate) fn content(&self) -> (SemanticTaskContentIdentity, Vec<crate::SemanticTruth>) {
        (
            self.content_identity(),
            self.observation.actual_truths.clone(),
        )
    }

    #[cfg(feature = "semantic-policy")]
    fn completed_result_material(&self) -> SemanticCompletedStepWitnessMaterial {
        let identities = self.content_identity();
        let mut bytes = Vec::new();
        bytes.extend_from_slice(b"xlog.semantic.task-four-valued-result.v1\0");
        bytes.extend_from_slice(identities.query.as_bytes());
        bytes.extend_from_slice(identities.theory_program.as_bytes());
        material_u64(&mut bytes, self.observation.result_bytes.len() as u64);
        bytes.extend_from_slice(&self.observation.result_bytes);
        for &truth in &self.observation.actual_truths {
            material_u64(&mut bytes, truth as u64);
        }
        SemanticCompletedStepWitnessMaterial {
            identity: identities.result,
            bytes,
        }
    }

    pub(crate) fn spec(&self) -> &SemanticTaskEvaluationSpec {
        &self.spec
    }

    pub(crate) fn priority_levels(&self) -> &[SemanticTaskPriorityLevel] {
        &self.spec.priority_levels
    }

    fn word_count(&self) -> Result<usize, SemanticTransitionError> {
        let mut count = 39usize;
        for (rows, width) in [
            (self.statements.len(), 7usize),
            (self.allowed_supports.len(), 5),
            (self.spec.priority_levels.len(), 1),
            (self.spec.task_ground.bindings().len(), 36),
            (self.observation_statements.len(), 8),
        ] {
            count = rows
                .checked_mul(width)
                .and_then(|words| count.checked_add(words))
                .ok_or(SemanticTransitionError::GenerationExhausted)?;
        }
        for level in &self.spec.priority_levels {
            count = level
                .goals
                .len()
                .checked_mul(3)
                .and_then(|words| count.checked_add(words))
                .ok_or(SemanticTransitionError::GenerationExhausted)?;
        }
        count = count
            .checked_add(self.spec.task_ground.device_requirement_word_count()?)
            .ok_or(SemanticTransitionError::GenerationExhausted)?;
        if let Some(program) = self.spec.program.editable_program() {
            count = program
                .word_count()
                .and_then(|words| count.checked_add(words))
                .ok_or(SemanticTransitionError::GenerationExhausted)?;
        }
        count
            .checked_add(
                self.spec
                    .rule_library
                    .as_ref()
                    .map_or(8, |library| library.word_count()),
            )
            .ok_or(SemanticTransitionError::GenerationExhausted)
    }

    /// The exact-capacity result plus its original requirement encoder and
    /// topological workspaces. Identity/program hashing uses no temporary bank.
    pub(super) fn words_allocation_bytes(&self) -> Result<u64, SemanticTransitionError> {
        self.word_count()?
            .checked_add(self.spec.task_ground.device_requirement_word_count()?)
            .and_then(|words| words.checked_mul(size_of::<u64>()))
            .and_then(|bytes| {
                self.spec
                    .task_ground
                    .requirements()
                    .len()
                    .checked_mul(size_of::<u32>() + size_of::<bool>())
                    .and_then(|workspace| bytes.checked_add(workspace))
            })
            .and_then(|bytes| u64::try_from(bytes).ok())
            .ok_or(SemanticTransitionError::GenerationExhausted)
    }

    pub(crate) fn words(&self, owner: u64) -> Vec<u64> {
        self.words_with_intervention(owner, self.spec.evaluation_intervention)
    }

    fn words_with_intervention(
        &self,
        owner: u64,
        intervention: Option<SemanticEvaluationIntervention>,
    ) -> Vec<u64> {
        let count = self
            .word_count()
            .expect("immutable task binding retains its finite canonical encoding");
        let program = self.spec.program.editable_program();
        let goal_count = self
            .spec
            .priority_levels
            .iter()
            .map(|level| level.goals.len())
            .sum::<usize>();
        let mut words = Vec::with_capacity(count);
        words.extend([10, owner]);
        words.extend(identity_words(
            *self.identity_with_intervention(intervention).as_bytes(),
        ));
        words.extend([
            self.statements.len() as u64,
            self.spec.task_ground.bindings().len() as u64,
            self.spec.task_ground.code(),
            self.allowed_supports.len() as u64,
            self.spec.priority_levels.len() as u64,
            goal_count as u64,
            program.map_or(0, |program| {
                program
                    .word_count()
                    .expect("validated program retains its finite encoding") as u64
            }),
        ]);
        words.extend(self.spec.scoring.words());
        if let Some(witness) = self.goal_witness {
            words.extend(identity_words(*witness.semantic_root.as_bytes()));
            words.extend(identity_words(*witness.authority_root.as_bytes()));
            words.extend(identity_words(*witness.mandatory_links_root.as_bytes()));
            words.extend(identity_words(*witness.constraints_root.as_bytes()));
            words.push(witness.mandatory_link_count);
            words.push(witness.constraint_count);
        } else {
            words.extend([0; 18]);
        }
        words.push(u64::from(self.spec.actor_eligible));
        for (query, statement) in self.statements.iter().enumerate() {
            words.extend(identity_words(*statement.identity().as_bytes()));
            words.extend([
                u64::from(self.spec.statement_records[query]),
                self.observation.actual_truths[query] as u64,
                u64::from(self.spec.admissible_truth_masks[query]),
            ]);
        }
        for (record, support) in &self.allowed_supports {
            words.push(u64::from(*record));
            words.extend(identity_words(*support));
        }
        for level in &self.spec.priority_levels {
            words.push(level.goals.len() as u64);
        }
        for level in &self.spec.priority_levels {
            for goal in &level.goals {
                words.extend([
                    u64::from(goal.query),
                    u64::from(goal.target_truth),
                    u64::from(goal.weight),
                ]);
            }
        }
        for binding in self.spec.task_ground.bindings() {
            words.extend(binding.words());
        }
        for (statement, fact) in &self.observation_statements {
            words.extend(identity_words(*statement.identity().as_bytes()));
            words.extend([
                u64::from(fact.predicate),
                u64::from(fact.arity),
                u64::from(fact.first),
                u64::from(fact.second),
            ]);
        }
        let requirements = self
            .spec
            .task_ground
            .device_requirement_words()
            .expect("immutable task binding retains its validated attainment graph");
        words.push(requirements.len() as u64);
        words.extend(requirements);
        if let Some(program) = program {
            program.visit_words(|word| words.push(word));
        }
        let mode = intervention.unwrap_or(SemanticEvaluationIntervention::Structural);
        if let Some(library) = &self.spec.rule_library {
            library.visit_control_words(mode, |word| words.push(word));
        } else {
            words.extend([
                rule_control::RULE_CONTROL_MAGIC,
                1,
                mode as u64,
                0,
                0,
                0,
                0,
                0,
            ]);
        }
        debug_assert_eq!(words.len(), count);
        words
    }
}

/// One row of the generated roster. Text fields are text positions; edit fields
/// index the eighteen-field action signature. Offsets count input elements.
#[repr(C)]
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct SemanticComponent {
    pub offset: u64,
    pub ordinal: u32,
    pub lane: u32,
    pub slot: u32,
    pub field: u32,
    pub kind: u32,
    pub cardinality: u32,
}

impl SemanticComponent {
    pub const fn is_text(&self) -> bool {
        self.kind == COMPONENT_KIND_TEXT as u32
    }
}

/// Field codebook role and NULL-only cold cardinality in this catalogue.
pub struct SemanticCatalogueField {
    pub ordinal: u32,
    pub cardinality: u32,
    pub name: &'static str,
    pub role: &'static str,
}

/// Declarative action/opcode signature, including dependent opcode selection.
pub struct SemanticCatalogueSignature {
    pub value: u32,
    pub kind: &'static str,
    pub name: &'static str,
    pub signature: &'static str,
}

include!(concat!(
    env!("OUT_DIR"),
    "/semantic_transition_catalogue.rs"
));

pub const SEMANTIC_TRANSITION_GENERATION: u64 = CATALOGUE_GENERATION;
pub const SEMANTIC_TRANSITION_COMPONENT_COUNT: usize = COMPONENT_COUNT;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct SemanticCatalogueBinding {
    pub generation: u64,
    pub digest: Identity256,
}

/// The sole built-in action law; both Rust and CUDA are generated from its declaration.
pub struct SemanticActionCatalogue;

impl SemanticActionCatalogue {
    pub const fn current() -> Self {
        Self
    }
    pub const fn binding(&self) -> SemanticCatalogueBinding {
        SemanticCatalogueBinding {
            generation: CATALOGUE_GENERATION,
            digest: Identity256::from_bytes(CATALOGUE_DIGEST),
        }
    }
    pub const fn canonical_bytes(&self) -> &'static [u8] {
        CATALOGUE_ENCODING
    }
    #[cfg(feature = "semantic-policy")]
    fn completed_material(&self) -> SemanticCompletedStepWitnessMaterial {
        SemanticCompletedStepWitnessMaterial {
            identity: self.binding().digest,
            bytes: self.canonical_bytes().to_vec(),
        }
    }
    pub const fn components(&self) -> &'static [SemanticComponent] {
        COMPONENTS
    }
    pub const fn fields(&self) -> &'static [SemanticCatalogueField] {
        CATALOGUE_FIELDS
    }
    pub const fn signatures(&self) -> &'static [SemanticCatalogueSignature] {
        CATALOGUE_SIGNATURES
    }
    pub const fn text_cardinality(&self) -> usize {
        TEXT_CARDINALITY
    }
    pub const fn scratch_bytes(&self) -> usize {
        SCRATCH_BYTES
    }
    /// (active fields, forced-NULL fields) for NO_EDIT, INSERT_SUPPORT and INSERT_RULE.
    pub const fn field_masks(&self) -> [(u32, u32); 3] {
        [
            (NO_EDIT_ACTIVE_MASK as u32, NO_EDIT_NULL_MASK as u32),
            (
                INSERT_SUPPORT_ACTIVE_MASK as u32,
                INSERT_SUPPORT_NULL_MASK as u32,
            ),
            (INSERT_RULE_ACTIVE_MASK as u32, INSERT_RULE_NULL_MASK as u32),
        ]
    }
}

/// Cold-bound FP32 logits and binary product support in original category order.
pub struct SemanticComponentInput {
    pub logits: Vec<f32>,
    pub product_support: Vec<u8>,
}

/// FP32 element ranges for one field in the native policy parameter snapshot.
/// NULL is a category, but has no stored embedding row. The action-class field
/// has no NULL: its category zero is the trainable no-edit action.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct SemanticPolicyFieldLayout {
    pub embeddings: std::ops::Range<usize>,
    pub biases: std::ops::Range<usize>,
    pub cardinality: usize,
    pub null_category: Option<usize>,
}

/// Packing of the immutable policy inputs consumed by the serial component loop.
/// These ranges describe storage, not authority to substitute a model generation.
/// A session derives the layout from its retained admission's actual codebooks.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct SemanticPolicyLayout {
    pub z: std::ops::Range<usize>,
    pub recurrence: std::ops::Range<usize>,
    pub positions: std::ops::Range<usize>,
    pub fields: Vec<SemanticPolicyFieldLayout>,
    pub parameter_cells: usize,
}

impl SemanticPolicyLayout {
    fn from_components(components: &[SemanticComponent]) -> Result<Self, SemanticTransitionError> {
        let invalid = || SemanticTransitionError::InvalidInput {
            detail: "policy layout requires the complete native component roster".into(),
        };
        if components.len() != COMPONENT_COUNT {
            return Err(invalid());
        }
        let z = 0usize..4 * 128;
        let recurrence = z.end..z.end + 128 * 128;
        let positions = recurrence.end..recurrence.end + 18 * 128;
        let mut cursor = positions.end;
        let mut fields = Vec::with_capacity(18);
        for field in 0..18 {
            let cardinality = components[32 + field].cardinality as usize;
            if cardinality == 0 {
                return Err(invalid());
            }
            for lane in 0..2 {
                for slot in 0..2 {
                    let component = components[lane * 68 + 32 + slot * 18 + field];
                    if component.kind != COMPONENT_KIND_EDIT as u32
                        || component.field as usize != field
                        || component.lane as usize != lane + 1
                        || component.slot as usize != slot
                        || component.cardinality as usize != cardinality
                    {
                        return Err(invalid());
                    }
                }
            }
            let null_category = (field != 0).then_some(0);
            let embedding_cells = (cardinality - usize::from(null_category.is_some()))
                .checked_mul(128)
                .ok_or_else(invalid)?;
            let end = cursor.checked_add(embedding_cells).ok_or_else(invalid)?;
            let embeddings = cursor..end;
            cursor = end;
            let bias_cells = if null_category.is_some() && cardinality == 1 {
                0
            } else {
                cardinality
            };
            let end = cursor.checked_add(bias_cells).ok_or_else(invalid)?;
            let biases = cursor..end;
            cursor = end;
            fields.push(SemanticPolicyFieldLayout {
                embeddings,
                biases,
                cardinality,
                null_category,
            });
        }
        Ok(Self {
            z,
            recurrence,
            positions,
            fields,
            parameter_cells: cursor,
        })
    }

    /// Both lanes retain the initial state and all thirty-six field successors.
    pub const fn recurrent_cells(&self) -> usize {
        2 * 37 * 128
    }

    /// The same score bank is reused serially by every structural component.
    pub fn score_cells(&self) -> usize {
        self.fields
            .iter()
            .map(|field| field.cardinality)
            .max()
            .unwrap_or(0)
    }

    #[cfg(feature = "semantic-policy")]
    fn retained_score_stride(&self) -> usize {
        self.fields.iter().map(|field| field.cardinality).sum()
    }

    #[cfg(feature = "semantic-policy")]
    fn retained_score_cells(&self) -> usize {
        4 * self.retained_score_stride()
    }
}

/// Immutable descriptor meanings derived from the graph's admitted records.
/// Category zero is NULL. Nonzero categories are sorted by logical typed bytes,
/// independent of arena slots and digests. Equal-valued support records retain
/// separate categories, ordered by their original admission index.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum SemanticActionDescriptor {
    Target {
        predicate: xlog_core::RelId,
    },
    Operand {
        scalar_type: xlog_core::ScalarType,
        sort_label: String,
        encoded_value: Vec<u8>,
    },
    QualifierBundle {
        records: Vec<u32>,
    },
    SupportEvent {
        source_record: u32,
    },
    RulePredicate {
        predicate: u32,
        arity: u32,
    },
    RuleVariable {
        index: u32,
    },
}

#[cfg(feature = "semantic-policy")]
struct SemanticDecodedSupportInsertion {
    statement: SemanticStatementIdentity,
    support: SemanticSupportIdentity,
    source_event: u32,
    reconstruction: [u32; 10],
    bytes: Vec<u8>,
}

struct SemanticDecodedRuleInsertion {
    rule: crate::SemanticProgramRule,
    #[cfg(any(feature = "semantic-policy", test))]
    bytes: Vec<u8>,
}

fn semantic_program_rule_words(rule: crate::SemanticProgramRule) -> [u64; 25] {
    rule.words()
}

fn semantic_generated_rule_receipt_words(
    rule: crate::SemanticProgramRule,
    program: &crate::SemanticProgramAdmission,
) -> Result<[u64; 10], SemanticTransitionError> {
    if program.predicate_arities.len() != program.predicate_count as usize
        || rule.body_count != 2
        || rule.body[2] != crate::SemanticProgramAtom::default()
    {
        return Err(SemanticTransitionError::ObservationMismatch);
    }
    for atom in [&rule.head, &rule.body[0], &rule.body[1]] {
        if !(1..=2).contains(&atom.arity)
            || program.predicate_arities.get(atom.predicate as usize) != Some(&atom.arity)
            || atom.terms[..atom.arity as usize]
                .iter()
                .any(|term| term.kind != 0 || term.value >= 4)
            || atom.terms[atom.arity as usize..]
                .iter()
                .any(|term| *term != crate::SemanticProgramTerm::default())
        {
            return Err(SemanticTransitionError::ObservationMismatch);
        }
    }
    let bound = rule.body[..2]
        .iter()
        .flat_map(|atom| &atom.terms[..atom.arity as usize])
        .fold(0u8, |set, term| set | (1 << term.value));
    if rule.head.terms[..rule.head.arity as usize]
        .iter()
        .any(|term| bound & (1 << term.value) == 0)
    {
        return Err(SemanticTransitionError::ObservationMismatch);
    }
    // This projection is lossless only for generated variable rules under the
    // bound predicate declarations. Authored rules retain the full atom words.
    Ok([
        rule.head.predicate,
        rule.body[0].predicate,
        rule.body[1].predicate,
        rule.body_count,
        rule.head.terms[0].value,
        rule.head.terms[1].value,
        rule.body[0].terms[0].value,
        rule.body[0].terms[1].value,
        rule.body[1].terms[0].value,
        rule.body[1].terms[1].value,
    ]
    .map(u64::from))
}

struct ActionCodebooks {
    words: Vec<u64>,
    targets: Vec<SemanticActionDescriptor>,
    operands: Vec<SemanticActionDescriptor>,
    qualifiers: Vec<SemanticActionDescriptor>,
    leaves: Vec<SemanticActionDescriptor>,
    components: Vec<SemanticComponent>,
    binding: SemanticCatalogueBinding,
    program_binding: Option<Identity256>,
    input_cells: usize,
    model_catalogue: Option<(Arc<model_catalogue::FrozenModelCatalogue>, usize)>,
    model_projection_reservation: Option<Arc<SemanticReplayMaterialReservation>>,
    derivation_reservation: Option<Arc<SemanticReplayMaterialReservation>>,
}

impl ActionCodebooks {
    fn local_category(&self, field: u32, category: u32) -> Option<usize> {
        let range = match field {
            2 => 0,
            3..=10 => 1,
            11 => 2,
            17 => 3,
            _ => return None,
        };
        let begin = self.words[29 + 2 * range];
        let end = self.words[30 + 2 * range];
        (u64::from(category) >= begin && u64::from(category) < end)
            .then(|| (u64::from(category) - begin) as usize)
    }

    fn program_binding(program: &crate::SemanticProgramAdmission) -> Identity256 {
        let mut hash = Sha256::new();
        hash.update(b"xlog.semantic.rule-codebook.program.v2\0");
        program.visit_words(|word| hash.update(word.to_le_bytes()));
        Identity256::from_bytes(hash.finalize().into())
    }

    fn decoded_rule_insertion(
        &self,
        program: &crate::SemanticProgramAdmission,
        choices: &[u32; 18],
    ) -> Result<SemanticDecodedRuleInsertion, SemanticTransitionError> {
        if self.program_binding != Some(Self::program_binding(program))
            || choices[0] != 1
            || choices[1] != 2
            || choices[11..].iter().any(|&choice| choice != 0)
        {
            return Err(SemanticTransitionError::ObservationMismatch);
        }
        fn chosen(
            entries: &[SemanticActionDescriptor],
            index: Option<usize>,
        ) -> Result<&SemanticActionDescriptor, SemanticTransitionError> {
            index
                .and_then(|index| entries.get(index as usize))
                .ok_or(SemanticTransitionError::ObservationMismatch)
        }
        let predicate = |entry: &SemanticActionDescriptor| match entry {
            SemanticActionDescriptor::RulePredicate { predicate, arity }
                if (1..=2).contains(arity)
                    && program.predicate_arities.get(*predicate as usize) == Some(arity) =>
            {
                Ok((*predicate, *arity))
            }
            _ => Err(SemanticTransitionError::ObservationMismatch),
        };
        let variable = |entry: &SemanticActionDescriptor| match entry {
            SemanticActionDescriptor::RuleVariable { index } if *index < 4 => Ok(*index),
            _ => Err(SemanticTransitionError::ObservationMismatch),
        };
        let predicates = [
            predicate(chosen(&self.targets, self.local_category(2, choices[2]))?)?,
            predicate(chosen(&self.operands, self.local_category(3, choices[3]))?)?,
            predicate(chosen(&self.operands, self.local_category(4, choices[4]))?)?,
        ];
        let mut rule = crate::SemanticProgramRule {
            body_count: 2,
            ..Default::default()
        };
        for (atom_index, (predicate, arity)) in predicates.into_iter().enumerate() {
            let atom = if atom_index == 0 {
                &mut rule.head
            } else {
                &mut rule.body[atom_index - 1]
            };
            atom.predicate = predicate;
            atom.arity = arity;
            for argument in 0..2 {
                let field = 5 + 2 * atom_index + argument;
                if argument < arity as usize {
                    atom.terms[argument].value = variable(chosen(
                        &self.operands,
                        self.local_category(field as u32, choices[field]),
                    )?)?;
                } else if choices[field] != 0 {
                    return Err(SemanticTransitionError::ObservationMismatch);
                }
            }
        }
        semantic_generated_rule_receipt_words(rule, program)?;
        #[cfg(any(feature = "semantic-policy", test))]
        let bytes = {
            let mut bytes = Vec::new();
            bytes.extend_from_slice(b"XLOG-DECODED-RULE-INSERTION\0");
            material_u64(&mut bytes, 2);
            bytes.extend_from_slice(self.binding.digest.as_bytes());
            bytes.extend_from_slice(Self::program_binding(program).as_bytes());
            for &choice in choices {
                material_u32(&mut bytes, choice);
            }
            for field in semantic_program_rule_words(rule) {
                material_u32(&mut bytes, field as u32);
            }
            bytes
        };
        Ok(SemanticDecodedRuleInsertion {
            rule,
            #[cfg(any(feature = "semantic-policy", test))]
            bytes,
        })
    }

    #[cfg(feature = "semantic-policy")]
    fn decoded_support_insertion(
        &self,
        admission: &SemanticAdmission,
        choices: &[u32; 18],
    ) -> Result<Option<SemanticDecodedSupportInsertion>, SemanticTransitionError> {
        if choices[0] == 0 {
            return Ok(None);
        }
        if choices[0] != 1 || choices[1] != 1 {
            return Err(SemanticTransitionError::ObservationMismatch);
        }
        let chosen = |field: u32, count: usize, choice: u32| {
            self.local_category(field, choice)
                .filter(|&index| index < count)
                .ok_or(SemanticTransitionError::ObservationMismatch)
        };
        let target = chosen(2, self.targets.len(), choices[2])?;
        let predicate = match self.targets[target] {
            SemanticActionDescriptor::Target { predicate } => predicate,
            _ => return Err(SemanticTransitionError::ObservationMismatch),
        };
        let arity = admission
            .records()
            .predicates
            .iter()
            .find(|entry| entry.predicate == predicate)
            .ok_or(SemanticTransitionError::ObservationMismatch)?
            .schema
            .arity();
        let mut reconstruction = [0u32; 10];
        reconstruction[0] = predicate.0;
        for argument in 0..arity {
            let choice = choices[3 + argument];
            chosen(3 + argument as u32, self.operands.len(), choice)?;
            let offset = self.words[2] as usize + 6 * choice as usize;
            reconstruction[1 + 2 * argument] = self.words[offset + 4] as u32;
            reconstruction[2 + 2 * argument] = self.words[offset + 5] as u32;
        }
        let qualifier = choices[11];
        chosen(11, self.qualifiers.len(), qualifier)?;
        reconstruction[9] = self.words[self.words[4] as usize + 3 * qualifier as usize + 2] as u32;
        let leaf = chosen(17, self.leaves.len(), choices[17])?;
        let source_event = match self.leaves[leaf] {
            SemanticActionDescriptor::SupportEvent { source_record } => source_record,
            _ => return Err(SemanticTransitionError::ObservationMismatch),
        };
        let statement = material_statement_key(admission, None, &reconstruction)
            .map_err(SemanticTransitionError::Semantic)?
            .identity();
        let support = admission
            .support_event(source_event)
            .map_err(SemanticTransitionError::Semantic)?
            .identity(statement);
        let mut bytes = Vec::new();
        bytes.extend_from_slice(b"XLOG-DECODED-SUPPORT-INSERTION\0");
        material_u64(&mut bytes, 1);
        bytes.extend_from_slice(self.binding.digest.as_bytes());
        for &choice in choices {
            material_u32(&mut bytes, choice);
        }
        bytes.extend_from_slice(statement.as_bytes());
        bytes.extend_from_slice(support.as_bytes());
        material_u32(&mut bytes, source_event);
        for reference in reconstruction {
            material_u32(&mut bytes, reference);
        }
        Ok(Some(SemanticDecodedSupportInsertion {
            statement,
            support,
            source_event,
            reconstruction,
            bytes,
        }))
    }

    #[cfg(feature = "semantic-policy")]
    fn completed_material(&self) -> SemanticCompletedStepWitnessMaterial {
        SemanticCompletedStepWitnessMaterial {
            identity: self.binding.digest,
            bytes: publication_abi_bytes(&self.words),
        }
    }

    #[cfg(feature = "semantic-policy")]
    fn completed_roster_material(&self) -> SemanticCompletedStepWitnessMaterial {
        let mut bytes = Vec::with_capacity(
            b"xlog.semantic-action-roster.v1\0".len() + 32 + 8 + self.components.len() * 7 * 8,
        );
        bytes.extend_from_slice(b"xlog.semantic-action-roster.v1\0");
        bytes.extend_from_slice(self.binding.digest.as_bytes());
        material_u64(&mut bytes, self.components.len() as u64);
        for component in &self.components {
            for value in [
                component.offset,
                component.ordinal as u64,
                component.lane as u64,
                component.slot as u64,
                component.field as u64,
                component.kind as u64,
                component.cardinality as u64,
            ] {
                material_u64(&mut bytes, value);
            }
        }
        SemanticCompletedStepWitnessMaterial {
            identity: Identity256::from_bytes(Sha256::digest(&bytes).into()),
            bytes,
        }
    }

    fn support_layout(&self) -> (Vec<std::ops::Range<usize>>, usize) {
        (
            self.components
                .iter()
                .map(|component| {
                    component.offset as usize
                        ..component.offset as usize + component.cardinality as usize
                })
                .collect(),
            self.input_cells,
        )
    }

    fn derive(
        admission: &SemanticAdmission,
        owner: u64,
        program: Option<&crate::SemanticProgramAdmission>,
    ) -> Result<Self, SemanticTransitionError> {
        if let Some(program) = program {
            program
                .validate()
                .map_err(|detail| SemanticTransitionError::InvalidInput {
                    detail: detail.into(),
                })?;
        }
        let records = admission.records();
        let predicates: BTreeMap<_, _> = records
            .predicates
            .iter()
            .map(|p| (p.predicate.0, p))
            .collect();
        let sorts: BTreeSet<_> = records
            .predicates
            .iter()
            .flat_map(|p| p.schema.sort_labels().iter().cloned())
            .collect();
        let sorts: BTreeMap<_, _> = sorts
            .into_iter()
            .enumerate()
            .map(|(i, s)| (s, i as u64 + 1))
            .collect();
        let mut targets = BTreeMap::new();
        for p in predicates
            .values()
            .filter(|p| p.role == SemanticRecordRole::Statement && p.schema.arity() <= 4)
        {
            let mut row = vec![p.predicate.0 as u64, p.schema.arity() as u64];
            row.extend((0..4).map(|i| {
                p.schema
                    .columns
                    .get(i)
                    .map_or(0, |(_, t)| t.to_code() as u64 + 1)
            }));
            row.extend((0..4).map(|i| p.schema.sort_labels().get(i).map_or(0, |s| sorts[s])));
            targets.insert(
                p.predicate.0.to_le_bytes(),
                (
                    row,
                    SemanticActionDescriptor::Target {
                        predicate: p.predicate,
                    },
                ),
            );
        }
        let mut operands = BTreeMap::new();
        for (record_index, (record, encoded)) in records
            .records
            .iter()
            .zip(&admission.encoded_records)
            .enumerate()
        {
            let schema = &predicates[&record.predicate.0].schema;
            for (i, range) in encoded.arguments.iter().enumerate() {
                let value = encoded.bytes[range.clone()].to_vec();
                let label = &schema.sort_labels()[i];
                let mut key = value.clone();
                key.extend_from_slice(&(label.len() as u64).to_le_bytes());
                key.extend_from_slice(label.as_bytes());
                operands.entry(key).or_insert_with(|| {
                    (
                        value.clone(),
                        schema.columns[i].1.to_code() as u64 + 1,
                        sorts[label],
                        record_index as u64,
                        i as u64,
                        SemanticActionDescriptor::Operand {
                            scalar_type: schema.columns[i].1,
                            sort_label: label.clone(),
                            encoded_value: value,
                        },
                    )
                });
            }
        }
        let logical = |indices: &[u32]| {
            let mut bytes = (indices.len() as u32).to_le_bytes().to_vec();
            for &index in indices {
                let atom = &admission.encoded_records[index as usize].bytes;
                bytes.extend_from_slice(&(atom.len() as u64).to_le_bytes());
                bytes.extend_from_slice(atom);
            }
            bytes
        };
        let mut qualifiers = BTreeMap::new();
        qualifiers.insert(logical(&[]), (Vec::new(), u32::MAX));
        for (index, record) in records.records.iter().enumerate() {
            if predicates[&record.predicate.0].role == SemanticRecordRole::Statement {
                qualifiers
                    .entry(logical(&record.qualifiers))
                    .or_insert_with(|| (record.qualifiers.clone(), index as u32));
            }
        }
        let mut leaves = BTreeMap::new();
        for (index, support) in records.supports.iter().enumerate() {
            let polarity = match support.polarity {
                crate::SemanticPolarity::Pro => 1u64,
                crate::SemanticPolarity::Contra => 2,
            };
            let refs = [
                support.provenance,
                support.source,
                support.context,
                support.scope,
            ];
            let mut key = polarity.to_le_bytes().to_vec();
            key.extend(logical(&refs));
            let mut words = vec![polarity];
            for record in refs {
                words.extend(identity_words(
                    Sha256::digest(&admission.encoded_records[record as usize].bytes).into(),
                ));
            }
            words.push(index as u64);
            leaves.insert(
                (key, index),
                (
                    words,
                    SemanticActionDescriptor::SupportEvent {
                        source_record: index as u32,
                    },
                ),
            );
        }
        let additional_targets = program
            .map(|program| program.predicate_count as usize)
            .unwrap_or(0);
        let additional_operands = program
            .map(|program| program.predicate_count as usize + 4)
            .unwrap_or(0);
        if [
            targets.len().saturating_add(additional_targets),
            operands.len().saturating_add(additional_operands),
            qualifiers.len(),
            leaves.len(),
        ]
        .into_iter()
        .any(|n| n >= 65536)
        {
            return Err(SemanticTransitionError::InvalidInput {
                detail: "descriptor codebook exceeds 65535 non-NULL entries".into(),
            });
        }
        let mut words = vec![0; model_catalogue::HEADER_WORDS];
        let mut bytes = Vec::new();
        words[0] = words.len() as u64;
        words[1] = (targets.len() + additional_targets) as u64 + 1;
        words.extend([0; 10]);
        let mut target_views: Vec<SemanticActionDescriptor> = targets
            .into_values()
            .map(|(row, view)| {
                words.extend(row);
                view
            })
            .collect();
        if let Some(program) = program {
            for predicate in 0..program.predicate_count {
                let arity = program.predicate_arities[predicate as usize];
                words.extend([
                    u64::from(predicate),
                    u64::MAX,
                    u64::from(arity),
                    0,
                    0,
                    0,
                    0,
                    0,
                    0,
                    0,
                ]);
                target_views.push(SemanticActionDescriptor::RulePredicate { predicate, arity });
            }
        }
        words[2] = words.len() as u64;
        words[3] = (operands.len() + additional_operands) as u64 + 1;
        words.extend([0; 6]);
        let mut operand_views: Vec<SemanticActionDescriptor> = operands
            .into_values()
            .map(|(value, ty, sort, record, argument, view)| {
                words.extend([
                    bytes.len() as u64,
                    value.len() as u64,
                    ty,
                    sort,
                    record,
                    argument,
                ]);
                bytes.extend(value);
                view
            })
            .collect();
        if let Some(program) = program {
            for predicate in 0..program.predicate_count {
                let arity = program.predicate_arities[predicate as usize];
                words.extend([0, 0, 0, 1, u64::from(predicate), u64::from(arity)]);
                operand_views.push(SemanticActionDescriptor::RulePredicate { predicate, arity });
            }
            for index in 0..4 {
                words.extend([0, 0, 0, 2, u64::from(index), 0]);
                operand_views.push(SemanticActionDescriptor::RuleVariable { index });
            }
        }
        words[4] = words.len() as u64;
        words[5] = qualifiers.len() as u64 + 1;
        words.extend([0; 3]);
        let qualifier_views = qualifiers
            .into_values()
            .map(|(refs, source)| {
                let offset = bytes.len();
                bytes.extend_from_slice(&(refs.len() as u32).to_le_bytes());
                for &index in &refs {
                    bytes.extend_from_slice(&Sha256::digest(
                        &admission.encoded_records[index as usize].bytes,
                    ));
                }
                words.extend([
                    offset as u64,
                    (bytes.len() - offset) as u64,
                    u64::from(source),
                ]);
                SemanticActionDescriptor::QualifierBundle { records: refs }
            })
            .collect();
        words[6] = words.len() as u64;
        words[7] = leaves.len() as u64 + 1;
        words.extend([0; 18]);
        let leaf_views = leaves
            .into_values()
            .map(|(row, view)| {
                words.extend(row);
                view
            })
            .collect();
        words[8] = words.len() as u64 * 8;
        words[9] = bytes.len() as u64;
        words[10..14].copy_from_slice(&identity_words(*admission.schema_generation().as_bytes()));
        words[17..21].copy_from_slice(&identity_words(
            *admission.base_snapshot().digest().as_bytes(),
        ));
        bytes.resize(bytes.len().div_ceil(8) * 8, 0);
        words.extend(
            bytes
                .as_chunks::<8>()
                .0
                .iter()
                .map(|v| u64::from_le_bytes(*v)),
        );
        let program_binding = program.map(Self::program_binding);
        for (range, count) in [1, 3, 5, 7].into_iter().enumerate() {
            words[29 + 2 * range] = 1;
            words[30 + 2 * range] = words[count];
        }
        words[38] = u64::from(program.is_some());
        words[39] = u64::from(program.is_some());
        let binding = Self::bind_admission_words(admission, owner, program_binding, &mut words)?;
        let (components, input_cells) = Self::component_geometry(&words, program.is_some())?;
        let components = components.into_iter().collect();
        Ok(Self {
            words,
            targets: target_views,
            operands: operand_views,
            qualifiers: qualifier_views,
            leaves: leaf_views,
            components,
            binding,
            program_binding,
            input_cells,
            model_catalogue: None,
            model_projection_reservation: None,
            derivation_reservation: None,
        })
    }

    fn component_geometry(
        words: &[u64],
        has_program: bool,
    ) -> Result<([SemanticComponent; COMPONENT_COUNT], usize), SemanticTransitionError> {
        validate_frozen_codebook_frame(words.len(), |index| words[index])?;
        if words.len() < model_catalogue::HEADER_WORDS
            || words[39] != u64::from(has_program)
            || [1, 3, 5, 7]
                .into_iter()
                .any(|index| words[index] == 0 || words[index] > 65536)
        {
            return Err(publication_input_error(
                "action codebook geometry requires its original complete header",
            ));
        }
        let mut components: [SemanticComponent; COMPONENT_COUNT] = COMPONENTS
            .try_into()
            .map_err(|_| SemanticTransitionError::ObservationMismatch)?;
        let mut offset = 0u64;
        for component in &mut components {
            let cardinality = if component.is_text() {
                component.cardinality
            } else {
                match component.field {
                    2 => words[1] as u32,
                    3..=6 => words[3] as u32,
                    7..=10 if words[38] != 0 => words[3] as u32,
                    1 if words[38] == 0 => 2,
                    11 => words[5] as u32,
                    17 => words[7] as u32,
                    _ => component.cardinality,
                }
            };
            component.offset = offset;
            component.cardinality = cardinality;
            offset = offset
                .checked_add(u64::from(cardinality))
                .ok_or(SemanticTransitionError::GenerationExhausted)?;
        }
        Ok((
            components,
            usize::try_from(offset).map_err(|_| SemanticTransitionError::GenerationExhausted)?,
        ))
    }
}

fn identity_words(bytes: [u8; 32]) -> [u64; 4] {
    std::array::from_fn(|i| u64::from_le_bytes(bytes[8 * i..8 * i + 8].try_into().unwrap()))
}

// SAFETY: fixed C layout, integral fields only.
unsafe impl DeviceRepr for SemanticComponent {}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct SemanticRngBinding {
    pub model_generation: u32,
    pub stream_serial: u64,
    pub family_id: u8,
    pub proposal: u32,
}

/// Device-produced receipt. Integers use three little-endian 64-bit limbs.
/// The exact probability is p/q; the exact importance factor is
/// p/factor_denominator. Singleton rows canonically use 1/1 for both.
#[repr(C)]
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct SemanticTransitionReceipt {
    pub proposal: u64,
    pub catalogue_generation: u64,
    pub catalogue_digest: Identity256,
    /// Binds the retained admission, acquired base, owner and logical codebooks.
    pub admission_binding: Identity256,
    pub ordinal: u32,
    pub lane: u32,
    pub slot: u32,
    pub field: u32,
    pub kind: u32,
    pub choice: u32,
    pub legal_count: u32,
    pub active_count: u32,
    pub selected_rank: u32,
    pub reserved: u32,
    pub key: [u32; 2],
    pub counter: [u32; 4],
    pub random_words: [u32; 4],
    pub draw: u64,
    pub cdf_start: u64,
    pub cdf_end: u64,
    pub mass: u64,
    pub p: [u64; 3],
    pub q: [u64; 3],
    pub factor_denominator: [u64; 3],
    pub cumulative_mass_below: [u64; 3],
    pub active_fields: u32,
    pub null_fields: u32,
}

// SAFETY: C layout, integral fields only; all bit patterns are valid.
unsafe impl DeviceRepr for SemanticTransitionReceipt {}

fn canonical_text_null(receipt: &SemanticTransitionReceipt) -> bool {
    receipt.kind == COMPONENT_KIND_TEXT as u32
        && receipt.choice == TEXT_NULL as u32
        && receipt.legal_count == 1
        && receipt.active_count == 1
        && receipt.selected_rank == 0
        && receipt.cumulative_mass_below == [0, 0, 0]
        && receipt.active_fields == 0
        && receipt.null_fields == 0
        && receipt.p == [1, 0, 0]
        && receipt.q == [1, 0, 0]
        && receipt.factor_denominator == [1, 0, 0]
        && receipt.cdf_start == 0
        && receipt.cdf_end == 1 << 63
        && receipt.mass == 1 << 63
}

/// Device-computed facts for the complete original task query roster.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct SemanticTaskFacts {
    /// Ordered actual Truth4 codes for the complete task query roster. A refused
    /// lane has no executed truth outcome; its terminal refusal is authoritative.
    pub truth: Vec<u64>,
    /// Equality of each actual Truth4 answer to the protected observer result.
    pub correct: Option<Vec<u64>>,
    /// Authenticated attainment of original listed goals, independent of
    /// reference correctness. Unlisted Coding queries contribute no attainment.
    pub attained: Vec<u64>,
    /// Number of correct logical queries or attained original coding goals.
    pub g: u64,
    /// Whether all original logical queries or listed coding goals are attained.
    pub p: u64,
    /// Actual edit commands plus added supports plus defined truth changes.
    pub c: u64,
    /// Query agreement minus measured work, using the bound task coefficients.
    pub v: i64,
    /// Whether the candidate satisfies the task scope and hard constraints.
    pub eligible: u64,
}

#[repr(C)]
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
struct DeviceTaskFacts {
    g: u64,
    p: u64,
    c: u64,
    v: i64,
    eligible: u64,
}

#[repr(C)]
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct DeviceTaskEvaluation {
    lane_refusal: [u64; 2],
    query_count: u64,
    winner: u64,
    return_value: i64,
    facts: [DeviceTaskFacts; 3],
}

/// Exact piecewise-linear cell selected by the device policy forward pass.
/// The separate retained masks carry the categorical support and active set.
#[repr(C)]
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
struct SemanticPolicyPwlCell {
    abi: u64,
    ordinal: u64,
    cardinality: u64,
    legal_count: u64,
    active_count: u64,
    selected_rank: u64,
    maximum_bits: u64,
    singleton: u64,
    g: [u64; 3],
    active_sum: [u64; 3],
    selected_probability: [u64; 3],
    probability_denominator: [u64; 3],
}

/// Producer-owned selected-score differential operator retained by the forward
/// pass. Together with the exact active set it determines the categorical VJP.
#[repr(C)]
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
struct SemanticPolicySelectedScoreVjp {
    abi: u64,
    ordinal: u64,
    choice: u64,
    active_count: u64,
    selected_active: u64,
    singleton: u64,
    probability_numerator: [u64; 3],
    probability_denominator: [u64; 3],
}

/// Device-sealed receipt for the complete action batch. The root is SHA-256 of
/// these exact bytes and therefore cannot be substituted by a task identity or
/// a digest of component receipts alone.
#[repr(C)]
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
struct SemanticActionBatchReceipt {
    abi: u64,
    proposal: u64,
    stream_serial: u64,
    family_id: u64,
    action_law_generation: u64,
    model_generation: u64,
    actor_eligible: u64,
    component_count: u64,
    candidate_count: u64,
    winner: u64,
    total_return_bits: u64,
    base_word: u64,
    next_word: u64,
    rng_base: u64,
    rng_span: u64,
    rng_successor: u64,
    catalogue_digest: Identity256,
    component_receipts_digest: Identity256,
    semantic_receipts_digest: Identity256,
    candidate_roots: [Identity256; 3],
    base_logical_digest: Identity256,
    execution_work: ExecutionWork,
}

#[repr(C)]
#[derive(Clone, Copy)]
struct DeviceState {
    model_generation: u32,
    family_id: u32,
    stream_serial: u64,
    proposal: u64,
    next_proposal: u64,
    blocks: u64,
    status: u64,
    catalogue_generation: u64,
    catalogue_digest: Identity256,
    binding_digest: Identity256,
    semantic_receipts: [[u64; 42]; 7],
    work: [SemanticTransitionWork; 2],
    importance_weight: f64,
    retired_roots_mask: u64,
    cleanup_receipts: [[u64; 42]; 3],
    task_evaluation: DeviceTaskEvaluation,
    actor_eligible: u64,
    execution_work: ExecutionWork,
    action_batch: SemanticActionBatchReceipt,
    action_batch_root: Identity256,
}

impl Default for DeviceState {
    fn default() -> Self {
        // SAFETY: the scalar ABI admits every bit pattern; zero initializes all
        // integers and the floating-point importance weight.
        unsafe { std::mem::zeroed() }
    }
}

// SAFETY: C layout, integer and FP64 fields; all bit patterns are valid.
unsafe impl DeviceRepr for DeviceState {}
unsafe impl DeviceRepr for SemanticPolicyPwlCell {}
unsafe impl DeviceRepr for SemanticPolicySelectedScoreVjp {}
unsafe impl DeviceRepr for SemanticActionBatchReceipt {}

const _: () = assert!(size_of::<SemanticPolicyPwlCell>() == 160);
const _: () = assert!(size_of::<SemanticPolicySelectedScoreVjp>() == 96);
const _: () = assert!(size_of::<SemanticActionBatchReceipt>() == 504);

/// Original active-ring source slot. Kind and provenance are independent: a
/// filled model-input row is not an assertion that the token was observed.
#[repr(C)]
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct SemanticTextSlot {
    pub token: u64,
    pub logical_position: u64,
    /// Padding = 0, filled = 1, mask = 2. Active validity is derived from kind.
    pub kind: u64,
    /// Absent = 0, source = 1, generated = 2; only filled rows have a subtype.
    pub provenance: u64,
    pub valid: u64,
    pub committed: u64,
    pub recomputed: u64,
    /// Row in the retained full source-provenance table, not an authority bit.
    pub provenance_record: u64,
}

type SourceSlot = SemanticTextSlot;

// SAFETY: C layout containing only u64 values; all bit patterns are valid.
unsafe impl DeviceRepr for SourceSlot {}

/// Semantic role of a retained state range. Indices name actual layers, tensors,
/// or records inside the cold-bound role roster, never arbitrary device pointers.
#[repr(u64)]
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
pub enum SemanticStateRole {
    PrefixSource = 1,
    TokenProvenanceRecords = 2,
    PrefixIdentity = 3,
    AttentionKeys = 4,
    AttentionValues = 5,
    ConvolutionState = 6,
    RecurrentState = 7,
    ValueRunningMax = 8,
    ValueDenominator = 9,
    ValueNumerator = 10,
    EditRunningMax = 11,
    EditDenominator = 12,
    EditNumerator = 13,
    CompletionCoverage = 14,
    RawFeedback = 15,
    FeedbackStatements = 16,
    FeedbackSupportProvenance = 17,
    SlowWeights = 18,
    FastAdapters = 19,
    SymbolicHeads = 20,
    OptimizerState = 21,
    LossScaler = 22,
    TrainingSchedule = 23,
    Gradients = 24,
    GradientAccumulation = 25,
    OtherRng = 26,
    ReplayEntries = 27,
    ReplayPayload = 28,
    TrainingView = 29,
    IntentEntries = 30,
    IntentPayload = 31,
    Acknowledgements = 32,
    AttemptReceipt = 33,
    GoalState = 34,
    WorldLineage = 35,
    EditJournal = 36,
    Environment = 37,
    AuthorityEnvelope = 38,
    AuthorityDecisions = 39,
    CheckpointLineage = 40,
    SchemaContract = 41,
    TokenizerContract = 42,
    RuntimeContract = 43,
    ModelContract = 44,
    TopologyContract = 45,
    PositionTable = 46,
    ActionCatalogue = 47,
    ActionCodebooks = 48,
    ProofRecords = 49,
    LearningCopyReset = 50,
    ActiveAttentionKeys = 51,
    ActiveAttentionValues = 52,
    ActiveConvolution = 53,
    ActiveRecurrent = 54,
    TensorLayout = 55,
    ReplayAppendEntries = 56,
    ReplayAppendPayload = 57,
    TaskGround = 58,
}

const PUBLICATION_ROLE_COUNT: usize = SemanticStateRole::TaskGround as usize;

impl SemanticStateRole {
    pub fn from_code(code: u64) -> Option<Self> {
        const ROLES: [SemanticStateRole; PUBLICATION_ROLE_COUNT] = [
            SemanticStateRole::PrefixSource,
            SemanticStateRole::TokenProvenanceRecords,
            SemanticStateRole::PrefixIdentity,
            SemanticStateRole::AttentionKeys,
            SemanticStateRole::AttentionValues,
            SemanticStateRole::ConvolutionState,
            SemanticStateRole::RecurrentState,
            SemanticStateRole::ValueRunningMax,
            SemanticStateRole::ValueDenominator,
            SemanticStateRole::ValueNumerator,
            SemanticStateRole::EditRunningMax,
            SemanticStateRole::EditDenominator,
            SemanticStateRole::EditNumerator,
            SemanticStateRole::CompletionCoverage,
            SemanticStateRole::RawFeedback,
            SemanticStateRole::FeedbackStatements,
            SemanticStateRole::FeedbackSupportProvenance,
            SemanticStateRole::SlowWeights,
            SemanticStateRole::FastAdapters,
            SemanticStateRole::SymbolicHeads,
            SemanticStateRole::OptimizerState,
            SemanticStateRole::LossScaler,
            SemanticStateRole::TrainingSchedule,
            SemanticStateRole::Gradients,
            SemanticStateRole::GradientAccumulation,
            SemanticStateRole::OtherRng,
            SemanticStateRole::ReplayEntries,
            SemanticStateRole::ReplayPayload,
            SemanticStateRole::TrainingView,
            SemanticStateRole::IntentEntries,
            SemanticStateRole::IntentPayload,
            SemanticStateRole::Acknowledgements,
            SemanticStateRole::AttemptReceipt,
            SemanticStateRole::GoalState,
            SemanticStateRole::WorldLineage,
            SemanticStateRole::EditJournal,
            SemanticStateRole::Environment,
            SemanticStateRole::AuthorityEnvelope,
            SemanticStateRole::AuthorityDecisions,
            SemanticStateRole::CheckpointLineage,
            SemanticStateRole::SchemaContract,
            SemanticStateRole::TokenizerContract,
            SemanticStateRole::RuntimeContract,
            SemanticStateRole::ModelContract,
            SemanticStateRole::TopologyContract,
            SemanticStateRole::PositionTable,
            SemanticStateRole::ActionCatalogue,
            SemanticStateRole::ActionCodebooks,
            SemanticStateRole::ProofRecords,
            SemanticStateRole::LearningCopyReset,
            SemanticStateRole::ActiveAttentionKeys,
            SemanticStateRole::ActiveAttentionValues,
            SemanticStateRole::ActiveConvolution,
            SemanticStateRole::ActiveRecurrent,
            SemanticStateRole::TensorLayout,
            SemanticStateRole::ReplayAppendEntries,
            SemanticStateRole::ReplayAppendPayload,
            SemanticStateRole::TaskGround,
        ];
        let index = usize::try_from(code.checked_sub(1)?).ok()?;
        ROLES.get(index).copied()
    }
}

/// One actual canonical control record or queue payload retained by a parent.
/// Mutable queue capacity is explicit; bytes contain the real encoded header
/// and entries, including an empty queue's header rather than an invented state.
pub struct SemanticStateRecord {
    pub role: SemanticStateRole,
    pub index: u64,
    pub bytes: Vec<u8>,
    pub capacity_bytes: usize,
}

/// Byte spans in the producer's one ModelContract record. The native owner
/// hashes the immutable schema bytes without interpreting their format, then
/// binds them to the actual model generation and original publication instance.
/// Digest fields are raw 32 bytes; generation is an unaligned little-endian u64.
#[repr(C)]
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct SemanticModelContractLayout {
    pub schema_begin: u64,
    pub schema_bytes: u64,
    pub schema_digest_offset: u64,
    pub generation_offset: u64,
    pub identity_offset: u64,
}

impl SemanticModelContractLayout {
    fn validate(self, record_bytes: u64) -> Result<(), SemanticTransitionError> {
        let spans = [
            (self.schema_begin, self.schema_bytes),
            (self.schema_digest_offset, 32),
            (self.generation_offset, 8),
            (self.identity_offset, 32),
        ];
        for (index, &(begin, bytes)) in spans.iter().enumerate() {
            if bytes == 0
                || begin > record_bytes
                || bytes > record_bytes - begin
                || spans[..index]
                    .iter()
                    .any(|&(other, length)| begin < other + length && other < begin + bytes)
            {
                return Err(publication_input_error(
                    "model contract spans must be nonempty, disjoint and within its actual bytes",
                ));
            }
        }
        Ok(())
    }
}

/// A genuine producer-owned model tensor and its exact cold model contract.
/// No numeric conversion occurs. Logical intervals describe covered positions;
/// non-positional weights and optimizer state use the explicit interval 0..0.
pub struct SemanticTensorInput {
    pub layout: SemanticTensorLayout,
    pub logical_begin: u64,
    pub logical_end: u64,
    pub tensor: DlpackManagedTensor,
    /// Retained native allocation origin of this actual producer, if any.
    /// This is not a reader grant or a tensor version-counter identity.
    pub native_allocation: Option<DeviceAllocationProvenance>,
}

/// Retained original tensor producers for one prepared bank's autograd
/// delivery boundary. The binding owns the consumed DLPack records until the
/// Python-side delivery owner is retired; it grants no publication authority.
pub struct SemanticGradientDeliveryBinding {
    _tensors: Vec<PreparedSemanticTensor>,
    _reservation: Option<SemanticReplayMaterialReservation>,
}

#[derive(Clone, Copy)]
enum GradientDeliveryModel<'a> {
    Recorded(&'a [PreparedSemanticTensor], &'a BTreeSet<(u64, u64)>),
    #[cfg(feature = "semantic-policy")]
    Acquired(
        &'a PublicationStorage,
        &'a SemanticPublishedLease,
        &'a BTreeSet<(u64, u64)>,
    ),
}

impl<'a> GradientDeliveryModel<'a> {
    fn parameter_coordinates(self) -> &'a BTreeSet<(u64, u64)> {
        match self {
            Self::Recorded(_, parameters) => parameters,
            #[cfg(feature = "semantic-policy")]
            Self::Acquired(_, _, parameters) => parameters,
        }
    }

    fn owns_tensor(self, tensor: &PreparedSemanticTensor) -> Result<bool, SemanticTransitionError> {
        match self {
            Self::Recorded(model, _) => Ok(model
                .iter()
                .any(|original| same_tensor_content_owner(original, tensor))),
            #[cfg(feature = "semantic-policy")]
            Self::Acquired(storage, lease, _) => {
                let key = (tensor.layout.role, tensor.layout.index);
                let Some(range) = lease
                    .directory
                    .iter()
                    .find(|range| (range.role, range.index) == key)
                else {
                    return Ok(false);
                };
                let Some(layout) = storage.layouts.get(&key) else {
                    return Ok(false);
                };
                let Some(backing) = storage.allocations.get(range.storage_slot as usize) else {
                    return Ok(false);
                };
                let begin = usize::try_from(range.offset_bytes)
                    .map_err(|_| SemanticTransitionError::ObservationMismatch)?;
                let end = usize::try_from(range.length_bytes)
                    .ok()
                    .and_then(|bytes| begin.checked_add(bytes))
                    .ok_or(SemanticTransitionError::ObservationMismatch)?;
                let view = backing
                    .slice()?
                    .view()
                    .try_slice(begin..end)
                    .ok_or(SemanticTransitionError::ObservationMismatch)?;
                Ok(tensor.layout == *layout
                    && tensor.logical_begin == range.logical_begin
                    && tensor.logical_end == range.logical_end
                    && tensor.data == *view.device_ptr()
                    && tensor
                        .source
                        .as_ref()
                        .is_some_and(|source| source.len() == view.len())
                    && step_input_allocation_matches(tensor, &view))
            }
        }
    }
}

/// A producer-declared storage object within one complete backing allocation.
/// Storage identity is its ordinal, not an address or a tensor version counter.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct SemanticModelStorage {
    pub allocation: u64,
    pub byte_offset: u64,
    pub span_bytes: u64,
}

/// A typed publication coordinate within a producer-declared storage object.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct SemanticModelView {
    pub role: u64,
    pub index: u64,
    pub storage: u64,
    pub byte_offset: u64,
}

/// Full producer-owned backing buffers and their independent storage/view map.
/// Allocation inputs are contiguous U8 vectors with role zero and ordinal index.
/// Tensor and version-counter identities remain in the opaque model contract.
pub struct SemanticModelMemory {
    pub allocations: Vec<SemanticTensorInput>,
    pub storages: Vec<SemanticModelStorage>,
    pub views: Vec<SemanticModelView>,
}

#[derive(Clone, Debug, Default, PartialEq, Eq)]
struct ModelMemoryGeometry {
    allocation_bytes: Vec<u64>,
    storages: Vec<SemanticModelStorage>,
    views: Vec<SemanticModelView>,
}

impl ModelMemoryGeometry {
    fn location(&self, role: u64, index: u64) -> Result<(usize, usize), SemanticTransitionError> {
        let view = self
            .views
            .iter()
            .find(|view| (view.role, view.index) == (role, index))
            .ok_or_else(|| {
                publication_input_error("model tensor lacks its producer storage view")
            })?;
        let storage = usize::try_from(view.storage)
            .ok()
            .and_then(|index| self.storages.get(index))
            .ok_or_else(|| publication_input_error("model view names an absent storage object"))?;
        let allocation = usize::try_from(storage.allocation)
            .ok()
            .filter(|&index| index < self.allocation_bytes.len())
            .ok_or_else(|| {
                publication_input_error("model storage names an absent backing allocation")
            })?;
        let offset = storage
            .byte_offset
            .checked_add(view.byte_offset)
            .and_then(|offset| usize::try_from(offset).ok())
            .ok_or_else(|| publication_input_error("model storage view offset overflows"))?;
        Ok((allocation, offset))
    }

    fn validate(
        &self,
        layouts: &BTreeMap<(u64, u64), SemanticTensorLayout>,
    ) -> Result<(), SemanticTransitionError> {
        let mut allocations = BTreeSet::new();
        for storage in &self.storages {
            let capacity = usize::try_from(storage.allocation)
                .ok()
                .and_then(|index| self.allocation_bytes.get(index))
                .ok_or_else(|| publication_input_error("model storage allocation is absent"))?;
            if usize::try_from(*capacity).is_err()
                || storage
                    .byte_offset
                    .checked_add(storage.span_bytes)
                    .is_none_or(|end| end > *capacity)
            {
                return Err(publication_input_error(
                    "model storage exceeds its complete backing allocation",
                ));
            }
            allocations.insert(storage.allocation);
        }
        let mut storages = BTreeSet::new();
        let mut previous = None;
        for view in &self.views {
            let key = (view.role, view.index);
            if !matches!(view.role, 18..=25) || previous.is_some_and(|previous| previous >= key) {
                return Err(publication_input_error(
                    "model views must enumerate unique model tensor coordinates in order",
                ));
            }
            previous = Some(key);
            let layout = layouts.get(&key).ok_or_else(|| {
                publication_input_error("model storage view lacks its original tensor layout")
            })?;
            let (_, offset) = self.location(view.role, view.index)?;
            let storage = &self.storages[view.storage as usize];
            let span = tensor_layout_bytes(layout)? as u64;
            if layout.logical_axis != u64::MAX
                || !(offset as u64).is_multiple_of(layout.element_bytes)
                || view
                    .byte_offset
                    .checked_add(span)
                    .is_none_or(|end| end > storage.span_bytes)
            {
                return Err(publication_input_error(
                    "typed model view exceeds or misaligns its declared storage",
                ));
            }
            storages.insert(view.storage);
        }
        if allocations.len() != self.allocation_bytes.len()
            || storages.len() != self.storages.len()
            || self.views.len()
                != layouts
                    .values()
                    .filter(|layout| matches!(layout.role, 18..=25))
                    .count()
        {
            return Err(publication_input_error(
                "model memory map omits a tensor or contains unreachable storage",
            ));
        }
        Ok(())
    }

    fn encode_into(&self, bytes: &mut Vec<u8>) -> Result<(), SemanticTransitionError> {
        for count in [
            self.allocation_bytes.len(),
            self.storages.len(),
            self.views.len(),
        ] {
            material_u32(
                bytes,
                u32::try_from(count).map_err(|_| SemanticTransitionError::GenerationExhausted)?,
            );
        }
        for &extent in &self.allocation_bytes {
            material_u64(bytes, extent);
        }
        for storage in &self.storages {
            for field in [storage.allocation, storage.byte_offset, storage.span_bytes] {
                material_u64(bytes, field);
            }
        }
        for view in &self.views {
            for field in [view.role, view.index, view.storage, view.byte_offset] {
                material_u64(bytes, field);
            }
        }
        Ok(())
    }

    fn digest(
        &self,
        layouts: &BTreeMap<(u64, u64), SemanticTensorLayout>,
    ) -> Result<Identity256, SemanticTransitionError> {
        self.validate(layouts)?;
        let mut bytes = b"xlog.semantic.model-memory.v1\0".to_vec();
        self.encode_into(&mut bytes)?;
        let model = layouts
            .values()
            .filter(|layout| matches!(layout.role, 18..=25));
        material_u64(&mut bytes, model.clone().count() as u64);
        for layout in model {
            for field in [
                layout.role,
                layout.index,
                layout.element_bytes,
                layout.scalar_type,
                layout.rank,
                layout.logical_axis,
            ]
            .into_iter()
            .chain(layout.dimensions)
            .chain(layout.strides_bytes)
            {
                material_u64(&mut bytes, field);
            }
        }
        Ok(Identity256::from_bytes(Sha256::digest(&bytes).into()))
    }

    fn decode_from(
        reader: &mut SemanticMaterialReader<'_>,
    ) -> Result<Self, SemanticTransitionError> {
        let allocations = reader.count(8).map_err(SemanticTransitionError::Semantic)?;
        let storages = reader
            .count(24)
            .map_err(SemanticTransitionError::Semantic)?;
        let views = reader
            .count(32)
            .map_err(SemanticTransitionError::Semantic)?;
        let mut geometry = Self::default();
        for _ in 0..allocations {
            geometry
                .allocation_bytes
                .push(reader.u64().map_err(SemanticTransitionError::Semantic)?);
        }
        for _ in 0..storages {
            geometry.storages.push(SemanticModelStorage {
                allocation: reader.u64().map_err(SemanticTransitionError::Semantic)?,
                byte_offset: reader.u64().map_err(SemanticTransitionError::Semantic)?,
                span_bytes: reader.u64().map_err(SemanticTransitionError::Semantic)?,
            });
        }
        for _ in 0..views {
            geometry.views.push(SemanticModelView {
                role: reader.u64().map_err(SemanticTransitionError::Semantic)?,
                index: reader.u64().map_err(SemanticTransitionError::Semantic)?,
                storage: reader.u64().map_err(SemanticTransitionError::Semantic)?,
                byte_offset: reader.u64().map_err(SemanticTransitionError::Semantic)?,
            });
        }
        Ok(geometry)
    }
}

fn prepare_model_memory(
    allocations: &[PreparedSemanticTensor],
    storages: Vec<SemanticModelStorage>,
    views: Vec<SemanticModelView>,
    tensors: &[PreparedSemanticTensor],
) -> Result<ModelMemoryGeometry, SemanticTransitionError> {
    let mut geometry = ModelMemoryGeometry {
        allocation_bytes: Vec::new(),
        storages,
        views,
    };
    for (index, allocation) in allocations.iter().enumerate() {
        let layout = allocation.layout;
        if layout.role != 0
            || layout.index != index as u64
            || layout.rank != 1
            || layout.scalar_type != 1
            || layout.element_bytes != 1
            || layout.logical_axis != u64::MAX
            || layout.strides_bytes != [1, 0, 0, 0]
            || allocation.logical_begin != 0
            || allocation.logical_end != 0
        {
            return Err(publication_input_error(
                "model backing producer must be its complete ordinal U8 vector",
            ));
        }
        let bytes = tensor_layout_bytes(&layout)? as u64;
        let end = allocation
            .data
            .checked_add(bytes)
            .ok_or(SemanticTransitionError::GenerationExhausted)?;
        // Validate distinct declared owners; never infer identity from addresses.
        for (prior, &prior_bytes) in allocations[..index].iter().zip(&geometry.allocation_bytes) {
            if bytes != 0
                && prior_bytes != 0
                && allocation.data < prior.data + prior_bytes
                && prior.data < end
            {
                return Err(publication_input_error(
                    "declared model backing allocations overlap",
                ));
            }
        }
        geometry.allocation_bytes.push(bytes);
    }
    let layouts = tensors
        .iter()
        .map(|tensor| ((tensor.layout.role, tensor.layout.index), tensor.layout))
        .collect();
    geometry.validate(&layouts)?;
    for tensor in tensors
        .iter()
        .filter(|tensor| matches!(tensor.layout.role, 18..=25))
    {
        let (allocation, offset) = geometry.location(tensor.layout.role, tensor.layout.index)?;
        if allocations[allocation].data.checked_add(offset as u64) != Some(tensor.data) {
            return Err(publication_input_error(
                "original tensor does not occupy its producer-declared backing view",
            ));
        }
    }
    Ok(geometry)
}

/// Operator-granted plan and finite candidate interval in the native prefix.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct SemanticNonterminalIntentBinding {
    pub plan_digest: Identity256,
    pub candidate_prefix_begin: u64,
    pub candidate_prefix_end: u64,
}

impl SemanticNonterminalIntentBinding {
    fn validate(self, prefix_capacity: u64) -> Result<(), SemanticTransitionError> {
        if self.plan_digest == Identity256::default()
            || self.candidate_prefix_begin >= self.candidate_prefix_end
            || self.candidate_prefix_end > prefix_capacity
        {
            return Err(publication_input_error(
                "nonterminal intent requires its original plan and bounded candidate prefix",
            ));
        }
        self.payload_bytes()?;
        Ok(())
    }

    fn payload_bytes(self) -> Result<u64, SemanticTransitionError> {
        self.candidate_prefix_end
            .checked_sub(self.candidate_prefix_begin)
            .and_then(|count| count.checked_mul(size_of::<u64>() as u64))
            .and_then(|bytes| bytes.checked_add(32 + 2 * size_of::<u64>() as u64))
            .ok_or_else(|| publication_input_error("nonterminal intent payload extent overflowed"))
    }
}

/// Original finite reservation for acquired non-actor replay rows.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct SemanticReplayAppendBinding {
    pub row_capacity: usize,
    pub raw_byte_capacity: usize,
    pub append_groups: Vec<Vec<u64>>,
    pub metadata_bytes: u64,
    pub max_material_bytes: u64,
    pub total_material_bytes: u64,
    pub max_evidence_bytes: u64,
    pub payload_capacity_bytes: usize,
}

impl SemanticReplayAppendBinding {
    pub(crate) fn validate(&self) -> Result<(), SemanticTransitionError> {
        if self.row_capacity == 0
            || self.raw_byte_capacity == 0
            || self.append_groups.is_empty()
            || self.append_groups.len() >= self.row_capacity
            || self.metadata_bytes == 0
            || self.max_material_bytes == 0
            || self.total_material_bytes == 0
            || self.max_evidence_bytes == 0
            || self.payload_capacity_bytes == 0
        {
            return Err(publication_input_error(
                "replay append requires its original finite row, payload and acquisition reservation",
            ));
        }
        Ok(())
    }
}

/// Initial canonical parent only. A model continuation cannot be supplied here:
/// it is admitted after a real Acquire and a forward using that acquired parent.
/// PrefixIdentity is native-owned: fresh publication derives its 32 bytes from
/// the actual PrefixSource. Supplying a caller record for that role is an error.
pub struct SemanticParentBinding {
    pub recovered_instance: Option<Identity256>,
    pub source: [SemanticTextSlot; 32],
    pub prefix: Vec<SemanticTextSlot>,
    pub ring_head: u64,
    pub provenance_records: u64,
    pub prefix_capacity: u64,
    pub feedback_capacity: u64,
    pub max_position: u64,
    pub pad_token: u64,
    pub terminal_tokens: Vec<u64>,
    pub final_intent_payload_bytes: u64,
    /// Operator-bound plan and original native prefix interval, never a model
    /// token convention or a caller-encoded intent queue.
    pub nonterminal_intent: Option<SemanticNonterminalIntentBinding>,
    /// Original finite replay reservation, allocated during the task import.
    pub replay_append: Option<SemanticReplayAppendBinding>,
    /// Actual application effect descriptor. The native owner constructs the
    /// empty intent queue; callers never encode its private header or entries.
    pub intent_effect: Vec<u8>,
    pub intent_entry_capacity: u64,
    pub intent_payload_capacity_bytes: usize,
    pub acknowledgement_payload_capacity_bytes: usize,
    pub model_generation: u64,
    /// Complete versioned numerical-mode contribution from the model owner.
    /// The Python binding uses exact canonical ColdValue metadata, not a digest
    /// or repr. Native code owns the surrounding RuntimeContract record.
    pub model_numerical_mode: Vec<u8>,
    pub model_contract_layout: SemanticModelContractLayout,
    pub policy_generation: u64,
    pub neural_generation: u64,
    pub cache_generation: u64,
    pub authority_generation: u64,
    pub training_cursor: u64,
    pub training_rng: [u64; 4],
    pub fuel: u64,
    pub rng: SemanticRngBinding,
    pub topology_identity: Identity256,
    pub table_identity: Identity256,
    /// Every one of the 55 roles is explicit, including actual zero tensor counts.
    pub role_counts: [u64; 55],
    pub records: Vec<SemanticStateRecord>,
    pub tensors: Vec<SemanticTensorInput>,
    pub model_memory: SemanticModelMemory,
    /// Model-declared 51..54 capacities only; no active output exists before
    /// Acquire and the original forward. Initial ranges are unreachable.
    pub active_layouts: Vec<SemanticTensorLayout>,
}

/// An observed token payload admitted by the trusted application controller.
/// `origin` retains the complete source/manifest/transformation record, not an
/// independently supplied native digest or a model-generated provenance row.
#[derive(Clone, Debug)]
pub struct SemanticObservedSource {
    pub identity: String,
    pub tokens: Vec<u64>,
    pub origin: Vec<u8>,
}

/// A token is selected only by offset into its admitted observed payload.
#[derive(Clone, Debug)]
pub struct SemanticSourceMapping {
    pub source: String,
    pub offset: u64,
    pub logical_position: u64,
}

/// Initial source geometry issued from the admitted observation mapping before
/// the model computes its prefix cache. The rows retain zero provenance indices;
/// parent binding constructs and verifies the private ledger after prefill.
#[derive(Clone)]
pub struct SemanticInitialSourceLayout {
    pub source: [SemanticTextSlot; 32],
    pub prefix: Vec<SemanticTextSlot>,
    pub prefill_tokens: Vec<u64>,
    pub ring_head: u64,
    #[cfg(feature = "semantic-policy")]
    prefill_mapping: Vec<SemanticSourceMapping>,
    provenance_bytes: Vec<u8>,
    provenance_capacity_bytes: usize,
    provenance_records: u64,
}

/// One imported task's pre-parent model input. Its source and owner are fixed
/// before the actual model call; no second stage can be issued on this Session.
struct InitialPrefillTensorOwners {
    tensors: Vec<PreparedSemanticTensor>,
}

struct InitialPrefillStage {
    scope: Arc<()>,
    task_identity: Identity256,
    task_epoch: u64,
    model_generation: u64,
    layout: SemanticInitialSourceLayout,
    input: Option<PreparedSemanticTensor>,
    model_content: Option<InitialPrefillTensorOwners>,
    output_content: Option<InitialPrefillTensorOwners>,
    consumer_stream: Option<u64>,
}

/// Storage needed by the original forward after the one-use prefill stage has
/// joined its parent. Tensor owners retire with the first known prepared segment;
/// the original scope and record remain available for later material custody.
struct RetainedInitialPrefillContent {
    scope: Arc<()>,
    task_identity: Identity256,
    task_epoch: u64,
    model_generation: u64,
    model: InitialPrefillTensorOwners,
    #[cfg(feature = "semantic-policy")]
    output: InitialPrefillTensorOwners,
    #[cfg(feature = "semantic-policy")]
    record: InitialPrefillRecord,
}

#[cfg(feature = "semantic-policy")]
#[derive(Clone)]
struct InitialPrefillRecord {
    predecessor: SemanticPublishedIdentity,
    semantic_root: Identity256,
    task_identity: Identity256,
    task_epoch: u64,
    task_content: SemanticTaskContentIdentity,
    model_generation: u64,
    tokens: Vec<u64>,
    mapping: Vec<SemanticSourceMapping>,
}

/// The one content grammar for published and dormant completed prefills.
struct DecodedInitialPrefillContent {
    token_count: usize,
    semantic_root: Identity256,
    model_generation: u64,
    task_identity: Identity256,
    task_epoch: u64,
    task_content: SemanticTaskContentIdentity,
    tokens: Vec<u64>,
    mapping: Vec<SemanticSourceMapping>,
}

impl DecodedInitialPrefillContent {
    fn verify(
        &self,
        semantic_root: Identity256,
        model_generation: u64,
        task_identity: Identity256,
        task_epoch: u64,
        task_content: SemanticTaskContentIdentity,
        prefix_extent: u64,
    ) -> Result<(), SemanticTransitionError> {
        if self.semantic_root != semantic_root
            || self.model_generation != model_generation
            || self.task_identity != task_identity
            || self.task_epoch != task_epoch
            || self.task_content != task_content
            || self.token_count as u64 != prefix_extent
            || self.token_count == 0
        {
            return Err(publication_input_error(
                "checkpoint initial prefill differs from its native task or parent",
            ));
        }
        Ok(())
    }
}

fn prefill_identity(
    reader: &mut SemanticMaterialReader<'_>,
) -> Result<Identity256, SemanticTransitionError> {
    Ok(Identity256::from_bytes(
        reader
            .take(32)
            .map_err(SemanticTransitionError::Semantic)?
            .try_into()
            .map_err(|_| SemanticTransitionError::ObservationMismatch)?,
    ))
}

fn prefill_extent(
    reader: &mut SemanticMaterialReader<'_>,
) -> Result<usize, SemanticTransitionError> {
    usize::try_from(reader.u64().map_err(SemanticTransitionError::Semantic)?)
        .map_err(|_| publication_input_error("initial prefill extent exceeds this host"))
}

impl CheckpointInitialPrefill {
    fn parse_content(
        bytes: &[u8],
    ) -> Result<DecodedInitialPrefillContent, SemanticTransitionError> {
        Self::parse_content_mode(bytes, true)
    }

    fn scan_content(bytes: &[u8]) -> Result<DecodedInitialPrefillContent, SemanticTransitionError> {
        Self::parse_content_mode(bytes, false)
    }

    fn parse_content_mode(
        bytes: &[u8],
        retain: bool,
    ) -> Result<DecodedInitialPrefillContent, SemanticTransitionError> {
        let mut reader = SemanticMaterialReader::new(bytes);
        let semantic_root = prefill_identity(&mut reader)?;
        let model_generation = reader.u64().map_err(SemanticTransitionError::Semantic)?;
        let task_identity = prefill_identity(&mut reader)?;
        let task_epoch = reader.u64().map_err(SemanticTransitionError::Semantic)?;
        let task_content = SemanticTaskContentIdentity {
            query: prefill_identity(&mut reader)?,
            theory_program: prefill_identity(&mut reader)?,
            result: prefill_identity(&mut reader)?,
        };
        let token_count = prefill_extent(&mut reader)?;
        if token_count == 0 || token_count > bytes.len() / size_of::<u64>() {
            return Err(publication_input_error(
                "checkpoint initial prefill token extent differs",
            ));
        }
        let mut tokens = Vec::new();
        if retain {
            tokens.try_reserve_exact(token_count).map_err(|_| {
                publication_input_error("initial prefill token roster allocation failed")
            })?;
        }
        for _ in 0..token_count {
            let token = reader.u64().map_err(SemanticTransitionError::Semantic)?;
            if retain {
                tokens.push(token);
            }
        }
        if prefill_extent(&mut reader)? != token_count {
            return Err(publication_input_error(
                "checkpoint initial prefill mapping extent differs",
            ));
        }
        let mut mapping = Vec::new();
        if retain {
            mapping.try_reserve_exact(token_count).map_err(|_| {
                publication_input_error("initial prefill mapping allocation failed")
            })?;
        }
        for position in 0..token_count {
            let length = prefill_extent(&mut reader)?;
            let source = reader
                .take(length)
                .map_err(SemanticTransitionError::Semantic)?;
            let source = std::str::from_utf8(source).map_err(|_| {
                publication_input_error("checkpoint initial prefill source name is invalid")
            })?;
            let offset = reader.u64().map_err(SemanticTransitionError::Semantic)?;
            let logical_position = reader.u64().map_err(SemanticTransitionError::Semantic)?;
            if source.is_empty() || logical_position != position as u64 {
                return Err(publication_input_error(
                    "checkpoint initial prefill logical positions differ",
                ));
            }
            if retain {
                mapping.push(SemanticSourceMapping {
                    source: source.to_owned(),
                    offset,
                    logical_position,
                });
            }
        }
        reader.finish().map_err(SemanticTransitionError::Semantic)?;
        Ok(DecodedInitialPrefillContent {
            semantic_root,
            model_generation,
            task_identity,
            task_epoch,
            task_content,
            token_count,
            tokens,
            mapping,
        })
    }
}

#[cfg(feature = "semantic-policy")]
fn encode_initial_prefill_record_prefix(
    record: &InitialPrefillRecord,
) -> Result<Vec<u8>, SemanticTransitionError> {
    let extent = initial_prefill_content_extent(record)?;
    let mut bytes = Vec::new();
    bytes
        .try_reserve_exact(extent)
        .map_err(|_| publication_input_error("initial prefill content allocation failed"))?;
    bytes.extend_from_slice(record.semantic_root.as_bytes());
    material_u64(&mut bytes, record.model_generation);
    bytes.extend_from_slice(record.task_identity.as_bytes());
    material_u64(&mut bytes, record.task_epoch);
    for identity in [
        record.task_content.query,
        record.task_content.theory_program,
        record.task_content.result,
    ] {
        bytes.extend_from_slice(identity.as_bytes());
    }
    material_u64(&mut bytes, record.tokens.len() as u64);
    for token in &record.tokens {
        material_u64(&mut bytes, *token);
    }
    material_u64(&mut bytes, record.mapping.len() as u64);
    for row in &record.mapping {
        material_u64(&mut bytes, row.source.len() as u64);
        bytes.extend_from_slice(row.source.as_bytes());
        material_u64(&mut bytes, row.offset);
        material_u64(&mut bytes, row.logical_position);
    }
    Ok(bytes)
}

#[cfg(feature = "semantic-policy")]
fn initial_prefill_geometry_content_extent(
    tokens: &[u64],
    mapping: &[SemanticSourceMapping],
) -> Result<usize, SemanticTransitionError> {
    let extent = (5usize * 32 + 4 * 8)
        .checked_add(
            tokens
                .len()
                .checked_mul(8)
                .ok_or(SemanticTransitionError::GenerationExhausted)?,
        )
        .ok_or(SemanticTransitionError::GenerationExhausted)?;
    mapping.iter().try_fold(extent, |size, row| {
        size.checked_add(3 * 8)
            .and_then(|size| size.checked_add(row.source.len()))
            .ok_or(SemanticTransitionError::GenerationExhausted)
    })
}

struct CheckpointInitialPrefill {
    original: SemanticPublishedIdentity,
    content: Vec<u8>,
    recovery_referent: Option<Vec<u8>>,
}

#[cfg(feature = "semantic-policy")]
struct OriginalInitialPrefillContent {
    predecessor: SemanticPublishedIdentity,
    bytes: Vec<u8>,
    installed: bool,
}

/// Original prefill seals and the exact outstanding read cursor. No new
/// numerical producer or prefill baseline is constructed by this export.
pub struct SemanticCheckpointInitialPrefillObservation {
    binding: SemanticPublishedStateObservationBinding,
    #[cfg(feature = "semantic-policy")]
    content: Option<OriginalInitialPrefillContent>,
    reservation: Option<Arc<SemanticReplayMaterialReservation>>,
    section: Option<Vec<u8>>,
    loaded: Option<SemanticReplayLoadedMaterial>,
    present: bool,
}

#[cfg(feature = "semantic-policy")]
fn initial_prefill_content_extent(
    record: &InitialPrefillRecord,
) -> Result<usize, SemanticTransitionError> {
    initial_prefill_geometry_content_extent(&record.tokens, &record.mapping)
}

impl CheckpointInitialPrefill {
    const MAGIC: &'static [u8] = b"XLOG-CHECKPOINT-INITIAL-PREFILL\0";

    fn encode_section(value: Option<&Self>) -> Result<Vec<u8>, SemanticTransitionError> {
        let extent = Self::MAGIC.len() + 8 + 1;
        let extent = value.map_or(Ok(extent), |value| {
            extent
                .checked_add(2 * 32 + 8 + 8)
                .and_then(|size| size.checked_add(value.content.len()))
                .ok_or(SemanticTransitionError::GenerationExhausted)
        })?;
        let mut bytes = Vec::new();
        bytes
            .try_reserve_exact(extent)
            .map_err(|_| publication_input_error("initial prefill section allocation failed"))?;
        bytes.extend_from_slice(Self::MAGIC);
        material_u64(&mut bytes, 3);
        if let Some(value) = value {
            bytes.push(1);
            encode_publication_identity(&mut bytes, value.original);
            material_u64(
                &mut bytes,
                u64::try_from(value.content.len())
                    .map_err(|_| publication_input_error("initial prefill exceeds u64"))?,
            );
            bytes.extend_from_slice(&value.content);
        } else {
            bytes.push(0);
        }
        Ok(bytes)
    }

    fn decode_section(bytes: &[u8]) -> Result<Option<Self>, SemanticTransitionError> {
        let mut reader = SemanticMaterialReader::new(bytes);
        if reader
            .take(Self::MAGIC.len())
            .map_err(SemanticTransitionError::Semantic)?
            != Self::MAGIC
            || reader.u64().map_err(SemanticTransitionError::Semantic)? != 3
        {
            return Err(publication_input_error(
                "checkpoint initial prefill has another domain or version",
            ));
        }
        let result = match reader.u8().map_err(SemanticTransitionError::Semantic)? {
            0 => None,
            1 => {
                let original = decode_publication_identity(&mut reader)?;
                let length =
                    usize::try_from(reader.u64().map_err(SemanticTransitionError::Semantic)?)
                        .map_err(|_| {
                            publication_input_error("checkpoint initial prefill exceeds this host")
                        })?;
                let content = reader
                    .take(length)
                    .map_err(SemanticTransitionError::Semantic)?
                    .to_vec();
                if content.is_empty() {
                    return Err(publication_input_error(
                        "checkpoint initial prefill is empty",
                    ));
                }
                Some(Self {
                    original,
                    content,
                    recovery_referent: None,
                })
            }
            _ => {
                return Err(publication_input_error(
                    "checkpoint initial prefill presence is invalid",
                ));
            }
        };
        reader.finish().map_err(SemanticTransitionError::Semantic)?;
        Ok(result)
    }

    fn verify_content(
        &self,
        semantic_root: Identity256,
        model_generation: u64,
        task_identity: Identity256,
        task_epoch: u64,
        task_content: SemanticTaskContentIdentity,
        prefix_extent: u64,
    ) -> Result<(), SemanticTransitionError> {
        Self::scan_content(&self.content)?.verify(
            semantic_root,
            model_generation,
            task_identity,
            task_epoch,
            task_content,
            prefix_extent,
        )
    }

    fn verify_recorded_content(
        &self,
        task_identity: Identity256,
        task_epoch: u64,
        task_content: SemanticTaskContentIdentity,
    ) -> Result<(), SemanticTransitionError> {
        let decoded = Self::scan_content(&self.content)?;
        decoded.verify(
            decoded.semantic_root,
            decoded.model_generation,
            task_identity,
            task_epoch,
            task_content,
            decoded.token_count as u64,
        )
    }
}

/// Opaque handle to the single imported-task prefill stage. This is not a
/// model-forward receipt; the actual input and outputs must be joined before
/// the parent can be published.
#[derive(Clone)]
pub struct SemanticInitialPrefillLease {
    issuer: Arc<()>,
    scope: Arc<()>,
}

fn validate_initial_prefill_input_layout(
    layout: &SemanticTensorLayout,
    token_count: u64,
) -> Result<(), SemanticTransitionError> {
    let row_bytes = token_count
        .checked_mul(size_of::<i64>() as u64)
        .filter(|_| token_count != 0)
        .ok_or_else(|| {
            publication_input_error("initial prefill requires nonempty admitted prefix tokens")
        })?;
    if *layout
        != (SemanticTensorLayout {
            role: 0,
            index: 0,
            element_bytes: size_of::<i64>() as u64,
            scalar_type: 7,
            rank: 2,
            logical_axis: 1,
            dimensions: [1, token_count, 0, 0],
            strides_bytes: [row_bytes, size_of::<i64>() as u64, 0, 0],
        })
    {
        return Err(publication_input_error(
            "initial prefill input must be the exact contiguous I64 model token tensor [1,prefix]",
        ));
    }
    Ok(())
}

fn same_initial_source_rows(expected: &[SemanticTextSlot], actual: &[SemanticTextSlot]) -> bool {
    expected.len() == actual.len()
        && expected.iter().zip(actual).all(|(expected, actual)| {
            SemanticTextSlot {
                provenance_record: 0,
                ..*expected
            } == SemanticTextSlot {
                provenance_record: 0,
                ..*actual
            }
        })
}

/// Place the exact admitted tokens into an ordered computed prefix and original
/// 32-row ring. No model cache or publication is claimed by this cold plan.
/// The existing parent bind rechecks the same source mapping and cache geometry.
#[expect(
    clippy::too_many_arguments,
    reason = "cold planning checks the admitted source and complete parent text geometry together"
)]
pub fn initial_source_layout(
    sources: &[SemanticObservedSource],
    mapping: &[SemanticSourceMapping],
    authority: &[u8],
    generation: u64,
    provenance_capacity_records: u64,
    prefix_capacity: u64,
    feedback_capacity: u64,
    max_position: u64,
    pad_token: u64,
) -> Result<SemanticInitialSourceLayout, SemanticTransitionError> {
    let invalid = publication_input_error;
    if pad_token >= TEXT_CARDINALITY as u64 {
        return Err(invalid(
            "initial source padding token is outside the text vocabulary",
        ));
    }
    let last_position = mapping.iter().map(|entry| entry.logical_position).max();
    let source_extent = last_position
        .map(|last| {
            last.checked_add(1)
                .ok_or_else(|| invalid("initial source position overflows"))
        })
        .transpose()?
        .unwrap_or(0);
    let prefix_extent = source_extent.saturating_sub(32);
    if prefix_extent > prefix_capacity || prefix_extent > mapping.len() as u64 {
        return Err(invalid(
            "admitted source exceeds its complete prefix capacity",
        ));
    }
    let admitted = sources
        .iter()
        .map(|source| (source.identity.as_str(), source))
        .collect::<BTreeMap<_, _>>();
    let mut tokens = BTreeMap::new();
    for entry in mapping {
        let source = admitted
            .get(entry.source.as_str())
            .ok_or_else(|| invalid("source mapping names an unadmitted payload"))?;
        let offset =
            usize::try_from(entry.offset).map_err(|_| invalid("source token offset overflows"))?;
        let token = *source
            .tokens
            .get(offset)
            .ok_or_else(|| invalid("source mapping token offset is out of range"))?;
        if tokens.insert(entry.logical_position, token).is_some() {
            return Err(invalid("source mapping repeats a logical position"));
        }
    }
    let mut source = [SemanticTextSlot {
        token: pad_token,
        ..SemanticTextSlot::default()
    }; 32];
    let mut prefix = Vec::with_capacity(prefix_extent as usize);
    let mut prefill_tokens = Vec::with_capacity(prefix_extent as usize);
    for position in 0..prefix_extent {
        let token = *tokens
            .get(&position)
            .ok_or_else(|| invalid("computed prefix lacks an admitted source token"))?;
        prefix.push(SemanticTextSlot {
            token,
            logical_position: position,
            kind: 1,
            provenance: 1,
            valid: 1,
            committed: 1,
            ..SemanticTextSlot::default()
        });
        prefill_tokens.push(token);
    }
    for (&position, &token) in tokens.range(prefix_extent..) {
        let index = usize::try_from(position - prefix_extent)
            .map_err(|_| invalid("initial source ring offset overflows"))?;
        if index >= source.len() {
            return Err(invalid("admitted source exceeds its 32-row active ring"));
        }
        source[index] = SemanticTextSlot {
            token,
            logical_position: position,
            kind: 1,
            provenance: 1,
            valid: 1,
            ..SemanticTextSlot::default()
        };
    }
    let (_, _, provenance) = initial_source_ledger(
        source,
        prefix.clone(),
        sources,
        mapping,
        authority,
        generation,
        provenance_capacity_records,
    )?;
    #[cfg(feature = "semantic-policy")]
    let mut prefill_mapping = mapping
        .iter()
        .filter(|entry| entry.logical_position < prefix_extent)
        .cloned()
        .collect::<Vec<_>>();
    #[cfg(feature = "semantic-policy")]
    prefill_mapping.sort_by_key(|entry| entry.logical_position);
    let ring_head = (source_extent - prefix_extent) % 32;
    validate_text_parent(
        &source,
        prefix_extent,
        prefix_capacity,
        feedback_capacity,
        max_position,
        ring_head,
        mapping.len() as u64,
    )?;
    Ok(SemanticInitialSourceLayout {
        source,
        prefix,
        prefill_tokens,
        ring_head,
        #[cfg(feature = "semantic-policy")]
        prefill_mapping,
        provenance_bytes: provenance.bytes,
        provenance_capacity_bytes: provenance.capacity_bytes,
        provenance_records: mapping.len() as u64,
    })
}

impl SemanticParentBinding {
    /// Construct the private initial SOURCE ledger from admitted observations.
    /// The complete authority record is retained in the parent by the same
    /// controller. Fresh GENERATED rows must instead enter through restoration.
    pub fn bind_initial_sources(
        &mut self,
        sources: &[SemanticObservedSource],
        mapping: &[SemanticSourceMapping],
        authority: &[u8],
        capacity_records: u64,
    ) -> Result<(), SemanticTransitionError> {
        if self.recovered_instance.is_some()
            || self.provenance_records != 0
            || self
                .records
                .iter()
                .any(|record| record.role == SemanticStateRole::TokenProvenanceRecords)
            || self.role_counts[SemanticStateRole::TokenProvenanceRecords as usize - 1] != 1
        {
            return Err(publication_input_error(
                "fresh source provenance must be constructed by the controller",
            ));
        }
        let (source, prefix, record) = initial_source_ledger(
            self.source,
            self.prefix.clone(),
            sources,
            mapping,
            authority,
            self.authority_generation,
            capacity_records,
        )?;
        self.source = source;
        self.prefix = prefix;
        self.provenance_records = mapping.len() as u64;
        self.records.push(record);
        Ok(())
    }
}

fn initial_source_ledger(
    mut ring: [SemanticTextSlot; 32],
    mut prefix: Vec<SemanticTextSlot>,
    sources: &[SemanticObservedSource],
    mapping: &[SemanticSourceMapping],
    authority: &[u8],
    generation: u64,
    capacity: u64,
) -> Result<
    (
        [SemanticTextSlot; 32],
        Vec<SemanticTextSlot>,
        SemanticStateRecord,
    ),
    SemanticTransitionError,
> {
    let invalid = publication_input_error;
    let source_count = sources.len();
    let sources = sources
        .iter()
        .map(|source| (source.identity.as_str(), source))
        .collect::<BTreeMap<_, _>>();
    if sources.len() != source_count
        || sources.values().any(|source| {
            source.identity.is_empty()
                || source.origin.is_empty()
                || source.tokens.is_empty()
                || source
                    .tokens
                    .iter()
                    .any(|&token| token >= TEXT_CARDINALITY as u64 || token == MASK_TOKEN as u64)
        })
    {
        return Err(invalid(
            "observed sources require unique identities and complete valid token payloads",
        ));
    }
    if authority.is_empty()
        || generation == 0
        || capacity
            < (mapping.len() as u64)
                .checked_add(32)
                .ok_or_else(|| invalid("source ledger capacity overflows"))?
    {
        return Err(invalid(
            "source ledger requires complete authority and append capacity",
        ));
    }
    let mut positions = BTreeMap::new();
    for entry in mapping {
        let source = sources
            .get(entry.source.as_str())
            .ok_or_else(|| invalid("source mapping names an unadmitted payload"))?;
        let offset =
            usize::try_from(entry.offset).map_err(|_| invalid("source token offset overflows"))?;
        if offset >= source.tokens.len()
            || positions.insert(entry.logical_position, entry).is_some()
        {
            return Err(invalid(
                "source mapping has invalid payload, offset, or duplicate logical position",
            ));
        }
    }
    let authority_digest = Identity256::from_bytes(Sha256::digest(authority).into());
    let mut bytes = Vec::with_capacity(
        mapping
            .len()
            .checked_mul(size_of::<TokenProvenance>())
            .ok_or_else(|| invalid("source ledger extent overflows"))?,
    );
    let mut seen = BTreeSet::new();
    for (physical_slot, slot) in prefix.iter_mut().map(|slot| (u64::MAX, slot)).chain(
        ring.iter_mut()
            .enumerate()
            .map(|(index, slot)| (index as u64, slot)),
    ) {
        if slot.kind != 1 {
            if slot.kind > 2 || slot.provenance != 0 || slot.provenance_record != 0 {
                return Err(invalid(
                    "MASK or PAD cannot carry initial SOURCE provenance",
                ));
            }
            continue;
        }
        let entry = positions.get(&slot.logical_position).ok_or_else(|| {
            invalid("every initial FILLED position requires its exact source mapping")
        })?;
        let source = sources[entry.source.as_str()];
        let token = source.tokens[entry.offset as usize];
        if slot.provenance != 1
            || slot.provenance_record != 0
            || slot.token != token
            || !seen.insert(slot.logical_position)
        {
            return Err(invalid(
                "initial FILLED token differs from its admitted SOURCE payload or position",
            ));
        }
        slot.provenance_record = (bytes.len() / size_of::<TokenProvenance>()) as u64;
        let mut record = TokenProvenance {
            source_slot: physical_slot,
            logical_position: entry.logical_position,
            token,
            // For observed inputs ordinal is the exact payload token offset;
            // no action receipt is invented before a real generated transition.
            ordinal: entry.offset,
            authority_generation: generation,
            origin_logical_digest: Identity256::from_bytes(Sha256::digest(&source.origin).into()),
            authority_closure_origin: authority_digest,
            ..TokenProvenance::default()
        };
        // SAFETY: TokenProvenance is a padding-free repr(C) integral record.
        // Every field was initialized; the private record digest starts at zero.
        let logical = unsafe {
            std::slice::from_raw_parts(
                (&record as *const TokenProvenance).cast::<u8>(),
                size_of::<TokenProvenance>(),
            )
        };
        record.record_digest = Identity256::from_bytes(Sha256::digest(logical).into());
        // SAFETY: the same padding-free initialized record is copied, not borrowed.
        bytes.extend_from_slice(unsafe {
            std::slice::from_raw_parts(
                (&record as *const TokenProvenance).cast::<u8>(),
                size_of::<TokenProvenance>(),
            )
        });
    }
    if seen.len() != mapping.len() {
        return Err(invalid(
            "source mapping includes a MASK, PAD, or absent logical position",
        ));
    }
    let capacity_bytes = usize::try_from(capacity)
        .ok()
        .and_then(|count| count.checked_mul(size_of::<TokenProvenance>()))
        .ok_or_else(|| invalid("source ledger capacity overflows"))?;
    Ok((
        ring,
        prefix,
        SemanticStateRecord {
            role: SemanticStateRole::TokenProvenanceRecords,
            index: 0,
            bytes,
            capacity_bytes,
        },
    ))
}

/// Original model outputs for one acquired parent. The Session supplies their
/// instance, publication word, task and generation binding from its real lease.
pub struct SemanticContinuationInput<D = Vec<u8>> {
    pub tensors: Vec<SemanticTensorInput>,
    /// Exact fresh controller snapshot used to authorize this invocation.
    /// This is not an independently issuable model input or authority claim.
    pub authority_decisions: D,
    /// Original U64[32,2] mapping and U64[1] count, never host-compacted.
    pub text_rows: DlpackManagedTensor,
    pub text_row_count: DlpackManagedTensor,
    /// Original Bool8[32], indexed by acquired source slot.
    pub selected_text: DlpackManagedTensor,
    /// Original U64[A,4] physical mapping and U64[1] count; holes remain holes.
    pub active_rows: DlpackManagedTensor,
    pub active_row_count: DlpackManagedTensor,
    /// Original Bool8[1] ordinary numerical admission predicate.
    pub numerical_admissibility: DlpackManagedTensor,
    /// Optional sealed U64[6] first capacity-denial record for a prepared Update.
    /// Its payload owner is bound separately; only its first-word anchor is hashed.
    pub capacity_refusal: Option<SemanticCapacityRefusalInput>,
    /// Original pre-draw FP64[N,2,3] block bounds. Only proposals draw.
    pub numerical_blocks: Option<DlpackManagedTensor>,
    /// Original sealed model-contract schema digest for this block roster.
    pub model_schema_digest: Option<Identity256>,
    /// Original sealed model-contract identity for this generation.
    pub model_identity: Option<Identity256>,
}

/// Original device cause and retained payload allocation of one prepared Update.
/// After the last reservation writer joins, the first continuation witness seals
/// cause at role zero/index N+6 and anchor at N+7, following N ordinary tensors
/// and six services. The anchor is the payload's initialized first U64 word.
/// Its frozen descriptor must name allocation_ordinal, byte offset zero and the
/// complete payload extent. All owners survive original graph retirement.
pub struct SemanticCapacityRefusalInput {
    pub cause: DlpackManagedTensor,
    pub anchor: DlpackManagedTensor,
    pub payload: DlpackManagedTensor,
    pub allocation_ordinal: u64,
}

/// First denied reservation, in bytes, not application-wide live memory usage.
/// ABI 1 uses reason 0 with all following fields zero, or reason 1 with the
/// original frozen allocation ordinal and requested > capacity - used. The
/// producer records one coherent first failure and never advances its denied
/// cursor. Failure requires the same witness's late numerical predicate false.
#[repr(C)]
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct SemanticCapacityRefusalRecord {
    pub abi: u64,
    pub reason: u64,
    pub allocation_ordinal: u64,
    pub requested_bytes: u64,
    pub used_bytes: u64,
    pub capacity_bytes: u64,
}

// SAFETY: the device ABI is exactly six initialized, padding-free U64 fields.
unsafe impl DeviceRepr for SemanticCapacityRefusalRecord {}

#[cfg(feature = "semantic-policy")]
fn decode_capacity_refusal(
    record: SemanticCapacityRefusalRecord,
    expected: (u64, u64),
) -> Result<Option<SemanticCapacityRefusalRecord>, SemanticTransitionError> {
    if record.abi != 1 {
        return Err(SemanticTransitionError::ObservationMismatch);
    }
    match record.reason {
        0 if record.allocation_ordinal == 0
            && record.requested_bytes == 0
            && record.used_bytes == 0
            && record.capacity_bytes == 0 =>
        {
            Ok(None)
        }
        1 if (record.allocation_ordinal, record.capacity_bytes) == expected
            && record.requested_bytes > 0
            && record.used_bytes <= record.capacity_bytes
            && record.requested_bytes > record.capacity_bytes - record.used_bytes =>
        {
            Ok(Some(record))
        }
        _ => Err(SemanticTransitionError::ObservationMismatch),
    }
}

fn continuation_service_layouts(
    first_index: usize,
    capacity: u64,
    physical_blocks: Option<usize>,
) -> Result<Vec<SemanticTensorLayout>, SemanticTransitionError> {
    let first_index = u64::try_from(first_index)
        .ok()
        .filter(|index| {
            index
                .checked_add(if physical_blocks.is_some() { 6 } else { 5 })
                .is_some()
        })
        .ok_or_else(|| publication_input_error("continuation service roster overflow"))?;
    if capacity < 34 {
        return Err(publication_input_error(
            "continuation active capacity lacks its source and feedback slots",
        ));
    }
    let layout = |offset, scalar_type, element_bytes, rank, dimensions| {
        canonical_tensor_layout(SemanticTensorLayout {
            role: 0,
            index: first_index + offset,
            scalar_type,
            element_bytes,
            rank,
            dimensions,
            logical_axis: u64::MAX,
            strides_bytes: [0; 4],
        })
    };
    let mut layouts = vec![
        layout(0, 3, 8, 2, [32, 2, 0, 0])?,
        layout(1, 3, 8, 1, [1, 0, 0, 0])?,
        layout(2, 8, 1, 1, [32, 0, 0, 0])?,
        layout(3, 3, 8, 2, [capacity, 4, 0, 0])?,
        layout(4, 3, 8, 1, [1, 0, 0, 0])?,
        layout(5, 8, 1, 1, [1, 0, 0, 0])?,
    ];
    if let Some(blocks) = physical_blocks {
        layouts.push(layout(6, 9, 8, 3, [blocks as u64, 2, 3, 0])?);
    }
    Ok(layouts)
}

/// Decode the retained versioned schema from the original ModelContract slice.
fn retained_model_schema(
    record: &[u8],
    layout: SemanticModelContractLayout,
) -> Result<Option<serde_json::Value>, SemanticTransitionError> {
    layout.validate(record.len() as u64)?;
    let begin = layout.schema_begin as usize;
    let end = begin + layout.schema_bytes as usize;
    let Ok(schema) = serde_json::from_slice::<serde_json::Value>(&record[begin..end]) else {
        return Ok(None);
    };
    if schema
        .get("counter_encoding")
        .and_then(serde_json::Value::as_str)
        != Some("u32-hex8")
    {
        return Ok(None);
    }
    Ok(Some(schema))
}

/// Derive unique physical parameter owners from that same authenticated schema.
/// Other schema formats cannot claim this block-bound admission contract.
fn model_physical_parameter_roster(
    record: &[u8],
    layout: SemanticModelContractLayout,
) -> Result<Option<Vec<String>>, SemanticTransitionError> {
    let Some(schema) = retained_model_schema(record, layout)? else {
        return Ok(None);
    };
    let (physical, count) = model_physical_parameters(&schema)?;
    let mut names = Vec::with_capacity(count);
    for (name, entry) in physical {
        if entry.get("kind").and_then(serde_json::Value::as_str) == Some("parameter") {
            names.push(name.clone());
        }
    }
    names.sort_unstable();
    Ok(Some(names))
}

fn model_physical_parameters(
    schema: &serde_json::Value,
) -> Result<(&serde_json::Map<String, serde_json::Value>, usize), SemanticTransitionError> {
    let model = schema
        .get("model")
        .ok_or_else(|| publication_input_error("versioned model schema lacks its model owner"))?;
    let physical = model
        .get("physical")
        .and_then(serde_json::Value::as_object)
        .ok_or_else(|| publication_input_error("model schema lacks its physical owner roster"))?;
    let mut count = 0usize;
    for entry in physical.values() {
        match entry.get("kind").and_then(serde_json::Value::as_str) {
            Some("parameter") => {
                count = count
                    .checked_add(1)
                    .ok_or(SemanticTransitionError::GenerationExhausted)?
            }
            Some("buffer") => {}
            _ => {
                return Err(publication_input_error(
                    "model physical roster has an unknown owner kind",
                ));
            }
        }
    }
    if count == 0 {
        return Err(publication_input_error(
            "model physical roster has no parameter owners",
        ));
    }
    Ok((physical, count))
}

fn model_physical_parameter_count(
    record: &[u8],
    layout: SemanticModelContractLayout,
) -> Result<Option<usize>, SemanticTransitionError> {
    retained_model_schema(record, layout)?
        .as_ref()
        .map(|schema| model_physical_parameters(schema).map(|(_, count)| count))
        .transpose()
}

/// Authenticate parameter-leaf coordinates independently of the full model
/// content roster, which also includes non-differentiable buffers. Frozen
/// Parameters remain leaves even when they have no gradient allocation.
fn model_physical_parameter_coordinates(
    record: &[u8],
    layout: SemanticModelContractLayout,
) -> Result<Option<BTreeSet<(u64, u64)>>, SemanticTransitionError> {
    let Some(names) = model_physical_parameter_roster(record, layout)? else {
        return Ok(None);
    };
    let schema = retained_model_schema(record, layout)?
        .ok_or(SemanticTransitionError::ObservationMismatch)?;
    let Some(learning) = schema["model"]
        .get("learning")
        .filter(|value| !value.is_null())
    else {
        return Ok(None);
    };
    let views = learning
        .get("views")
        .and_then(serde_json::Value::as_array)
        .ok_or_else(|| publication_input_error("model learning schema lacks its typed views"))?;
    let leaves = learning
        .get("leaves")
        .and_then(serde_json::Value::as_array)
        .ok_or_else(|| {
            publication_input_error("model learning schema lacks its parameter leaves")
        })?;
    let expected = names.iter().map(String::as_str).collect::<BTreeSet<_>>();
    let mut owners = BTreeSet::new();
    let mut coordinates = BTreeSet::new();
    for leaf in leaves {
        let view = leaf
            .get("effective")
            .and_then(serde_json::Value::as_u64)
            .and_then(|index| usize::try_from(index).ok())
            .and_then(|index| views.get(index))
            .ok_or_else(|| {
                publication_input_error("parameter leaf has no original effective view")
            })?;
        // The view name is the physical leaf's name. Its serialized tensor
        // owner may be another alias and does not classify parameter/buffer.
        let name = view
            .get("name")
            .and_then(serde_json::Value::as_str)
            .ok_or_else(|| {
                publication_input_error("parameter effective view lacks its physical owner")
            })?;
        let coordinate = view
            .get("layout")
            .and_then(serde_json::Value::as_array)
            .filter(|layout| layout.len() >= 2)
            .and_then(|layout| Some((layout[0].as_u64()?, layout[1].as_u64()?)))
            .ok_or_else(|| {
                publication_input_error("parameter effective view lacks its native coordinates")
            })?;
        if !expected.contains(name)
            || !owners.insert(name)
            || !(18..=20).contains(&coordinate.0)
            || !coordinates.insert(coordinate)
        {
            return Err(publication_input_error(
                "parameter leaf roster changed its original physical owners or coordinates",
            ));
        }
    }
    if owners != expected {
        return Err(publication_input_error(
            "parameter leaf roster omits an original physical Parameter",
        ));
    }
    Ok(Some(coordinates))
}

/// Identity of one packed active-cache row in its original forward. Kinds are
/// FILLED=1, MASK=2 and FEEDBACK=3; physical_row is not the packed coordinate.
#[repr(C)]
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct SemanticActiveRow {
    pub physical_row: u64,
    pub source_slot: u64,
    pub logical_position: u64,
    pub kind: u64,
}

/// Acquired bank-local active-cache state. A computed empty result has no rows
/// but is distinct from the initial parent which has never consumed a forward.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct SemanticActiveRows {
    pub computed: bool,
    pub rows: Vec<SemanticActiveRow>,
}

/// One original compact model row; source_slot is the acquired ring identity,
/// never the packed model coordinate. The row's array index identifies logits.
#[repr(C)]
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct SemanticTextRow {
    pub source_slot: u64,
    pub logical_position: u64,
}
// SAFETY: padding-free C representation containing only two initialized u64s.
unsafe impl DeviceRepr for SemanticTextRow {}

#[repr(C)]
#[derive(Clone, Copy, Default)]
struct TextBinding {
    rows: u64,
    count: u64,
    selected: u64,
}

struct TextBindingStorage {
    inputs: Vec<PreparedSemanticTensor>,
    capacity_refusal: Option<BoundCapacityRefusal>,
    numerical_block_snapshot: Option<Arc<TrackedCudaSlice<f64>>>,
    model_contract: Option<DeviceMemoryView<u8>>,
    physical_blocks: u64,
    model_schema_digest: Identity256,
    model_identity: Identity256,
    _witness: SemanticTensorOwner,
    _model_owner: Option<SemanticTensorOwner>,
    consumer_stream: u64,
    parent: TextBindingParent,
}

struct BoundCapacityRefusal {
    snapshot: Arc<TrackedCudaSlice<SemanticCapacityRefusalRecord>>,
    payload: PreparedSemanticTensor,
    allocation_ordinal: u64,
    capacity_bytes: u64,
}

#[expect(
    clippy::large_enum_variant,
    reason = "the published header stays inline on the latency-sensitive export path"
)]
enum TextBindingParent {
    Published {
        bank: usize,
        header: PublicationHeader,
    },
    Prepared(Arc<PreparedStepInputs>),
}

impl TextBindingStorage {
    fn published_parent(&self) -> Result<(usize, PublicationHeader), SemanticTransitionError> {
        match &self.parent {
            TextBindingParent::Published { bank, header } => Ok((*bank, *header)),
            TextBindingParent::Prepared(_) => Err(publication_input_error(
                "a prepared invocation has no host-observed parent header",
            )),
        }
    }
    fn descriptor(&self) -> TextBinding {
        TextBinding {
            rows: self.inputs[0].data,
            count: self.inputs[1].data,
            selected: self.inputs[2].data,
        }
    }

    fn record(&self, recorder: &mut LaunchRecorder) {
        for input in &self.inputs {
            if let Some(source) = &input.source {
                recorder.read(source);
            }
        }
        if let Some(snapshot) = &self.numerical_block_snapshot {
            recorder.read(snapshot.as_ref());
        }
        if let Some(cause) = &self.capacity_refusal {
            recorder.read_write(cause.snapshot.as_ref());
            if let Some(payload) = &cause.payload.source {
                recorder.read(payload);
            }
        }
        if let Some(contract) = &self.model_contract {
            recorder.read(contract);
        }
    }

    fn continuation_inputs(
        &self,
        kind: SemanticTransitionKind,
        authority_bytes: u64,
        training_selection: u64,
        model_update: ModelUpdateContinuationInputs,
    ) -> ContinuationInputs {
        ContinuationInputs {
            text: self.descriptor(),
            active_rows: self.inputs[3].data,
            active_row_count: self.inputs[4].data,
            numerical_admissibility: self.inputs[5].data,
            numerical_blocks: self
                .numerical_block_snapshot
                .as_ref()
                .map_or(0, |snapshot| snapshot.device_ptr_value()),
            physical_blocks: self.physical_blocks,
            model_schema_digest: self.model_schema_digest,
            model_identity: self.model_identity,
            model_contract: self
                .model_contract
                .as_ref()
                .map_or(0, |contract| *contract.device_ptr()),
            model_contract_bytes: self
                .model_contract
                .as_ref()
                .map_or(0, |contract| contract.len() as u64),
            transition_kind: kind.code(),
            authority_bytes,
            training_selection,
            model_update_bindings: model_update.bindings,
            model_update_binding_count: model_update.binding_count,
            model_update_admissibility: model_update.admissibility,
            model_update_refusal: model_update.refusal,
            model_update_canary_results: model_update.canary_results,
            model_update_canaries: model_update.canaries,
            capacity_refusal_source: if self.capacity_refusal.is_some() {
                self.inputs[6].data
            } else {
                0
            },
            capacity_refusal: self
                .capacity_refusal
                .as_ref()
                .map_or(0, |cause| cause.snapshot.device_ptr_value()),
            capacity_allocation_ordinal: self
                .capacity_refusal
                .as_ref()
                .map_or(0, |cause| cause.allocation_ordinal),
            capacity_bytes: self
                .capacity_refusal
                .as_ref()
                .map_or(0, |cause| cause.capacity_bytes),
        }
    }
}

fn enqueue_numerical_block_snapshot(
    provider: &CudaKernelProvider,
    domain: &ResidentExecutionDomain,
    poisoned: &mut bool,
    original: &PreparedSemanticTensor,
    destination: &TrackedCudaSlice<f64>,
    work: Option<DeviceMemoryView<u64>>,
) -> Result<(), SemanticTransitionError> {
    let source = original
        .source
        .as_ref()
        .ok_or_else(|| publication_input_error("original block bounds have no device storage"))?;
    let bytes = destination
        .len()
        .checked_mul(size_of::<f64>())
        .ok_or(SemanticTransitionError::GenerationExhausted)?;
    if source.len() != bytes {
        return Err(publication_input_error(
            "original block bounds differ from the frozen native capacity",
        ));
    }
    let bytes = u64::try_from(bytes).map_err(|_| SemanticTransitionError::GenerationExhausted)?;
    let execute = provider
        .device()
        .inner()
        .get_func(
            "xlog_semantic_transition",
            "semantic_numerical_block_snapshot",
        )
        .ok_or_else(|| runtime_error("kernel lookup", "block bound snapshot unavailable"))?;
    let mut recorder = domain.new_strict_recorder();
    recorder.read(source);
    recorder.write(destination);
    if let Some(work) = &work {
        recorder.read_write(work);
    }
    let arguments = (
        *source.device_ptr(),
        destination.device_ptr_value(),
        bytes,
        work.as_ref().map_or(0, |work| *work.device_ptr()),
    );
    enqueue_recorded(domain, poisoned, recorder, |enqueue| {
        // SAFETY: the original typed witness established the exact contiguous
        // FP64 span. The disjoint destination and original tally share this
        // command's recorded allocation and completion custody.
        unsafe {
            execute.launch_in(
                enqueue,
                LaunchConfig {
                    grid_dim: (1, 1, 1),
                    block_dim: (1, 1, 1),
                    shared_mem_bytes: 0,
                },
                arguments,
            )
        }
        .map_err(|error| XlogError::Kernel(format!("block bound snapshot: {error}")))
    })
}

/// Native publication origin and current physical selection. This carries
/// lineage, not a contents proof or an independently issuable use authority.
