impl PreparedSegmentState {
    fn new(
        issuer: Arc<()>,
        tokens: Vec<u64>,
        transitions: impl ExactSizeIterator<Item = SemanticTransitionKind> + Clone,
        cold_capacity: SemanticSegmentColdCapacity,
    ) -> Result<Self, SemanticTransitionError> {
        if tokens.is_empty()
            || tokens.contains(&0)
            || tokens.iter().copied().collect::<BTreeSet<_>>().len() != tokens.len()
            || tokens.len() != transitions.len()
            || transitions
                .clone()
                .any(|kind| kind == SemanticTransitionKind::Drain)
        {
            return Err(publication_input_error(
                "a prepared segment requires distinct owned steps and one frozen proposal, recompute, or update mode per step",
            ));
        }
        let mut owned = Vec::new();
        owned
            .try_reserve_exact(transitions.len())
            .map_err(|error| runtime_error("prepared schedule reservation", error))?;
        owned.extend(transitions);
        cold_capacity.external_floor()?;
        Ok(Self {
            issuer,
            scope: Arc::new(()),
            tokens,
            transitions: owned,
            cold_capacity,
            cold_reservation: None,
            derived_layout: None,
            layout_reservation: None,
            layout_allocation_failed: false,
            publication: None,
            #[cfg(feature = "semantic-policy")]
            model_input_generations: None,
            structural_only: false,
            structural_frozen: false,
            recording_ready: Arc::new(AtomicBool::new(false)),
            initialization: None,
            initialization_pending: AtomicBool::new(false),
            metadata_freeze: None,
            metadata_pending: AtomicBool::new(false),
            next: 0,
            active: false,
            finished: false,
            capturing: false,
            submitted: false,
            completed: false,
            execution_poisoned: false,
            graph_call_entered: false,
            launch_attempt: None,
            authority_upload: None,
            never_graph_called: None,
            cancelled: Arc::new(AtomicBool::new(false)),
            construction: Arc::new(Mutex::new(())),
            graph_retirement: None,
            parent_reader: None,
            original_parent: None,
            #[cfg(feature = "semantic-policy")]
            program_steps: BTreeMap::new(),
            #[cfg(feature = "semantic-policy")]
            program_admission: None,
            #[cfg(feature = "semantic-policy")]
            actor_refresh_execution: Arc::new(Mutex::new(
                actor_refresh::ActorRefreshParentExecution::Constructing,
            )),
            #[cfg(feature = "semantic-policy")]
            actor_refresh_observation: None,
            parent_quiescent: false,
            transfers: None,
            completion_observations: PreparedSegmentCompletionObservations::default(),
            final_consumers: BTreeMap::new(),
        })
    }

    fn handles(&self) -> Result<Vec<SemanticPreparedStep>, SemanticTransitionError> {
        let mut handles = Vec::new();
        handles
            .try_reserve_exact(self.tokens.len())
            .map_err(|error| runtime_error("prepared handle reservation", error))?;
        handles.extend(self.tokens.iter().map(|&token| SemanticPreparedStep {
            issuer: Arc::clone(&self.issuer),
            scope: Arc::clone(&self.scope),
            token,
        }));
        Ok(handles)
    }

    fn check(
        &self,
        step: &SemanticPreparedStep,
        issuer: &Arc<()>,
        recording: bool,
    ) -> Result<(), SemanticTransitionError> {
        self.check_retained(step, issuer)?;
        if self.finished
            || self.cancelled.load(Ordering::Acquire)
            || (recording
                && (self.structural_only
                    || !self.recording_ready.load(Ordering::Acquire)
                    || !self.active
                    || self.tokens.get(self.next) != Some(&step.token)))
        {
            return Err(publication_input_error(
                "prepared step differs from its owning Session or active construction scope",
            ));
        }
        Ok(())
    }

    fn check_retained(
        &self,
        step: &SemanticPreparedStep,
        issuer: &Arc<()>,
    ) -> Result<(), SemanticTransitionError> {
        if !Arc::ptr_eq(issuer, &self.issuer)
            || !Arc::ptr_eq(&step.issuer, issuer)
            || !Arc::ptr_eq(&step.scope, &self.scope)
            || !self.tokens.contains(&step.token)
        {
            return Err(publication_input_error(
                "retained prepared step differs from its original Session and construction scope",
            ));
        }
        Ok(())
    }

    fn requested_kind(
        &self,
        step: &SemanticPreparedStep,
        issuer: &Arc<()>,
    ) -> Result<SemanticTransitionKind, SemanticTransitionError> {
        self.check_retained(step, issuer)?;
        let index = self
            .tokens
            .iter()
            .position(|&token| token == step.token)
            .ok_or(SemanticTransitionError::ObservationMismatch)?;
        Ok(self.transitions[index])
    }

    fn enter(
        &mut self,
        step: &SemanticPreparedStep,
        issuer: &Arc<()>,
    ) -> Result<SemanticTransitionKind, SemanticTransitionError> {
        self.check(step, issuer, false)?;
        if self.structural_only
            || !self.recording_ready.load(Ordering::Acquire)
            || self.active
            || self.tokens.get(self.next) != Some(&step.token)
        {
            return Err(publication_input_error(
                "prepared steps must record once in their original bounded order",
            ));
        }
        self.active = true;
        Ok(self.transitions[self.next])
    }

    fn leave(
        &mut self,
        step: &SemanticPreparedStep,
        issuer: &Arc<()>,
    ) -> Result<(), SemanticTransitionError> {
        self.check(step, issuer, true)?;
        self.active = false;
        self.next += 1;
        Ok(())
    }

    fn require_finish(&self) -> Result<(), SemanticTransitionError> {
        if self.finished
            || self.cancelled.load(Ordering::Acquire)
            || self.active
            || self.next != self.tokens.len()
        {
            return Err(publication_input_error(
                "prepared segment has unrecorded or unfinished steps",
            ));
        }
        Ok(())
    }

    fn finish(&mut self) -> Result<(), SemanticTransitionError> {
        self.require_finish()?;
        self.finished = true;
        Ok(())
    }

    #[cfg(any(test, feature = "semantic-policy"))]
    fn submit(&mut self) -> Result<(), SemanticTransitionError> {
        if !self.finished
            || self.active
            || self.next != self.tokens.len()
            || self.submitted
            || self.completed
            || self.cancelled.load(Ordering::Acquire)
        {
            return Err(publication_input_error(
                "prepared segment submission requires one complete unused construction",
            ));
        }
        self.submitted = true;
        Ok(())
    }

    fn require_cancellable(
        &self,
        steps: &[SemanticPreparedStep],
    ) -> Result<(), SemanticTransitionError> {
        if (self.submitted && !self.has_never_graph_called_proof())
            || self.completed
            || self.cancelled.load(Ordering::Acquire)
            || steps.len() != self.tokens.len()
            || steps.iter().zip(&self.tokens).any(|(step, token)| {
                step.token != *token || self.check_retained(step, &self.issuer).is_err()
            })
        {
            return Err(publication_input_error(
                "non-submission requires the complete original unused prepared roster",
            ));
        }
        Ok(())
    }

    fn require_non_submission(
        &self,
        proof: &SemanticPreparedSegmentNonSubmission,
    ) -> Result<(), SemanticTransitionError> {
        if (self.submitted && !self.has_never_graph_called_proof())
            || self.completed
            || !self.cancelled.load(Ordering::Acquire)
            || proof.steps.len() != self.tokens.len()
            || proof.steps.iter().zip(&self.tokens).any(|(step, token)| {
                step.token != *token || self.check_retained(step, &self.issuer).is_err()
            })
        {
            return Err(publication_input_error(
                "cancelled custody requires its genuine whole-roster non-submission proof",
            ));
        }
        Ok(())
    }

    fn has_never_graph_called_proof(&self) -> bool {
        !self.graph_call_entered
            && self.never_graph_called.as_ref().is_some_and(|proof| {
                Arc::ptr_eq(&proof.scope, &self.scope)
                    && self.launch_attempt.as_ref().is_some_and(|attempt| {
                        Arc::ptr_eq(attempt, &proof.attempt)
                            && attempt.closed.load(Ordering::Acquire)
                    })
            })
    }

    // The Session closes construction under known capture exclusion before any
    // join attempt. It may return the retained proof only after all joins finish;
    // unknown completion keeps construction closed without issuing that proof.
    fn cancel(
        &mut self,
        steps: &[SemanticPreparedStep],
    ) -> Result<SemanticPreparedSegmentNonSubmission, SemanticTransitionError> {
        self.require_cancellable(steps)?;
        self.cancelled.store(true, Ordering::Release);
        Ok(SemanticPreparedSegmentNonSubmission {
            steps: steps.to_vec(),
        })
    }
}

#[cfg(feature = "semantic-policy")]
#[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
