impl PreparedModelUpdate {
    fn descriptor(&self) -> ModelUpdateContinuationInputs {
        ModelUpdateContinuationInputs {
            bindings: self.bindings.device_ptr_value(),
            binding_count: self.bindings.len() as u64,
            admissibility: self.admissibility.device_ptr_value(),
            refusal: self.refusal.device_ptr_value(),
            canary_results: self.canary_results.device_ptr_value(),
            canaries: self.canaries.as_ref().map_or(0, |view| *view.device_ptr()),
        }
    }

    fn record(&self, recorder: &mut LaunchRecorder) -> Result<(), SemanticTransitionError> {
        if let Some(canaries) = &self.canaries {
            recorder.read(canaries);
        }
        recorder.read(&self.bindings);
        recorder.read(self.evidence.as_ref());
        for evidence in self.evidence_owners.iter() {
            recorder.read(&evidence.lease);
            recorder.read(&evidence.parent_header);
            recorder.read(&evidence.result);
            recorder.read(&evidence.origin);
            recorder.read(&evidence.states[0]);
            recorder.read(&evidence.states[1]);
        }
        recorder.read_write(&self.forward_receipts);
        #[cfg(feature = "semantic-policy")]
        {
            for stream in self.forward_streams.iter().flatten() {
                stream.record(recorder)?;
            }
            if let Some(stream) = &self.canary_stream {
                stream.record(recorder)?;
            }
        }
        recorder.read_write(&self.admissibility);
        recorder.read_write(&self.refusal);
        recorder.read_write(&self.canary_results);
        if let Some(output) = &self.output {
            for allocation in &output.allocations {
                if let Some(source) = &allocation.source {
                    recorder.read(source);
                }
            }
            if let Some(source) = &output.admissibility.source {
                recorder.read(source);
            }
            for scratch in &output.stream_scratch {
                if let Some(source) = &scratch.source {
                    recorder.read(source);
                }
            }
        }
        Ok(())
    }

    #[cfg(feature = "semantic-policy")]
    #[expect(
        clippy::too_many_arguments,
        reason = "the update gate joins publication, training, task and original model-work owners"
    )]
    fn enqueue_acceptance(
        &self,
        domain: &ResidentExecutionDomain,
        poisoned: &mut bool,
        storage: &PublicationStorage,
        reader: &TrackedCudaSlice<PublicationLease>,
        training_view: &SemanticSelectedTrainingView,
        task: &TrackedCudaSlice<u64>,
        model_work: &PreparedModelWork,
        bank: usize,
        native_resident_bytes: u64,
        native_work: DeviceMemoryView<u64>,
    ) -> Result<(), SemanticTransitionError> {
        let output = self.output.as_ref().ok_or_else(|| {
            publication_input_error("prepared update has no original model output binding")
        })?;
        let mut recorder = domain.new_strict_recorder();
        storage.record(&mut recorder);
        recorder.read(reader);
        self.record(&mut recorder)?;
        model_work.record_reads(&mut recorder);
        recorder.read(task);
        let selection = training_view.selection();
        let roster_rows = training_view.roster_rows();
        let objective = training_view.objective();
        let canaries = training_view.canaries();
        let protected_members = training_view.protected_members();
        let retention_labels = training_view.retention_labels();
        let kinds = training_view.kinds();
        recorder.read(&selection);
        recorder.read(&roster_rows);
        recorder.read(&objective);
        recorder.read(&canaries);
        recorder.read(&protected_members);
        recorder.read(&retention_labels);
        recorder.read(&kinds);
        recorder.write(&self.canary_results);
        recorder.write(&self.admissibility);
        recorder.write(&self.refusal);
        recorder.read_write(&native_work);
        let admissibility_source = output.admissibility.data;
        let canary_results = self.canary_results.device_ptr_value();
        let admissibility_destination = self.admissibility.device_ptr_value();
        let refusal_destination = self.refusal.device_ptr_value();
        // All source, target, replay-child, tape and prepared allocations are
        // charged to the same original native manager. Count its actual live
        // charge once, not a hand-selected subset of this Update's views.
        let accounted_reserved_bytes = output
            .accounted_external_bytes
            .checked_add(native_resident_bytes)
            .ok_or(SemanticTransitionError::GenerationExhausted)?;
        let [baseline, candidate] = self.forward_streams.each_ref().map(|stream| {
            stream
                .as_ref()
                .ok_or(SemanticTransitionError::ObservationMismatch)
        });
        let baseline = baseline?;
        let candidate = candidate?;
        let comparison = self
            .canary_stream
            .as_ref()
            .ok_or(SemanticTransitionError::ObservationMismatch)?;
        let (row_count, capacity, vocabulary, scalar_type, block_positions) = baseline.geometry();
        let canary_inputs = ModelUpdateCanaryInputs {
            control: storage.control.device_ptr_value(),
            lease: reader.device_ptr_value(),
            selection: *selection.device_ptr(),
            roster_rows: *roster_rows.device_ptr(),
            objective: *objective.device_ptr(),
            canaries: *canaries.device_ptr(),
            canary_count: canaries.len() as u64,
            protected_members: *protected_members.device_ptr(),
            protected_member_count: protected_members.len() as u64,
            task: task.device_ptr_value(),
            task_words: task.len() as u64,
            evidence: self.evidence.device_ptr_value(),
            evidence_count: self.evidence.len() as u64,
            forward_receipts: self.forward_receipts.device_ptr_value(),
            retention_labels: *retention_labels.device_ptr(),
            kinds: *kinds.device_ptr(),
            baseline_state: baseline.state_pointer(),
            candidate_state: candidate.state_pointer(),
            baseline_row_seals: baseline.row_seals_pointer(),
            candidate_row_seals: candidate.row_seals_pointer(),
            comparison_state: comparison.state_pointer(),
            comparison_receipt: comparison.receipt_pointer(),
            scalar_type,
            row_count,
            capacity,
            vocabulary,
            block_positions,
            model_work: model_work.descriptor_for_bank(bank),
            accounted_reserved_bytes,
            // Initialization is original producer work. Native acceptance
            // publishes this exact pending generation without a second copy.
            copy_bytes: 0,
            admissibility_source,
            results: canary_results,
            admissibility_destination,
            refusal_destination,
            native_work: *native_work.device_ptr(),
        };
        enqueue_recorded(domain, poisoned, recorder, |enqueue| {
            // SAFETY: the producer gate was checked by the same captured
            // content witness as the complete update backing. The native byte
            // is the stable predicate consumed by the sole publication.
            unsafe {
                self.admissibility_copy.clone().launch_in(
                    enqueue,
                    LaunchConfig {
                        grid_dim: (1, 1, 1),
                        block_dim: (1, 1, 1),
                        shared_mem_bytes: 0,
                    },
                    (canary_inputs,),
                )
            }
            .map_err(|error| XlogError::Kernel(error.to_string()))
        })
    }
}

struct PreparedModelWork {
    recording: ModelWorkRecording,
    second_recording: Option<ModelWorkRecording>,
    content_banks: BTreeMap<usize, usize>,
    device: TrackedCudaSlice<ModelWorkEvent>,
    actual: TrackedCudaSlice<u64>,
    reset: CudaFunction,
    invocation: CudaFunction,
    capture_bank: Option<usize>,
    replay_cursor: usize,
    uncaptured_recording: bool,
}

const PREPARED_TRANSITION_BANKS: u8 = 0b11;

#[repr(C)]
#[derive(Clone, Copy, Default)]
