#[cfg(feature = "semantic-policy")]
#[expect(
    clippy::too_many_arguments,
    reason = "policy VJP launch retains each original producer and destination explicitly"
)]
fn record_policy_vjp(
    domain: &ResidentExecutionDomain,
    poisoned: &mut bool,
    mut recorder: LaunchRecorder,
    execute: CudaFunction,
    mut descriptor: Descriptor,
    coefficients: &TrackedCudaSlice<f64>,
    score_cotangents: Option<&DeviceMemoryView<f64>>,
    baseline_snapshot: Option<&DeviceMemoryView<f32>>,
    work: DeviceMemoryView<u64>,
) -> Result<(), SemanticTransitionError> {
    if work.len() != 11 || !work.device_ptr().is_multiple_of(8) {
        return Err(publication_input_error(
            "policy backward requires its original complete native work cell",
        ));
    }
    if coefficients.len() != COMPONENT_COUNT
        || descriptor.backward.cotangents != coefficients.device_ptr_value()
        || score_cotangents.is_some_and(|source| source.len() < COMPONENT_COUNT)
        || baseline_snapshot.is_some_and(|source| source.len() < COMPONENT_COUNT)
    {
        return Err(SemanticTransitionError::ObservationMismatch);
    }
    descriptor.backward.work = *work.device_ptr();
    descriptor.backward.baseline_snapshot =
        baseline_snapshot.map_or(0, |source| *source.device_ptr());
    descriptor.backward.score_cotangent_snapshot =
        score_cotangents.map_or(0, |source| *source.device_ptr());
    if let Some(source) = baseline_snapshot {
        recorder.read(source);
    }
    if let Some(source) = score_cotangents {
        recorder.read(source);
    }
    recorder.write(&work);
    enqueue_recorded(domain, poisoned, recorder, |enqueue| {
        // SAFETY: the recorder retains every forward/output allocation and,
        // for the external mode, the original cotangent producer. The
        // destination is the fixed F64 bank owned by this exact invocation.
        // The same original kernel snapshots the supplied resident sources
        // before its guards and produces their actual byte tally. A failed
        // launch therefore cannot leave a separately submitted copy prefix.
        // Selected mode still fills the F64 bank from resident objective/state
        // owners without an external cotangent copy.
        unsafe {
            execute
                .launch_in(
                    enqueue,
                    LaunchConfig {
                        grid_dim: (1, 1, 1),
                        block_dim: (256, 1, 1),
                        shared_mem_bytes: 0,
                    },
                    (descriptor,),
                )
                .map_err(|error| XlogError::Kernel(format!("policy backward launch: {error}")))?;
        }
        Ok::<(), XlogError>(())
    })
}

/// Dedicated device-owned adjoints for one exact policy invocation. Their tracked
/// allocations can be consumed on another recorded stream without host copies.
#[cfg(feature = "semantic-policy")]
pub struct SemanticPolicyGradients {
    pub binding: SemanticCatalogueBinding,
    pub invocation: SemanticRngBinding,
    pub layout: SemanticPolicyLayout,
    pub parameters: TrackedCudaSlice<f32>,
    pub text_logits: TrackedCudaSlice<f32>,
    pub component_baselines: TrackedCudaSlice<f32>,
    numerical: Arc<PolicyAdjointNumerical>,
    provider: Arc<CudaKernelProvider>,
    step_aliases: Arc<()>,
    publication: Arc<PublicationStorage>,
    continuation: Arc<TextBindingStorage>,
    vjp_workspace: Arc<PolicyVjpWorkspace>,
    support_cells: usize,
}

#[cfg(feature = "semantic-policy")]
impl SemanticPolicyGradients {
    /// Export parameter, full MASK and baseline adjoints, then their three
    /// FP64 error envelopes and three selected magnitude/error bounds.
    /// Baseline adjoints are exact zeros for externally supplied score roots.
    /// Backward already ordered the caller's explicit consumer stream after the
    /// device error guard. Final step release joins that consumer's last use.
    pub fn into_dlpack(self) -> Result<[DlpackManagedTensor; 9], SemanticTransitionError> {
        let retained_owner: Arc<dyn Send + Sync> = self.vjp_workspace;
        export_policy_gradients(
            [
                self.parameters.into_bytes().view(),
                self.text_logits.into_bytes().view(),
                self.component_baselines.into_bytes().view(),
            ],
            &self.numerical,
            self.support_cells,
            self.layout.parameter_cells,
            self.provider.device().ordinal() as i32,
            self.step_aliases,
            self.publication,
            self.continuation,
            retained_owner,
        )
    }
}

/// Device-selected policy roots recorded inside a prepared Update branch.
/// The retained native bank remains reusable while the mutually exclusive
/// Update branches are captured; every export is a fresh DLPack view.
#[cfg(feature = "semantic-policy")]
pub struct SemanticPreparedPolicyGradients {
    pub layout: SemanticPolicyLayout,
    parameters: DeviceMemoryView<f32>,
    text_logits: DeviceMemoryView<f32>,
    component_baselines: DeviceMemoryView<f32>,
    provider: Arc<CudaKernelProvider>,
    step_aliases: Arc<()>,
    publication: Arc<PublicationStorage>,
    continuation: Arc<TextBindingStorage>,
    owner: Arc<PolicyAdjointBuffers>,
    support_cells: usize,
}

/// One fixed FP32[1] device scalar reduced in frozen actor-group order inside
/// the prepared Update bank. Its value is detached from the model graph; the
/// corresponding critic adjoints are returned with each original policy VJP.
#[cfg(feature = "semantic-policy")]
pub struct SemanticPreparedGroupCritic {
    value: DeviceMemoryView<f32>,
    provider: Arc<CudaKernelProvider>,
    step_aliases: Arc<()>,
    publication: Arc<PublicationStorage>,
}

#[cfg(feature = "semantic-policy")]
impl SemanticPreparedGroupCritic {
    pub fn into_dlpack(self) -> Result<DlpackManagedTensor, SemanticTransitionError> {
        let layout = group_critic_output_layout()?;
        Ok(export_owned_allocation(
            unsafe { self.value.cast::<u8>() }.expect("FP32 group critic byte view"),
            vec![layout.dimensions[0] as i64],
            vec![(layout.strides_bytes[0] / layout.element_bytes) as i64],
            (2, (layout.element_bytes * 8) as u8),
            self.provider.device().ordinal() as i32,
            self.step_aliases,
            Some(self.publication),
            None,
            None,
        ))
    }
}

#[cfg(feature = "semantic-policy")]
impl SemanticPreparedPolicyGradients {
    pub fn into_dlpack(self) -> Result<[DlpackManagedTensor; 9], SemanticTransitionError> {
        let retained_owner: Arc<dyn Send + Sync> = self.owner.clone();
        let values = [self.parameters, self.text_logits, self.component_baselines].map(|view| {
            // SAFETY: retained original FP32 adjoints have their exact byte span.
            unsafe { view.cast::<u8>() }.expect("FP32 policy adjoint byte view")
        });
        export_policy_gradients(
            values,
            &self.owner.numerical,
            self.support_cells,
            self.layout.parameter_cells,
            self.provider.device().ordinal() as i32,
            self.step_aliases,
            self.publication,
            self.continuation,
            retained_owner,
        )
    }
}

#[cfg(feature = "semantic-policy")]
#[expect(
    clippy::too_many_arguments,
    reason = "all exports retain one original native tape and its final-use owners"
)]
fn export_policy_gradients(
    values: [DeviceMemoryView<u8>; 3],
    numerical: &PolicyAdjointNumerical,
    support_cells: usize,
    parameter_cells: usize,
    device: i32,
    step_aliases: Arc<()>,
    publication: Arc<PublicationStorage>,
    continuation: Arc<TextBindingStorage>,
    owner: Arc<dyn Send + Sync>,
) -> Result<[DlpackManagedTensor; 9], SemanticTransitionError> {
    let layouts = policy_gradient_output_layouts(support_cells, parameter_cells)?;
    let numerical_views = numerical.roots.iter().map(|buffer| {
        // SAFETY: numerical roots are retained aligned FP64 storage.
        unsafe { buffer.view().cast::<u8>() }.expect("FP64 policy numerical byte view")
    });
    let tensors = values
        .into_iter()
        .chain(numerical_views)
        .zip(layouts)
        .map(|(view, layout)| {
            let rank = layout.rank as usize;
            export_owned_allocation(
                view,
                layout.dimensions[..rank]
                    .iter()
                    .map(|&n| n as i64)
                    .collect(),
                layout.strides_bytes[..rank]
                    .iter()
                    .map(|&n| (n / layout.element_bytes) as i64)
                    .collect(),
                (2, (layout.element_bytes * 8) as u8),
                device,
                Arc::clone(&step_aliases),
                Some(Arc::clone(&publication)),
                Some(Arc::clone(&continuation)),
                Some(Arc::clone(&owner)),
            )
        })
        .collect::<Vec<_>>();
    Ok(tensors
        .try_into()
        .unwrap_or_else(|_| unreachable!("nine original policy gradient exports")))
}

#[cfg(feature = "semantic-policy")]
fn policy_gradient_output_layouts(
    support_cells: usize,
    parameter_cells: usize,
) -> Result<[SemanticTensorLayout; 9], SemanticTransitionError> {
    let original = policy_numerical_producer_layouts(support_cells, parameter_cells)?;
    let mut text_error = original[7];
    text_error.dimensions[2] = 2;
    text_error.strides_bytes = [0; 4];
    let text_error = canonical_tensor_layout(text_error)?;
    // Native labels are interleaved per coordinate. The kernel explicitly
    // packs actor then full into these contiguous region-major exports.
    Ok([
        original[2],
        original[0],
        original[3],
        original[4],
        text_error,
        original[5],
        paired_cotangent_domain(original[6])?,
        paired_cotangent_domain(original[7])?,
        paired_cotangent_domain(original[8])?,
    ])
}

#[cfg(feature = "semantic-policy")]
fn policy_gradient_output_geometry(
    buffers: &PolicyBuffers,
    support_cells: usize,
) -> Result<[SemanticPolicyNumericalDomainLayout; 9], SemanticTransitionError> {
    let owner = &buffers.temporal_adjoints;
    let values = [
        owner.parameters.view().allocation_provenance(),
        owner.text_logits.view().allocation_provenance(),
        owner.component_baselines.view().allocation_provenance(),
    ];
    values
        .into_iter()
        .chain(
            owner
                .numerical
                .roots
                .iter()
                .map(|buffer| buffer.view().allocation_provenance()),
        )
        .zip(policy_gradient_output_layouts(
            support_cells,
            buffers.layout.parameter_cells,
        )?)
        .map(|(allocation, layout)| {
            Ok(SemanticPolicyNumericalDomainLayout {
                allocation: allocation.ok_or_else(|| {
                    publication_input_error(
                        "original policy adjoint has no native allocation origin",
                    )
                })?,
                layout,
            })
        })
        .collect::<Result<Vec<_>, SemanticTransitionError>>()?
        .try_into()
        .map_err(|_| publication_input_error("original policy adjoint geometry lost an output"))
}

#[cfg(feature = "semantic-policy")]
fn group_critic_output_layout() -> Result<SemanticTensorLayout, SemanticTransitionError> {
    canonical_tensor_layout(SemanticTensorLayout {
        role: 0,
        index: 0,
        scalar_type: 6,
        element_bytes: 4,
        rank: 1,
        dimensions: [1, 0, 0, 0],
        logical_axis: u64::MAX,
        strides_bytes: [0; 4],
    })
}

#[cfg(feature = "semantic-policy")]
fn policy_producer_layouts(
    support_cells: usize,
    parameter_cells: usize,
) -> Result<[SemanticTensorLayout; 4], SemanticTransitionError> {
    let layout = |index, scalar_type, element_bytes, rank, dimensions| {
        canonical_tensor_layout(SemanticTensorLayout {
            role: 0,
            index,
            scalar_type,
            element_bytes,
            rank,
            dimensions,
            logical_axis: u64::MAX,
            strides_bytes: [0; 4],
        })
    };
    Ok([
        layout(0, 6, 4, 2, [32, TEXT_CARDINALITY as u64, 0, 0])?,
        layout(1, 8, 1, 1, [support_cells as u64, 0, 0, 0])?,
        layout(2, 6, 4, 1, [parameter_cells as u64, 0, 0, 0])?,
        layout(3, 6, 4, 2, [1, COMPONENT_COUNT as u64, 0, 0])?,
    ])
}

#[cfg(feature = "semantic-policy")]
fn policy_numerical_producer_layouts(
    support_cells: usize,
    parameter_cells: usize,
) -> Result<[SemanticTensorLayout; 9], SemanticTransitionError> {
    let values = policy_producer_layouts(support_cells, parameter_cells)?;
    let layout = |index, rank, dimensions| {
        canonical_tensor_layout(SemanticTensorLayout {
            role: 0,
            index,
            scalar_type: 9,
            element_bytes: 8,
            rank,
            dimensions,
            logical_axis: u64::MAX,
            strides_bytes: [0; 4],
        })
    };
    Ok([
        values[0],
        values[1],
        values[2],
        values[3],
        layout(4, 2, [parameter_cells as u64, 2, 0, 0])?,
        layout(5, 3, [1, COMPONENT_COUNT as u64, 2, 0])?,
        layout(6, 2, [parameter_cells as u64, 4, 0, 0])?,
        layout(7, 3, [32, TEXT_CARDINALITY as u64, 4, 0])?,
        layout(8, 3, [1, COMPONENT_COUNT as u64, 4, 0])?,
    ])
}

#[cfg(feature = "semantic-policy")]
struct PolicyNumericalBuffers {
    parameter_errors: TrackedCudaSlice<f64>,
    baseline_errors: TrackedCudaSlice<f64>,
    parameter_domains: TrackedCudaSlice<f64>,
    text_domains: TrackedCudaSlice<f64>,
    baseline_domains: TrackedCudaSlice<f64>,
    hidden_errors: TrackedCudaSlice<f64>,
    score_errors: TrackedCudaSlice<f64>,
    recurrent_errors: TrackedCudaSlice<f64>,
    parameter_envelopes: TrackedCudaSlice<f64>,
    baseline_envelopes: TrackedCudaSlice<f64>,
    uniform: Arc<PolicyUniformBuffers>,
}

#[cfg(feature = "semantic-policy")]
fn paired_cotangent_domain(
    mut layout: SemanticTensorLayout,
) -> Result<SemanticTensorLayout, SemanticTransitionError> {
    let rank = layout.rank as usize;
    layout.dimensions.copy_within(0..rank, 1);
    layout.dimensions[0] = 2;
    layout.rank += 1;
    layout.strides_bytes = [0; 4];
    canonical_tensor_layout(layout)
}

/// Structural geometry of one original uniform-domain allocation. This
/// retains its physical lifetime, not tensor access or valid numerical content.
#[cfg(feature = "semantic-policy")]
#[derive(Clone)]
pub struct SemanticPolicyNumericalDomainLayout {
    pub allocation: DeviceAllocationProvenance,
    pub layout: SemanticTensorLayout,
}

#[cfg(feature = "semantic-policy")]
fn policy_uniform_domain_tensor_layouts(
    support_cells: usize,
    parameter_cells: usize,
) -> Result<[SemanticTensorLayout; 3], SemanticTransitionError> {
    let original = policy_numerical_producer_layouts(support_cells, parameter_cells)?;
    Ok([
        paired_cotangent_domain(original[6])?,
        paired_cotangent_domain(original[7])?,
        paired_cotangent_domain(original[8])?,
    ])
}

#[cfg(feature = "semantic-policy")]
fn policy_uniform_domain_layouts(
    buffers: &PolicyBuffers,
    support_cells: usize,
) -> Result<[SemanticPolicyNumericalDomainLayout; 3], SemanticTransitionError> {
    let original =
        policy_uniform_domain_tensor_layouts(support_cells, buffers.layout.parameter_cells)?;
    let project =
        |index: usize, layout: SemanticTensorLayout| -> Result<_, SemanticTransitionError> {
            Ok(SemanticPolicyNumericalDomainLayout {
                allocation: buffers.numerical.uniform.outputs[index]
                    .view()
                    .allocation_provenance()
                    .ok_or_else(|| {
                        publication_input_error(
                            "original uniform domain has no native allocation origin",
                        )
                    })?,
                layout,
            })
        };
    Ok([
        project(0, original[0])?,
        project(1, original[1])?,
        project(2, original[2])?,
    ])
}

#[cfg(feature = "semantic-policy")]
fn require_policy_uniform_domain_layouts(
    buffers: &PolicyBuffers,
    support_cells: usize,
    expected: &[SemanticPolicyNumericalDomainLayout; 3],
) -> Result<(), SemanticTransitionError> {
    let original = policy_uniform_domain_layouts(buffers, support_cells)?;
    if original.iter().zip(expected).any(|(original, expected)| {
        original.layout != expected.layout
            || !original.allocation.same_allocation(&expected.allocation)
            || original.allocation.byte_offset() != expected.allocation.byte_offset()
            || original.allocation.view_bytes() != expected.allocation.view_bytes()
            || original.allocation.allocation_bytes() != expected.allocation.allocation_bytes()
    }) {
        return Err(publication_input_error(
            "uniform domain export changed its original ordered allocation geometry",
        ));
    }
    Ok(())
}

#[cfg(feature = "semantic-policy")]
fn enqueue_policy_uniform_domains(
    domain: &ResidentExecutionDomain,
    poisoned: &mut bool,
    buffers: &PolicyBuffers,
    components: &TrackedCudaSlice<SemanticComponent>,
    support: &TrackedCudaSlice<u8>,
) -> Result<(), SemanticTransitionError> {
    let mut recorder = domain.new_strict_recorder();
    recorder.read(&buffers.parameters);
    recorder.read(&buffers.component_baselines);
    recorder.read(components);
    recorder.read(support);
    buffers.numerical.record(&mut recorder);
    recorder.write(&buffers.numerical.uniform.descriptor);
    let descriptor = SemanticTransitionSession::retained_policy_descriptor(buffers);
    let mut retained = buffers
        .binding_work
        .lock()
        .map_err(|_| SemanticTransitionError::Poisoned)?;
    let retained = retained.as_mut().ok_or(SemanticTransitionError::NotBound)?;
    if retained.cursor < 9 {
        return Err(SemanticTransitionError::ObservationMismatch);
    }
    let mut uniform = buffers.numerical.uniform.initial_descriptor;
    uniform.transfer_target = retained.work.as_ref().map_or(0, |work| *work.device_ptr());
    uniform.transferred = 0;
    if let Some(work) = &retained.work {
        recorder.read_write(work);
    }
    let snapshot_bytes = if retained.allowance.is_some() {
        0
    } else {
        retained.snapshot_bytes
    };
    if let Some(command) = retained.commands.get_mut(9) {
        let execute = buffers.numerical.uniform.execute.clone();
        command.run(domain, poisoned, recorder, |enqueue, entered, submitted| {
            let descriptor = descriptor.into_kernel_param_storage();
            let uniform = uniform.into_kernel_param_storage();
            let components = components.device_ptr_value().into_kernel_param_storage();
            let support = support.device_ptr_value().into_kernel_param_storage();
            let bytes = snapshot_bytes.into_kernel_param_storage();
            let mut parameters = [
                descriptor.as_kernel_param(),
                uniform.as_kernel_param(),
                components.as_kernel_param(),
                support.as_kernel_param(),
                bytes.as_kernel_param(),
            ];
            // SAFETY: original snapshots, scratch and work owners are retained
            // by this binding and registered on the exact original stream.
            unsafe {
                execute.launch_raw_in_original(
                    enqueue,
                    LaunchConfig {
                        grid_dim: (1, 1, 1),
                        block_dim: (256, 1, 1),
                        shared_mem_bytes: 0,
                    },
                    &mut parameters,
                    false,
                    entered,
                    submitted,
                )
            }
            .map_err(|error| XlogError::Kernel(error.to_string()))
        })?;
        retained.cursor = 10;
        return Ok(());
    }
    enqueue_recorded(domain, poisoned, recorder, |enqueue| {
        // SAFETY: cold reservation and the immutable descriptor bind disjoint
        // scratch, original snapshots and complete output capacities. The
        // recorder orders all nine producers and the private descriptor's
        // device initialization before this one native transfer.
        unsafe {
            buffers.numerical.uniform.execute.clone().launch_in(
                enqueue,
                LaunchConfig {
                    grid_dim: (1, 1, 1),
                    block_dim: (256, 1, 1),
                    shared_mem_bytes: 0,
                },
                (
                    descriptor,
                    uniform,
                    components.device_ptr_value(),
                    support.device_ptr_value(),
                    snapshot_bytes,
                ),
            )
        }
        .map_err(|error| XlogError::Kernel(error.to_string()))
    })
}

#[cfg(feature = "semantic-policy")]
fn export_policy_uniform_domains(
    buffers: &PolicyBuffers,
    support_cells: usize,
    device: i32,
    aliases: Arc<()>,
    publication: Arc<PublicationStorage>,
) -> Result<[DlpackManagedTensor; 3], SemanticTransitionError> {
    let layouts = policy_uniform_domain_layouts(buffers, support_cells)?;
    let owner: Arc<dyn Send + Sync> = buffers.numerical.uniform.clone();
    let tensors = buffers
        .numerical
        .uniform
        .outputs
        .iter()
        .zip(layouts)
        .map(|(buffer, projection)| {
            let layout = projection.layout;
            let rank = layout.rank as usize;
            // SAFETY: the typed retained FP64 output allocation has the exact
            // native layout; no managed tensor or producer is fabricated.
            let view = unsafe { buffer.view().cast::<u8>() }.expect("FP64 domain byte view");
            Ok(export_owned_allocation(
                view,
                layout.dimensions[..rank]
                    .iter()
                    .map(|&n| n as i64)
                    .collect(),
                layout.strides_bytes[..rank]
                    .iter()
                    .map(|&n| (n / 8) as i64)
                    .collect(),
                (2, 64),
                device,
                Arc::clone(&aliases),
                Some(Arc::clone(&publication)),
                None,
                Some(Arc::clone(&owner)),
            ))
        })
        .collect::<Result<Vec<_>, SemanticTransitionError>>()?;
    Ok(tensors
        .try_into()
        .unwrap_or_else(|_| unreachable!("three uniform domain roots")))
}

#[cfg(feature = "semantic-policy")]
impl PolicyNumericalBuffers {
    fn buffers(&self) -> [&TrackedCudaSlice<f64>; 10] {
        [
            &self.parameter_errors,
            &self.baseline_errors,
            &self.parameter_domains,
            &self.text_domains,
            &self.baseline_domains,
            &self.hidden_errors,
            &self.score_errors,
            &self.recurrent_errors,
            &self.parameter_envelopes,
            &self.baseline_envelopes,
        ]
    }

    fn record(&self, recorder: &mut LaunchRecorder) {
        for buffer in self.buffers() {
            recorder.read_write(buffer);
        }
        self.uniform.record(recorder);
    }

    fn descriptor(&self, parameter_cells: usize) -> PolicyNumericalDescriptor {
        PolicyNumericalDescriptor {
            parameter_errors: self.parameter_errors.device_ptr_value(),
            baseline_errors: self.baseline_errors.device_ptr_value(),
            parameter_domains: self.parameter_domains.device_ptr_value(),
            text_domains: self.text_domains.device_ptr_value(),
            baseline_domains: self.baseline_domains.device_ptr_value(),
            hidden_errors: self.hidden_errors.device_ptr_value(),
            score_errors: self.score_errors.device_ptr_value(),
            recurrent_errors: self.recurrent_errors.device_ptr_value(),
            parameter_cells: parameter_cells as u64,
            parameter_envelopes: self.parameter_envelopes.device_ptr_value(),
            baseline_envelopes: self.baseline_envelopes.device_ptr_value(),
            uniform: self.uniform.descriptor.device_ptr_value(),
        }
    }
}

