#[cfg(feature = "semantic-policy")]
struct PolicyProducerViews {
    text_logits: DeviceMemoryView<f32>,
    product_support: DeviceMemoryView<u8>,
    parameters: DeviceMemoryView<f32>,
    component_baselines: DeviceMemoryView<f32>,
    numerical: [DeviceMemoryView<f64>; 5],
}

#[cfg(feature = "semantic-policy")]
fn policy_source_views(
    originals: &[PreparedSemanticTensor],
) -> Result<PolicyProducerViews, SemanticTransitionError> {
    if originals.len() != 9 {
        return Err(publication_input_error(
            "policy requires its complete original producer roster",
        ));
    }
    let source = |index: usize| {
        originals[index]
            .source
            .clone()
            .ok_or_else(|| publication_input_error("policy producer storage is empty"))
    };
    // SAFETY: policy_producer_layouts and the original witness established
    // contiguous F32 shape, byte extents and alignment before this conversion.
    let text_logits = unsafe { source(0)?.cast::<f32>() }.ok_or_else(|| {
        publication_input_error("original text logits are not aligned F32 storage")
    })?;
    // SAFETY: the same typed original admission holds for model parameters.
    let parameters = unsafe { source(2)?.cast::<f32>() }.ok_or_else(|| {
        publication_input_error("original policy parameters are not aligned F32 storage")
    })?;
    // SAFETY: the fourth admitted producer is the exact rank-two FP32
    // component-baseline row issued by the original model invocation.
    let component_baselines = unsafe { source(3)?.cast::<f32>() }.ok_or_else(|| {
        publication_input_error("original component baselines are not aligned F32 storage")
    })?;
    let mut numerical = Vec::with_capacity(5);
    for index in 4..9 {
        // SAFETY: the original F64 layout/witness proves alignment and extent.
        numerical.push(unsafe { source(index)?.cast::<f64>() }.ok_or_else(|| {
            publication_input_error("original policy numerical view is not aligned F64 storage")
        })?);
    }
    Ok(PolicyProducerViews {
        text_logits,
        product_support: source(1)?,
        parameters,
        component_baselines,
        numerical: numerical
            .try_into()
            .unwrap_or_else(|_| unreachable!("five numerical producers")),
    })
}

#[cfg(feature = "semantic-policy")]
#[expect(
    clippy::too_many_arguments,
    reason = "original snapshots retain their selected counter, DMA allowance and metadata pool explicitly"
)]
fn enqueue_policy_snapshots(
    domain: &ResidentExecutionDomain,
    poisoned: &mut bool,
    buffers: &PolicyBuffers,
    support: &TrackedCudaSlice<u8>,
    original: &PolicyProducerViews,
    work: Option<DeviceMemoryView<u64>>,
    allowance: Option<&Arc<Mutex<ColdNativeAllowance>>>,
    capture: bool,
    budget: Option<&SemanticReplayMaterialBudget>,
) -> Result<(), SemanticTransitionError> {
    if work
        .as_ref()
        .is_some_and(|work| work.len() != 11 || !work.device_ptr().is_multiple_of(8))
        || (allowance.is_some() && (work.is_none() || capture))
        || (capture && work.is_none())
    {
        return Err(publication_input_error(
            "policy binding lost its original complete work owner",
        ));
    }
    if work.is_some() && budget.is_none() {
        return Err(publication_input_error(
            "policy binding requires its original metadata byte pool",
        ));
    }
    if original.text_logits.len() != buffers.text_logits.len()
        || original.product_support.len() != support.len()
        || original.parameters.len() != buffers.parameters.len()
        || original.component_baselines.len() != buffers.component_baselines.len()
    {
        return Err(publication_input_error(
            "original policy producers differ from their fixed native capacities",
        ));
    }
    let numerical_destinations = &buffers.numerical.buffers()[..5];
    if numerical_destinations
        .iter()
        .zip(&original.numerical)
        .any(|(destination, source)| destination.len() != source.len())
    {
        return Err(publication_input_error(
            "original numerical policy capacities differ",
        ));
    }
    let primary = [
        (
            buffers.text_logits.device_ptr_value(),
            *original.text_logits.device_ptr(),
            original.text_logits.len() * 4,
        ),
        (
            support.device_ptr_value(),
            *original.product_support.device_ptr(),
            original.product_support.len(),
        ),
        (
            buffers.parameters.device_ptr_value(),
            *original.parameters.device_ptr(),
            original.parameters.len() * 4,
        ),
        (
            buffers.component_baselines.device_ptr_value(),
            *original.component_baselines.device_ptr(),
            original.component_baselines.len() * 4,
        ),
    ];
    let copies: [_; 9] = std::array::from_fn(|index| {
        if let Some(copy) = primary.get(index) {
            *copy
        } else {
            let index = index - primary.len();
            let source = &original.numerical[index];
            (
                numerical_destinations[index].device_ptr_value(),
                *source.device_ptr(),
                source.len() * 8,
            )
        }
    });
    let snapshot_bytes = copies.iter().try_fold(0u64, |total, (_, _, bytes)| {
        total
            .checked_add(*bytes as u64)
            .ok_or(SemanticTransitionError::GenerationExhausted)
    })?;
    let mut retained = buffers
        .binding_work
        .lock()
        .map_err(|_| SemanticTransitionError::Poisoned)?;
    if retained.is_none() {
        let command_count = if capture || allowance.is_none() {
            0
        } else {
            copies.len() + 1
        };
        let allocation_reservation = budget
            .map(|budget| {
                let completion_bytes =
                    crate::device::ExecutionCompletion::single_stream_allocation_bytes()
                        .map_err(|_| SemanticTransitionError::GenerationExhausted)?;
                let command_bytes = (size_of::<OriginalNativeCommand>() as u64)
                    .checked_add(completion_bytes)
                    .and_then(|bytes| bytes.checked_mul(command_count as u64))
                    .ok_or(SemanticTransitionError::GenerationExhausted)?;
                let bytes = (size_of::<OriginalPolicyBindingWork>() as u64)
                    .checked_add(command_bytes)
                    .ok_or(SemanticTransitionError::GenerationExhausted)?;
                budget.reserve_auxiliary(bytes)
            })
            .transpose()?;
        let mut commands = Vec::with_capacity(command_count);
        for _ in 0..command_count {
            commands.push(OriginalNativeCommand::new(domain)?);
        }
        *retained = Some(OriginalPolicyBindingWork {
            work: work.clone(),
            allowance: allowance.map(Arc::downgrade),
            commands,
            cursor: 0,
            snapshot_bytes,
            copies,
            _allocation_reservation: allocation_reservation,
        });
    }
    let retained = retained
        .as_mut()
        .expect("installed original policy binding");
    let same_work = match (&retained.work, &work) {
        (Some(original), Some(actual)) => {
            original.device_ptr() == actual.device_ptr() && original.len() == actual.len()
        }
        (None, None) => true,
        _ => false,
    };
    let same_allowance = match (&retained.allowance, allowance) {
        (Some(original), Some(actual)) => original
            .upgrade()
            .is_some_and(|original| Arc::ptr_eq(&original, actual)),
        (None, None) => true,
        _ => false,
    };
    if retained.snapshot_bytes != snapshot_bytes
        || retained.copies != copies
        || !same_work
        || !same_allowance
    {
        return Err(SemanticTransitionError::ObservationMismatch);
    }
    for (index, (destination, source, bytes)) in copies.into_iter().enumerate() {
        if retained.cursor > index {
            continue;
        }
        let mut recorder = domain.new_strict_recorder();
        recorder.read(&original.text_logits);
        recorder.read(&original.product_support);
        recorder.read(&original.parameters);
        recorder.read(&original.component_baselines);
        recorder.write(&buffers.text_logits);
        recorder.write(support);
        recorder.write(&buffers.parameters);
        recorder.write(&buffers.component_baselines);
        for (destination, source) in numerical_destinations.iter().zip(&original.numerical) {
            recorder.read(source);
            recorder.write(*destination);
        }
        if let Some(command) = retained.commands.get_mut(index) {
            command.run_dma(
                domain,
                poisoned,
                recorder,
                allowance,
                bytes,
                |enqueue, entered, submitted| {
                    *entered = true;
                    // SAFETY: matched typed extents retain this exact original pair.
                    unsafe {
                        sys::cuMemcpyDtoDAsync_v2(
                            destination,
                            source,
                            bytes,
                            enqueue.stream().cu_stream(),
                        )
                    }
                    .result()
                    .map_err(|error| XlogError::Kernel(error.to_string()))?;
                    *submitted = true;
                    Ok(())
                },
            )?;
        } else {
            enqueue_recorded(domain, poisoned, recorder, |enqueue| {
                // SAFETY: matched typed extents retain this exact original pair.
                unsafe {
                    sys::cuMemcpyDtoDAsync_v2(
                        destination,
                        source,
                        bytes,
                        enqueue.stream().cu_stream(),
                    )
                }
                .result()
                .map_err(|error| XlogError::Kernel(error.to_string()))
            })?;
        }
        retained.cursor = index + 1;
    }
    Ok(())
}

#[cfg(feature = "semantic-policy")]
struct PolicyReplacement {
    support: TrackedCudaSlice<u8>,
    receipts: TrackedCudaSlice<SemanticTransitionReceipt>,
    state: TrackedCudaSlice<DeviceState>,
    task_ground: Option<task_ground::TaskGroundStorage>,
}

/// Original numerical inputs and receipts survive later publication and rebinding.
/// Backward consumes this exact invocation once, independently of the current bank.
#[cfg(feature = "semantic-policy")]
struct PolicyTape {
    invocation: SemanticRngBinding,
    refusal: Option<SemanticTransitionRefusal>,
    binding: SemanticCatalogueBinding,
    policy: PolicyStorage,
    support: TrackedCudaSlice<u8>,
    receipts: TrackedCudaSlice<SemanticTransitionReceipt>,
    prepared_bank: Option<usize>,
    // Ordinary proposals keep the exact device state observed with this tape;
    // later restored invocations may rebind the Session's working state.
    origin_state: Option<TrackedCudaSlice<DeviceState>>,
    origin_task_ground: Option<task_ground::TaskGroundStorage>,
    // Immutable cold catalogue allocations remain shared by their original
    // invocation tapes; no later binding overwrites their bytes.
    components: DeviceMemoryView<SemanticComponent>,
    codebooks: DeviceMemoryView<u64>,
    retirement: Option<PolicyTapeRetirement>,
    retirement_parent: Option<PolicyRetirementParent>,
}

#[cfg(feature = "semantic-policy")]
struct PolicyRetirementParent {
    issuer: Arc<()>,
    token: u64,
    identity: SemanticPublishedIdentity,
    header: PublicationHeader,
    directory: Vec<PublicationRange>,
    active: bool,
}

#[cfg(feature = "semantic-policy")]
impl PolicyRetirementParent {
    fn matches(&self, lease: &SemanticPublishedLease) -> bool {
        Arc::ptr_eq(&self.issuer, &lease.issuer)
            && self.token == lease.token
            && self.identity == lease.identity
            && self.header == lease.header
            && self.active == lease.active
            && self.directory.len() == lease.directory.len()
            && self
                .directory
                .iter()
                .zip(&lease.directory)
                .all(|(original, current)| {
                    original.role == current.role
                        && original.index == current.index
                        && original.storage_slot == current.storage_slot
                        && original.generation == current.generation
                        && original.offset_bytes == current.offset_bytes
                        && original.length_bytes == current.length_bytes
                        && original.logical_begin == current.logical_begin
                        && original.logical_end == current.logical_end
                })
    }
}

struct OriginalConsumerEdge {
    event: cudarc::driver::CudaEvent,
    context: Arc<cudarc::driver::CudaContext>,
    source: u64,
    destination: u64,
    record_entered: bool,
    recorded: bool,
    source_completed: bool,
    wait_entered: bool,
    waited: bool,
}

impl OriginalConsumerEdge {
    fn new(
        stream: &CudaStream,
        source: sys::CUstream,
        destination: sys::CUstream,
    ) -> Result<Self, SemanticTransitionError> {
        Ok(Self {
            event: stream
                .context()
                .new_event(None)
                .map_err(|error| native_runtime_error("original consumer event", error))?,
            context: Arc::clone(stream.context()),
            source: source as u64,
            destination: destination as u64,
            record_entered: false,
            recorded: false,
            source_completed: false,
            wait_entered: false,
            waited: false,
        })
    }

    fn join(&mut self) -> Result<(), SemanticTransitionError> {
        if self.waited {
            return Ok(());
        }
        if self.source_completed {
            self.waited = true;
            return Ok(());
        }
        self.context
            .bind_to_thread()
            .map_err(|error| native_runtime_error("original consumer context", error))?;
        if !self.recorded {
            if self.record_entered {
                self.resolve_entered()?;
                return Ok(());
            }
            self.record_entered = true;
            // SAFETY: both streams and this exact event belong to the retained
            // original retirement owner. An entered record is never replayed.
            unsafe {
                cudarc::driver::result::event::record(
                    self.event.cu_event(),
                    self.source as sys::CUstream,
                )
            }
            .map_err(|error| native_runtime_error("original consumer event record", error))?;
            self.recorded = true;
        }
        if !self.waited {
            if self.wait_entered {
                // A failed stream wait may have entered. Joining its original
                // successfully recorded event proves that same producer is
                // complete without recording an event on future writes.
                self.event.synchronize().map_err(|error| {
                    native_runtime_error("original consumer event completion", error)
                })?;
                self.source_completed = true;
            } else {
                self.wait_entered = true;
                // SAFETY: the event is the original successful producer record;
                // the destination is the original admitted same-context stream.
                unsafe {
                    sys::cuStreamWaitEvent(
                        self.destination as sys::CUstream,
                        self.event.cu_event(),
                        0,
                    )
                }
                .result()
                .map_err(|error| native_runtime_error("original consumer stream join", error))?;
            }
            self.waited = true;
        }
        Ok(())
    }

    fn resolve_entered(&mut self) -> Result<bool, SemanticTransitionError> {
        if !self.record_entered {
            return Ok(false);
        }
        if self.source_completed {
            return Ok(true);
        }
        self.context
            .bind_to_thread()
            .map_err(|error| native_runtime_error("original consumer context", error))?;
        if self.recorded {
            self.event.synchronize().map_err(|error| {
                native_runtime_error("original consumer event completion", error)
            })?;
        } else {
            // SAFETY: this is the immutable original source stream under its
            // retained owning context and original capture exclusion. Positive
            // completion proves its last use without claiming the failed event
            // record was submitted or recording a fence on future writes.
            unsafe { sys::cuStreamSynchronize(self.source as sys::CUstream) }
                .result()
                .map_err(|error| {
                    native_runtime_error("original consumer source completion", error)
                })?;
        }
        self.source_completed = true;
        self.waited = true;
        Ok(true)
    }
}

#[cfg(feature = "semantic-policy")]
