#[cfg(test)]
mod task_state_contract {
    use super::*;

    #[test]
    fn text_null_requires_the_complete_singleton_receipt() {
        let mut receipt = SemanticTransitionReceipt {
            kind: COMPONENT_KIND_TEXT as u32,
            choice: TEXT_NULL as u32,
            legal_count: 1,
            active_count: 1,
            p: [1, 0, 0],
            q: [1, 0, 0],
            factor_denominator: [1, 0, 0],
            cdf_end: 1 << 63,
            mass: 1 << 63,
            ..SemanticTransitionReceipt::default()
        };
        assert!(canonical_text_null(&receipt));
        let exact = receipt;
        receipt.choice = 0;
        assert!(!canonical_text_null(&receipt));
        receipt = exact;
        receipt.p[1] = 1;
        assert!(!canonical_text_null(&receipt));
        receipt = exact;
        receipt.cdf_start = 1;
        assert!(!canonical_text_null(&receipt));
        receipt = exact;
        receipt.active_count = 2;
        assert!(!canonical_text_null(&receipt));
        receipt = exact;
        receipt.mass -= 1;
        assert!(!canonical_text_null(&receipt));
    }

    #[test]
    fn task_state_bank_includes_actual_query_receipts() {
        assert_eq!(size_of::<DeviceState>(), 7568);
        assert_eq!(size_of::<Descriptor>(), 1472);
    }

    #[test]
    fn ordinary_refusal_requires_original_coordinates_and_completed_cleanup() {
        let rng = SemanticRngBinding {
            model_generation: 3,
            family_id: 4,
            stream_serial: 5,
            proposal: 6,
        };
        let binding = SemanticActionCatalogue::current().binding();
        let original = DeviceState {
            model_generation: rng.model_generation,
            family_id: u32::from(rng.family_id),
            stream_serial: rng.stream_serial,
            proposal: 6,
            next_proposal: 6,
            catalogue_generation: binding.generation,
            catalogue_digest: binding.digest,
            binding_digest: binding.digest,
            status: 5,
            ..DeviceState::default()
        };
        assert_eq!(
            refused_terminal(&original, rng, binding, binding.digest, None, None).unwrap(),
            SemanticTransitionRefusal::NonFinitePolicyInput { completed_draws: 0 }
        );
        for mutation in 0..8 {
            let mut state = original;
            match mutation {
                0 => state.model_generation += 1,
                1 => state.family_id += 1,
                2 => state.stream_serial += 1,
                3 => state.next_proposal += 1,
                4 => state.blocks = COMPONENT_COUNT as u64,
                5 => state.importance_weight = 1.0,
                6 => state.cleanup_receipts[0][0] = 1,
                _ => state.retired_roots_mask = 4,
            }
            assert!(refused_terminal(&state, rng, binding, binding.digest, None, None).is_err());
        }
        for status in [0, 1, 3, 4, 6, 7, 8, 9, 10] {
            let mut state = original;
            state.status = status;
            assert!(refused_terminal(&state, rng, binding, binding.digest, None, None).is_err());
        }
        let mut state = original;
        state.status = 2;
        state.blocks = 50;
        assert_eq!(
            refused_terminal(&state, rng, binding, binding.digest, None, None).unwrap(),
            SemanticTransitionRefusal::InvalidFinalSupport {
                completed_draws: 50
            }
        );
        state.status = 11;
        assert!(refused_terminal(&state, rng, binding, binding.digest, None, None).is_err());
        state.execution_work.overflow = 1;
        assert_eq!(
            refused_terminal(&state, rng, binding, binding.digest, None, None).unwrap(),
            SemanticTransitionRefusal::WorkCounterOverflow {
                completed_draws: 50
            }
        );
        state.next_proposal += 1;
        assert!(refused_terminal(&state, rng, binding, binding.digest, None, None).is_err());
    }

    #[test]
    fn refused_seal_cleanup_distinguishes_aliases_from_retired_private_roots() {
        let mut state = DeviceState::default();
        assert!(refused_root_cleanup(&state, 17, 2, 3).is_ok());
        state.semantic_receipts[3][33] = 1;
        state.semantic_receipts[3][39] = 17;
        state.semantic_receipts[3][1] = 2;
        state.semantic_receipts[3][34] = 2;
        state.semantic_receipts[3][35] = 3;
        assert!(refused_root_cleanup(&state, 17, 2, 3).is_err());
        state.retired_roots_mask = 1;
        assert!(refused_root_cleanup(&state, 17, 2, 3).is_ok());
        state.cleanup_receipts[1][39] = 17;
        assert!(
            refused_root_cleanup(&state, 17, 2, 3).is_err(),
            "base aliases are never retired"
        );
        state.semantic_receipts[3][1] = 1;
        state.semantic_receipts[3][34] = 7;
        state.cleanup_receipts[1][3] = 7;
        state.cleanup_receipts[1][4] = 4;
        assert!(refused_root_cleanup(&state, 17, 2, 3).is_ok());
        state.cleanup_receipts[1][4] = 3;
        assert!(refused_root_cleanup(&state, 17, 2, 3).is_err());
        state.cleanup_receipts[1][4] = 4;
        state.retired_roots_mask = 3;
        assert!(
            refused_root_cleanup(&state, 17, 2, 3).is_err(),
            "no seal exists in the other lane"
        );
    }
}

/// Completed device outcome. A refusal carries no successor, selected-score
/// receipts, or derivative authority; it is not a successful observation.
#[derive(Clone, Debug, PartialEq)]
#[expect(
    clippy::large_enum_variant,
    reason = "published outcomes retain the original invocation owner without another allocation"
)]
pub enum SemanticTransitionOutcome {
    Published(SemanticTransitionObservation),
    Refused(SemanticTransitionRefusal),
}

impl SemanticTransitionOutcome {
    /// Inspect the original result without relinquishing its invocation owner.
    /// A refusal preserves the same typed error as consuming the outcome.
    pub fn as_published(&self) -> Result<&SemanticTransitionObservation, SemanticTransitionError> {
        match self {
            Self::Published(observation) => Ok(observation),
            Self::Refused(refusal) => Err(refusal.into_error()),
        }
    }

    pub fn into_published(self) -> Result<SemanticTransitionObservation, SemanticTransitionError> {
        match self {
            Self::Published(observation) => Ok(observation),
            Self::Refused(refusal) => Err(refusal.into_error()),
        }
    }
}

/// Ordinary device refusal after authentic parent and cleanup reconciliation.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum SemanticTransitionRefusal {
    InvalidFinalSupport {
        completed_draws: u64,
    },
    NonFinitePolicyInput {
        completed_draws: u64,
    },
    WorkCounterOverflow {
        completed_draws: u64,
    },
    InvalidTrainingView {
        status: u64,
    },
    RejectedModelUpdate {
        evidence: SemanticTrainingCanaryRefusalRecord,
    },
    CapacityExceeded {
        evidence: SemanticCapacityRefusalRecord,
    },
}

impl SemanticTransitionRefusal {
    fn into_error(self) -> SemanticTransitionError {
        match self {
            Self::InvalidFinalSupport { completed_draws } => {
                SemanticTransitionError::InvalidFinalSupport { completed_draws }
            }
            Self::NonFinitePolicyInput { completed_draws } => {
                SemanticTransitionError::NonFinitePolicyInput { completed_draws }
            }
            Self::WorkCounterOverflow { completed_draws } => {
                SemanticTransitionError::WorkCounterOverflow { completed_draws }
            }
            Self::InvalidTrainingView { status } => {
                SemanticTransitionError::InvalidTrainingView { status }
            }
            Self::RejectedModelUpdate { evidence } => {
                SemanticTransitionError::RejectedModelUpdate {
                    evidence: Box::new(evidence),
                }
            }
            Self::CapacityExceeded { evidence } => {
                SemanticTransitionError::CapacityExceeded { evidence }
            }
        }
    }
}

#[cfg(feature = "semantic-policy")]
fn decode_canary_refusal(
    record: SemanticTrainingCanaryRefusalRecord,
    results: &[SemanticTrainingCanaryResultRecord],
) -> Result<Option<SemanticTrainingCanaryRefusalRecord>, SemanticTransitionError> {
    if record.abi != 1 {
        return Err(SemanticTransitionError::ObservationMismatch);
    }
    if record.reason == 0 {
        let success = SemanticTrainingCanaryRefusalRecord {
            abi: 1,
            ..SemanticTrainingCanaryRefusalRecord::default()
        };
        return (record == success)
            .then_some(None)
            .ok_or(SemanticTransitionError::ObservationMismatch);
    }
    let reason = record
        .reason()
        .ok_or(SemanticTransitionError::ObservationMismatch)?;
    let original = results
        .iter()
        .find(|result| result.kind == record.kind)
        .ok_or(SemanticTransitionError::ObservationMismatch)?;
    if original.abi != 1
        || original.availability > 2
        || original.reason != record.reason
        || original.row_ordinal != record.row_ordinal
        || original.identity != record.identity
        || original.measurement_bits != record.measurement_bits
        || original.memory_used != record.memory_used
        || original.work_used != record.work_used
    {
        return Err(SemanticTransitionError::ObservationMismatch);
    }
    let lower = f64::from_bits(record.lower_bound_bits);
    let upper = f64::from_bits(record.upper_bound_bits);
    let measurement = f64::from_bits(record.measurement_bits);
    if !(1..=5).contains(&record.kind)
        || !lower.is_finite()
        || !upper.is_finite()
        || lower > upper
        || record.memory_limit == 0
        || record.work_limit == 0
        || (original.availability == 2
            && match reason {
                SemanticTrainingCanaryRefusalReason::NonFiniteMeasurement => {
                    measurement.is_finite()
                }
                SemanticTrainingCanaryRefusalReason::OutsideBounds => {
                    !measurement.is_finite() || (measurement >= lower && measurement <= upper)
                }
                SemanticTrainingCanaryRefusalReason::MemoryLimitExceeded => {
                    !measurement.is_finite()
                        || measurement < lower
                        || measurement > upper
                        || record.memory_used <= record.memory_limit
                }
                SemanticTrainingCanaryRefusalReason::WorkLimitExceeded => {
                    // The final work-limit pass can outrank an earlier retention
                    // or goal refusal, which skipped bounds and memory checks.
                    // Its original result therefore proves only this limit.
                    record.work_used <= record.work_limit
                }
                SemanticTrainingCanaryRefusalReason::IncompleteOperands
                | SemanticTrainingCanaryRefusalReason::ProtectedRetentionLost
                | SemanticTrainingCanaryRefusalReason::GoalWitnessInvalid
                | SemanticTrainingCanaryRefusalReason::WorkOverflow
                | SemanticTrainingCanaryRefusalReason::GenerationMismatch => false,
            })
    {
        return Err(SemanticTransitionError::ObservationMismatch);
    }
    Ok(Some(record))
}

fn refused_terminal(
    state: &DeviceState,
    rng: SemanticRngBinding,
    catalogue: SemanticCatalogueBinding,
    binding_digest: Identity256,
    canary_refusal: Option<SemanticTrainingCanaryRefusalRecord>,
    capacity_refusal: Option<SemanticCapacityRefusalRecord>,
) -> Result<SemanticTransitionRefusal, SemanticTransitionError> {
    if state.model_generation != rng.model_generation
        || state.family_id != u32::from(rng.family_id)
        || state.stream_serial != rng.stream_serial
        || state.proposal != u64::from(rng.proposal)
        || state.next_proposal != state.proposal
        || state.blocks >= COMPONENT_COUNT as u64
        || state.catalogue_generation != catalogue.generation
        || state.catalogue_digest != catalogue.digest
        || state.binding_digest != binding_digest
        || state.importance_weight != 0.0
        || state.retired_roots_mask & !3 != 0
        || state.cleanup_receipts.iter().any(|receipt| receipt[0] != 0)
    {
        return Err(SemanticTransitionError::ObservationMismatch);
    }
    match state.status {
        2 => Ok(SemanticTransitionRefusal::InvalidFinalSupport {
            completed_draws: state.blocks,
        }),
        5 => Ok(SemanticTransitionRefusal::NonFinitePolicyInput {
            completed_draws: state.blocks,
        }),
        11 if state.execution_work.overflow == 1 => {
            Ok(SemanticTransitionRefusal::WorkCounterOverflow {
                completed_draws: state.blocks,
            })
        }
        12..=14 if state.execution_work.overflow == 0 && state.blocks == 0 => {
            Ok(SemanticTransitionRefusal::InvalidTrainingView {
                status: state.status - 11,
            })
        }
        15 if state.execution_work.overflow == 0 && state.blocks == 0 => {
            Ok(SemanticTransitionRefusal::RejectedModelUpdate {
                evidence: canary_refusal.ok_or(SemanticTransitionError::ObservationMismatch)?,
            })
        }
        16 if state.execution_work.overflow == 0 && state.blocks == 0 => {
            Ok(SemanticTransitionRefusal::CapacityExceeded {
                evidence: capacity_refusal.ok_or(SemanticTransitionError::ObservationMismatch)?,
            })
        }
        _ => Err(SemanticTransitionError::ObservationMismatch),
    }
}

fn refused_root_cleanup(
    state: &DeviceState,
    owner: u64,
    base_slot: u64,
    base_generation: u64,
) -> Result<(), SemanticTransitionError> {
    let mismatch = || SemanticTransitionError::ObservationMismatch;
    // This slot may describe either the inactive root retired by publication
    // admission or a later candidate discard. The completed kernel checks the
    // corresponding owner operation and changes status to failure on error.
    let cleanup = &state.cleanup_receipts[0];
    if cleanup.iter().any(|&word| word != 0) && (cleanup[0] != 0 || cleanup[39] != owner) {
        return Err(mismatch());
    }
    for lane in 0..2 {
        let sealed = &state.semantic_receipts[3 + lane * 3];
        let cleanup = &state.cleanup_receipts[1 + lane];
        let consumed = state.retired_roots_mask & (1 << lane) != 0;
        // Resident root-kind is 1; a cleared or failed seal owns no sealed root.
        if sealed[0] != 0 || sealed[33] != 1 {
            if consumed || cleanup.iter().any(|&word| word != 0) {
                return Err(mismatch());
            }
            continue;
        }
        if !consumed || sealed[39] != owner {
            return Err(mismatch());
        }
        match sealed[1] {
            // An unchanged seal only aliases the protected base, so there is
            // deliberately no retirement receipt for it.
            2 if sealed[34] == base_slot
                && sealed[35] == base_generation
                && cleanup.iter().all(|&word| word == 0) => {}
            1 if cleanup[0] == 0
                && cleanup[1] == 0
                && cleanup[39] == owner
                && cleanup[3] == sealed[34]
                && sealed[35].checked_add(1) == Some(cleanup[4]) => {}
            _ => return Err(mismatch()),
        }
    }
    Ok(())
}

#[derive(Clone, Debug, PartialEq)]
pub struct SemanticTransitionObservation {
    pub components: Vec<SemanticTransitionReceipt>,
    pub root_handle: SemanticRootHandle,
    pub root: SemanticRootSnapshot,
    pub next_proposal: u64,
    pub lanes: [SemanticTransitionLane; 2],
    /// Full device-computed FP64 importance weight in original component order.
    /// The receipts retain the exact rational factors; this rounded reduction
    /// neither replaces them nor certifies the downstream parameter gradient.
    pub importance_weight: f64,
    /// Present only for the separately cold-bound finite evaluator.
    pub task_evaluation: Option<SemanticTaskEvaluation>,
}

/// A task-local refusal is not a semantic infrastructure failure.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum SemanticTaskRefusal {
    Scope,
    HardConstraint,
    FactCapacity,
    FuelExhausted,
}

impl SemanticTaskRefusal {
    pub const fn canonical_kind(self) -> &'static str {
        match self {
            Self::Scope => "task-scope",
            Self::HardConstraint => "hard-constraint",
            Self::FactCapacity => "fact-capacity",
            Self::FuelExhausted => "fuel-exhausted",
        }
    }
}

/// One native evaluation of the fixed base/learned roster. The selector runs
/// only on device; these are the resulting facts, not caller-supplied scores.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct SemanticTaskEvaluation {
    pub binding: Identity256,
    pub query_count: u64,
    pub winner: u64,
    pub return_value: i64,
    pub facts: [SemanticTaskFacts; 3],
}

/// Device terminal and both ordered edit results. A refused lane has no root;
/// successful edit receipts preceding rollback are not published graph state.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct SemanticTransitionLane {
    /// No sealed root is produced for a task-local refusal. An owner refusal
    /// remains an actual owner error, distinct from an evaluator decision.
    pub root: Option<Result<(SemanticRootHandle, SemanticRootSnapshot), SemanticHypergraphError>>,
    pub task_refusal: Option<SemanticTaskRefusal>,
    /// Decoded typed rules attempted in the two edit slots, including a lane
    /// later rejected by a hard constraint. Graph support edits remain in `edits`.
    pub program_rules: [Option<crate::SemanticProgramRule>; 2],
    pub edits: [Result<Option<SemanticInsertOutcome>, SemanticHypergraphError>; 2],
    /// Actual owner work, retained even when the candidate is discarded.
    pub work: SemanticTransitionWork,
}

/// Work performed by the two semantic edits of one learned candidate. These are
/// device counters, not estimates from the sampled actions or final truth alone.
#[repr(C)]
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct SemanticTransitionWork {
    /// Calls to the modifying semantic owner, including a call that refuses.
    /// A NO_EDIT or a suppressed edit does not call that owner.
    pub edit_commands: u64,
    /// New reachable support attachments, or new materialized facts for an
    /// editable program, made before any candidate discard.
    pub added_supports: u64,
    /// Successful support edits that change a truth other than NEITHER, or
    /// changed query truths after program materialization.
    pub defined_truth_changes: u64,
}

impl SemanticTransitionWork {
    #[cfg(any(test, feature = "semantic-policy"))]
    fn raw_structural_cost(self) -> u64 {
        self.edit_commands + self.added_supports + self.defined_truth_changes
    }

    fn is_valid(self, editable_program: bool, queries: u32) -> bool {
        if self.edit_commands > 2 {
            return false;
        }
        if editable_program {
            self.added_supports <= crate::semantic_program::RESIDENT_PROGRAM_FACT_CAPACITY as u64
                && self.defined_truth_changes <= u64::from(queries)
                && (self.edit_commands != 0
                    || (self.added_supports == 0 && self.defined_truth_changes == 0))
        } else {
            self.added_supports <= self.edit_commands
                && self.defined_truth_changes <= self.added_supports
        }
    }
}

/// Cumulative provider counters and explicit session stream waits. Launch metadata
/// and terminal observations remain separate counters, never implied zeros.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct SemanticTransitionHostIoStats {
    pub htod_bytes: u64,
    pub dtoh_bytes: u64,
    pub htod_calls: u64,
    pub dtoh_calls: u64,
    pub launch_metadata_bytes: u64,
    pub launch_metadata_calls: u64,
    pub metadata_dtoh_calls: u64,
    pub observation_bytes: u64,
    pub observation_calls: u64,
    pub session_stream_waits: u64,
}

/// Disposition of the original terminal wait, never inferred from an error.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum SemanticSegmentTerminalWait {
    NotStarted,
    CompletionUnknown,
    Complete,
}

/// Original submission snapshots around ingress, whole-graph execution and
/// completion-outcome export, before subsequent completed-step observations.
///
/// Handles and provider/stream identities are process-local profiler correlation
/// values, not persistent identities or evidence of transfer-free execution. The
/// graph interval covers its first admission through its last release; no step,
/// backward, publication or subsequent forward is removed from that interval.
/// Absent snapshots mean the original stage did not return known completion.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct SemanticPreparedSegmentTransfers {
    pub provider_identity: u64,
    pub session_instance: Identity256,
    pub domain_stream_id: crate::device_runtime::StreamId,
    pub cuda_stream_id: u64,
    pub graph_handle: u64,
    pub graph_exec_handle: u64,
    pub first_step_token: u64,
    pub last_step_token: u64,
    pub step_count: usize,
    pub before_ingress: SemanticTransitionHostIoStats,
    pub before_launch: Option<SemanticTransitionHostIoStats>,
    pub after_terminal_wait: Option<SemanticTransitionHostIoStats>,
    pub after_completion_export: Option<SemanticTransitionHostIoStats>,
    pub terminal_wait: SemanticSegmentTerminalWait,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum SemanticTransitionError {
    CatalogueMismatch,
    MaterialAllocationRefused {
        reason: xlog_core::error::AllocationRefusal,
    },
    InvalidInput {
        detail: String,
    },
    InvalidFinalSupport {
        completed_draws: u64,
    },
    NonFinitePolicyInput {
        completed_draws: u64,
    },
    WorkCounterOverflow {
        completed_draws: u64,
    },
    InvalidPolicyGradient {
        status: u64,
    },
    InvalidTrainingView {
        status: u64,
    },
    RejectedModelUpdate {
        evidence: Box<SemanticTrainingCanaryRefusalRecord>,
    },
    CapacityExceeded {
        evidence: SemanticCapacityRefusalRecord,
    },
    InvalidTaskBank,
    InvalidTaskBase,
    TaskOwnerFailure,
    PublicationRefused {
        status: u64,
    },
    OverlappingInputs,
    OverlappingLaunch,
    UnconsumedPolicyTape,
    UnpublishedTask,
    NotBound,
    NotCaptured,
    NoPendingLaunch,
    GenerationExhausted,
    ObservationMismatch,
    Poisoned,
    Semantic(SemanticHypergraphError),
    Runtime {
        operation: &'static str,
        detail: String,
    },
    NativeExecutionFailure {
        operation: &'static str,
        status: sys::CUresult,
    },
    NativeCompletionPending {
        operation: &'static str,
    },
}

impl fmt::Display for SemanticTransitionError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{self:?}")
    }
}
impl std::error::Error for SemanticTransitionError {}

fn runtime_error(operation: &'static str, error: impl fmt::Display) -> SemanticTransitionError {
    SemanticTransitionError::Runtime {
        operation,
        detail: error.to_string(),
    }
}

fn native_runtime_error(
    operation: &'static str,
    error: cudarc::driver::DriverError,
) -> SemanticTransitionError {
    SemanticTransitionError::NativeExecutionFailure {
        operation,
        status: error.0,
    }
}

/// One original cold copy, including its destination and completion event.
/// A resolver can join this owner after a late error, but cannot submit it twice.
struct PublicationRead<T: DeviceRepr + Copy> {
    issuer: Arc<()>,
    read: crate::device::RetainedDeviceRead<T>,
    uncertain_dma_bytes: Option<usize>,
    dma_observation_recorded: bool,
    materialization_dma_recorded: bool,
    _material_reservation: Option<Arc<SemanticReplayMaterialReservation>>,
    _byte_custody: Option<Arc<dyn Send + Sync>>,
    #[cfg(feature = "semantic-policy")]
    dma_allowance: Option<std::sync::Weak<Mutex<native_work_bound::ColdNativeAllowance>>>,
    #[cfg(feature = "semantic-policy")]
    dma_recorded: bool,
}

impl<T: DeviceRepr + Copy> PublicationRead<T> {
    fn uncertain_dma_byte_bound(&self) -> Option<usize> {
        self.uncertain_dma_bytes
    }

    fn observed_dma_bytes(&self) -> Option<usize> {
        if self.dma_observation_recorded {
            self.read.source().len().checked_mul(size_of::<T>())
        } else if !self.read.entered() {
            Some(0)
        } else {
            None
        }
    }

    fn known_completion_failure(&self) -> Option<sys::CUresult> {
        self.read.known_completion_failure()
    }

    fn completion_pending(&self) -> bool {
        self.read.completion_pending()
    }
}

/// Retained stages of one full cold publication observation. The handle owns
