/// Results retain each actual device invocation. An early admission refusal
/// owns no numerical invocation, selected receipts, or derivative authority.
/// Intermediate root records are historical receipts; a later step may retire
/// their slots. Acquire the canonical final reader for the current publication.
#[derive(Clone, Debug)]
#[expect(
    clippy::large_enum_variant,
    reason = "completed outcomes retain their original invocation and step owners"
)]
pub enum SemanticPreparedStepOutcome {
    Skipped {
        step: SemanticPreparedStep,
        status: u64,
    },
    /// A private current-model score of original choices, not a world action.
    PolicyScore {
        step: SemanticPreparedStep,
        bank: u8,
        status: u64,
    },
    Completed {
        step: SemanticPreparedStep,
        invocation: SemanticRngBinding,
        bank: u8,
        transition: SemanticTransitionKind,
        outcome: SemanticTransitionOutcome,
    },
}

const _: () = assert!(
    size_of::<PreparedStepResult>()
        == size_of::<PublicationHeader>() + 32 + size_of::<AttemptReceipt>()
);

fn prepared_step_allocation_bytes(
    input_bytes: usize,
    feedback_bytes: usize,
    policy_bytes: usize,
) -> Result<u64, SemanticTransitionError> {
    [
        size_of::<PublicationLease>(),
        size_of::<PreparedStepResult>(),
        input_bytes,
        feedback_bytes,
        policy_bytes,
    ]
    .into_iter()
    .try_fold(0usize, |sum, bytes| {
        sum.checked_add(bytes)
            .ok_or(SemanticTransitionError::GenerationExhausted)
    })
    .and_then(|bytes| {
        u64::try_from(bytes).map_err(|_| SemanticTransitionError::GenerationExhausted)
    })
}

fn prepared_segment_allocation_bytes(
    step_bytes: u64,
    transition_bound: usize,
    training_origin_bytes: usize,
) -> Result<u64, SemanticTransitionError> {
    if transition_bound == 0 {
        return Err(publication_input_error(
            "a prepared segment requires a positive transition bound",
        ));
    }
    u64::try_from(transition_bound)
        .ok()
        .and_then(|bound| step_bytes.checked_mul(bound))
        .and_then(|bytes| {
            u64::try_from(training_origin_bytes)
                .ok()
                .and_then(|origin_bytes| bytes.checked_add(origin_bytes))
        })
        .ok_or(SemanticTransitionError::GenerationExhausted)
}

/// Frozen bounds for the content, work, and external allocations currently
/// admitted during prepared-segment construction. Numerical-domain buffers
/// require their own native-derived extension before the full peak is claimed.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct SemanticSegmentColdCapacity {
    pub segment_capacity_bytes: u64,
    pub other_external_cuda_bytes: u64,
}

impl SemanticSegmentColdCapacity {
    fn external_floor(self) -> Result<u64, SemanticTransitionError> {
        if self.segment_capacity_bytes == 0 {
            return Err(publication_input_error(
                "prepared segment requires its positive original external slab limit",
            ));
        }
        self.segment_capacity_bytes
            .checked_add(self.other_external_cuda_bytes)
            .ok_or(SemanticTransitionError::GenerationExhausted)
    }
}

/// Count-derived child of one original structural admission. These counts are
/// frozen before allocation; they are not fields of the signed program bytes.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct PreparedStepLayout {
    model_work_capacity: usize,
}

impl PreparedStepLayout {
    fn model_work_bytes(self) -> Result<u64, SemanticTransitionError> {
        self.model_work_capacity
            .checked_mul(2 * size_of::<ModelWorkEvent>() + 3 * size_of::<u64>())
            .and_then(|bytes| u64::try_from(bytes).ok())
            .ok_or(SemanticTransitionError::GenerationExhausted)
    }

    fn late_native_bytes(self) -> Result<u64, SemanticTransitionError> {
        self.model_work_bytes()
    }
}

#[cfg(feature = "semantic-policy")]
fn policy_buffer_bytes(
    layout: &SemanticPolicyLayout,
    mask_cells: usize,
) -> Result<usize, SemanticTransitionError> {
    let differentiable_cells = [
        layout.parameter_cells,
        layout.score_cells(),
        layout.recurrent_cells(),
        32 * TEXT_CARDINALITY,
    ]
    .into_iter()
    .try_fold(0usize, |sum, cells| {
        sum.checked_add(cells)
            .ok_or(SemanticTransitionError::GenerationExhausted)
    })?;
    let primal_cells = differentiable_cells
        .checked_add(layout.retained_score_cells())
        .ok_or(SemanticTransitionError::GenerationExhausted)?;
    let adjoint_cells = differentiable_cells
        .checked_add(COMPONENT_COUNT)
        .ok_or(SemanticTransitionError::GenerationExhausted)?;
    let adjoint_cells = adjoint_cells
        .checked_mul(2)
        .ok_or(SemanticTransitionError::GenerationExhausted)?;
    let numerical_cells = [
        // Original E/D plus explicitly assembled primal envelopes.
        (layout.parameter_cells, 9usize),
        (COMPONENT_COUNT, 9),
        (32 * TEXT_CARDINALITY, 4),
        (128, 3),
        (layout.score_cells(), 3),
        (layout.recurrent_cells(), 3),
    ]
    .into_iter()
    .try_fold(0usize, |total, (cells, width)| {
        cells
            .checked_mul(width)
            .and_then(|cells| total.checked_add(cells))
            .ok_or(SemanticTransitionError::GenerationExhausted)
    })?;
    let adjoint_numerical_cells = differentiable_cells
        .checked_add(COMPONENT_COUNT)
        .and_then(|cells| cells.checked_mul(8))
        .and_then(|cells| {
            layout
                .parameter_cells
                .checked_add(32 * TEXT_CARDINALITY)
                .and_then(|roots| roots.checked_add(COMPONENT_COUNT))
                // In addition to the internal coherent labels above, export
                // full E (two doubles) and actor/full D (eight doubles).
                .and_then(|roots| roots.checked_mul(10))
                .and_then(|roots| cells.checked_add(roots))
        })
        .and_then(|cells| cells.checked_add(8 * COMPONENT_COUNT))
        .and_then(|cells| cells.checked_mul(2))
        .ok_or(SemanticTransitionError::GenerationExhausted)?;
    let numerical_cells = numerical_cells
        .checked_add(adjoint_numerical_cells)
        .ok_or(SemanticTransitionError::GenerationExhausted)?;
    let uniform_cells = layout
        .parameter_cells
        .checked_add(COMPONENT_COUNT)
        .and_then(|cells| cells.checked_mul(2))
        // Every unknown mapped text row has the same category domain. Keep
        // one private row and the required 32-row region-major public output.
        .and_then(|cells| cells.checked_add(33 * TEXT_CARDINALITY))
        // Private coherent labels and distinct region-major export storage.
        .and_then(|cells| cells.checked_mul(8))
        .and_then(|cells| cells.checked_add(layout.recurrent_cells() * 12))
        .and_then(|cells| cells.checked_add(layout.score_cells() * 12))
        .and_then(|cells| cells.checked_add(128 * 4 + COMPONENT_COUNT * 8))
        .ok_or(SemanticTransitionError::GenerationExhausted)?;
    let numerical_cells = numerical_cells
        .checked_add(uniform_cells)
        .ok_or(SemanticTransitionError::GenerationExhausted)?;
    primal_cells
        // Each differentiable primal bank has a dedicated adjoint bank. Only the
        // forward hidden vector is shared scratch. A second retained adjoint bank
        // is reserved for temporal Update capture; coefficients and status keep
        // their own types in both banks.
        .checked_add(adjoint_cells)
        .and_then(|cells| cells.checked_add(128))
        .and_then(|cells| cells.checked_add(COMPONENT_COUNT))
        .and_then(|cells| cells.checked_mul(size_of::<f32>()))
        .and_then(|bytes| bytes.checked_add(2 * COMPONENT_COUNT * size_of::<f64>()))
        .and_then(|bytes| bytes.checked_add(2 * size_of::<u64>()))
        .and_then(|bytes| bytes.checked_add(2 * 11 * size_of::<u64>()))
        .and_then(|bytes| {
            bytes.checked_add(12 * size_of::<u64>() + size_of::<PolicyUniformDescriptor>())
        })
        .and_then(|bytes| {
            numerical_cells
                .checked_mul(8)
                .and_then(|extra| bytes.checked_add(extra))
        })
        .and_then(|bytes| bytes.checked_add(COMPONENT_COUNT * size_of::<SemanticPolicyPwlCell>()))
        .and_then(|bytes| {
            bytes.checked_add(COMPONENT_COUNT * size_of::<SemanticPolicySelectedScoreVjp>())
        })
        .and_then(|bytes| {
            mask_cells
                .checked_mul(2)
                .and_then(|masks| bytes.checked_add(masks))
        })
        .ok_or(SemanticTransitionError::GenerationExhausted)
}

fn validate_rebinding_ownership(
    prepared_segment: Option<&PreparedSegmentState>,
    unreconciled_acquisition: bool,
) -> Result<(), SemanticTransitionError> {
    if prepared_segment.is_some() {
        return Err(publication_input_error(
            "a prepared segment still owns its executable and native resources",
        ));
    }
    if unreconciled_acquisition {
        return Err(publication_input_error(
            "an unreconciled acquisition still owns its native step",
        ));
    }
    Ok(())
}

fn validate_prepared_completion(
    lease: &PublicationLease,
    parent: &PublicationHeader,
    result: &PreparedStepResult,
    instance: Identity256,
) -> Result<SemanticTransitionKind, SemanticTransitionError> {
    if lease.abi != 1
        || lease.status != 0
        || lease.active != 0
        || lease.instance != instance
        || lease.bank > 1
        || lease.bank != lease.word & 1
        || lease.epoch != lease.word >> 1
        || parent.abi != 1
        || parent.instance != instance
        || parent.publication_word != lease.word
        || parent.sealed_epoch != lease.epoch
        || result.abi != 1
        || result.header.abi != 1
        || result.header.instance != instance
        || result.header.publication_word != result.word
        || result.header.sealed_epoch != result.word >> 1
        || result.advanced > 1
        || result.advanced != u64::from(result.word != lease.word && result.refusal == 0)
    {
        return Err(SemanticTransitionError::ObservationMismatch);
    }
    if result.word != lease.word {
        let epoch = lease
            .epoch
            .checked_add(1)
            .filter(|&epoch| epoch <= u64::MAX >> 1)
            .ok_or(SemanticTransitionError::ObservationMismatch)?;
        if result.word != (epoch << 1) | ((lease.word ^ 1) & 1)
            || result.header.base_word != lease.word
            || result.attempt.abi != 2
            || result.attempt.transition_kind != lease.transition_kind
            || result.attempt.instance != result.header.instance
            || result.attempt.base_word != lease.word
            || result.attempt.next_word != result.word
            || result.attempt.logical_digest != result.header.logical_digest
        {
            return Err(SemanticTransitionError::ObservationMismatch);
        }
    } else if result.attempt != AttemptReceipt::default() {
        return Err(SemanticTransitionError::ObservationMismatch);
    }
    match lease.transition_kind {
        1 => Ok(SemanticTransitionKind::Proposal),
        2 => Ok(SemanticTransitionKind::Recompute),
        3 => Ok(SemanticTransitionKind::Drain),
        4 => Ok(SemanticTransitionKind::Update),
        _ => Err(SemanticTransitionError::ObservationMismatch),
    }
}

/// A score retains its acquired header unchanged and never owns an attempt.
fn validate_prepared_policy_score(
    lease: &PublicationLease,
    parent: &PublicationHeader,
    result: &PreparedStepResult,
    instance: Identity256,
) -> Result<(), SemanticTransitionError> {
    if result.abi != 2
        || result.word != lease.word
        || result.header != *parent
        || result.advanced != 0
        || result.attempt != AttemptReceipt::default()
        || lease.transition_kind != SemanticTransitionKind::Proposal.code()
    {
        return Err(SemanticTransitionError::ObservationMismatch);
    }
    let mut ordinary = *result;
    ordinary.abi = 1;
    validate_prepared_completion(lease, parent, &ordinary, instance)?;
    Ok(())
}

impl SemanticTransitionSession {
    /// Bind the original shared capacity once. This grants no content access.
    pub fn bind_replay_material_budget(
        &mut self,
        budget: &SemanticReplayMaterialBudget,
    ) -> Result<(), SemanticTransitionError> {
        self.graph
            .bind_replay_material_budget(budget)
            .map_err(SemanticTransitionError::Semantic)?;
        if let Some(original) = &self.replay_material_budget {
            if !original.same_pool(budget) {
                return Err(publication_input_error(
                    "replay material capacity cannot replace its original pool",
                ));
            }
        } else {
            self.replay_material_budget = Some(budget.clone());
        }
        Ok(())
    }

    pub fn replay_material_budget(&self) -> Option<&SemanticReplayMaterialBudget> {
        self.replay_material_budget.as_ref()
    }

    /// Cold identity of the actual original allocation/execution context.
    /// UUID v2 distinguishes a partition from its physical parent device.
    pub fn resource_device_identity(&self) -> Result<([u8; 16], u64), SemanticTransitionError> {
        let _uncaptured = crate::cuda_graph::reserve_uncaptured_stream(&self.stream)
            .map_err(|error| runtime_error("resource device identity", error))?;
        self.stream
            .context()
            .bind_to_thread()
            .map_err(|error| runtime_error("resource device context binding", error))?;
        let mut uuid = cudarc::driver::sys::CUuuid { bytes: [0; 16] };
        // SAFETY: this session retains its actual context/device; the cold
        // query does not construct another context or execute captured work.
        unsafe {
            cudarc::driver::sys::cuDeviceGetUuid_v2(&mut uuid, self.stream.context().cu_device())
                .result()
                .map_err(|error| runtime_error("resource device UUID", error))?;
        }
        Ok((
            uuid.bytes.map(|byte| byte as u8),
            self.stream.context().cu_ctx() as u64,
        ))
    }
}

#[cfg(feature = "semantic-policy")]
impl SemanticTransitionSession {
    /// Submit this Session's complete graph once with the freshly validated
    /// canonical authority snapshot. The metadata upload precedes graph launch.
    pub fn launch_prepared_segment(
        &mut self,
        authority_decisions: Vec<u8>,
    ) -> Result<(), SemanticTransitionError> {
        #[cfg(feature = "semantic-policy")]
        if self.actor_refresh.is_some() {
            return Err(publication_input_error(
                "an embedded actor executes only in its original outer segment",
            ));
        }
        self.ensure_quiescent()?;
        self.require_authenticated_task_observations()?;
        let storage = Arc::clone(
            self.publication
                .as_ref()
                .ok_or(SemanticTransitionError::NotBound)?,
        );
        let build = self
            .prepared_segment
            .as_ref()
            .ok_or(SemanticTransitionError::NotCaptured)?;
        if let Some(token) = build.parent_reader {
            if !build.parent_quiescent
                || self.readers.len() != 1
                || self
                    .readers
                    .get(&token)
                    .is_none_or(|reader| Arc::strong_count(&reader.aliases) != 1)
            {
                return Err(publication_input_error(
                    "prepared submission requires its original quiescent parent reader",
                ));
            }
        }
        if !build.finished
            || build.submitted
            || build.cancelled.load(Ordering::Acquire)
            || self.captured.is_none()
            || authority_decisions.is_empty()
        {
            return Err(publication_input_error(
                "prepared submission requires one unused graph and fresh canonical authority bytes",
            ));
        }
        #[cfg(feature = "semantic-policy")]
        self.require_prepared_actor_refresh_work_frozen()?;
        #[cfg(feature = "semantic-policy")]
        self.require_prepared_policy_work_frozen()?;
        for token in &build.tokens {
            let prepared = self
                .steps
                .get(token)
                .and_then(|step| step.prepared.as_ref())
                .ok_or(SemanticTransitionError::ObservationMismatch)?;
            if prepared.transition_recorded != PREPARED_TRANSITION_BANKS
                || prepared.branches.iter().any(|branch| {
                    branch.continuation.as_ref().is_none_or(|continuation| {
                        continuation.inputs.authority_bytes != authority_decisions.len() as u64
                    })
                })
            {
                return Err(publication_input_error(
                    "fresh authority snapshot differs from the captured continuation byte extent",
                ));
            }
        }
        let authority = storage
            .continuation_templates
            .iter()
            .find(|range| range.role == 39 && range.index == 0)
            .ok_or(SemanticTransitionError::ObservationMismatch)?;
        let slot = usize::try_from(authority.storage_slot)
            .map_err(|_| SemanticTransitionError::ObservationMismatch)?;
        let destination = storage
            .allocations
            .get(slot)
            .ok_or(SemanticTransitionError::ObservationMismatch)?;
        if authority.offset_bytes != 0 || authority_decisions.len() > destination.len() {
            return Err(publication_input_error(
                "fresh authority snapshot exceeds its original fixed allocation",
            ));
        }
        let recorder = self.prepared_segment_recorder()?;
        let graph = self.captured.as_ref().expect("checked captured graph");
        let transfers = Arc::new(SemanticPreparedSegmentTransfers {
            provider_identity: self.provider.provider_identity(),
            session_instance: storage.instance,
            domain_stream_id: self.domain.stream_id(),
            cuda_stream_id: crate::cuda_graph::stream_execution_id(&self.stream)
                .map_err(|error| runtime_error("prepared execution stream identity", error))?,
            graph_handle: graph.graph() as u64,
            graph_exec_handle: graph.exec() as u64,
            first_step_token: *build.tokens.first().expect("original nonempty roster"),
            last_step_token: *build.tokens.last().expect("original nonempty roster"),
            step_count: build.tokens.len(),
            before_ingress: self.host_io_stats(),
            before_launch: None,
            after_terminal_wait: None,
            after_completion_export: None,
            terminal_wait: SemanticSegmentTerminalWait::NotStarted,
        });
        let authority_upload = crate::device::RetainedDeviceWrite::new(
            &self.stream,
            &authority_decisions,
            storage.allocations[slot]
                .slice()?
                .view()
                .slice(..authority_decisions.len()),
        )
        .map_err(|error| runtime_error("prepared authority staging", error))?;
        let attempt = Arc::new(PreparedLaunchAttempt {
            closed: AtomicBool::new(false),
        });
        let frame = PreparedLaunchFrame(Arc::clone(&attempt));
        let build = self.prepared_segment.as_mut().expect("checked segment");
        build.submit()?;
        build.launch_attempt = Some(attempt);
        build.authority_upload = Some(authority_upload);
        // This original submission owns uncertainty separately from an abort
        // or a semantic graph integrity failure. Arm before its first effect.
        build.execution_poisoned = true;
        build.transfers = Some(transfers);
        self.publication_uploads = vec![(
            slot,
            PublicationPayload::Metadata(authority_decisions.into()),
        )];
        let result = (|| {
            let PublicationPayload::Metadata(bytes) = &self.publication_uploads[0].1 else {
                unreachable!("owned authority metadata")
            };
            self.provider.admit_launch_metadata_htod(bytes.len());
            let upload = self
                .prepared_segment
                .as_mut()
                .expect("original segment")
                .authority_upload
                .as_mut()
                .expect("original authority upload");
            upload
                .enqueue(&self.stream)
                .map_err(|error| runtime_error("prepared fresh authority upload", error))?;
            upload
                .resolve()
                .map_err(|error| runtime_error("prepared fresh authority completion", error))?;
            let before_launch = self.host_io_stats();
            self.prepared_segment_transfers_mut()?.before_launch = Some(before_launch);
            let graph = self
                .captured
                .as_ref()
                .expect("checked original captured graph");
            let build = self.prepared_segment.as_mut().expect("original segment");
            let mut submission_poison = false;
            enqueue_recorded(&self.domain, &mut submission_poison, recorder, |enqueue| {
                // Enqueue admission can fail before invoking this callback.
                // Only this exact original call admits later observation; it
                // never authorizes replay of a failed executable.
                #[cfg(feature = "semantic-policy")]
                {
                    *build.actor_refresh_execution.lock().map_err(|_| {
                        XlogError::Kernel("original parent execution owner poisoned".into())
                    })? = actor_refresh::ActorRefreshParentExecution::LaunchEntered;
                }
                build.graph_call_entered = true;
                graph.launch_in(enqueue)
            })
        })();
        // Even an unwinding original call closes this exact frame. A later
        // cancellation can never race a still-admitted graph callback.
        drop(frame);
        if result.is_err() {
            self.pending = self
                .prepared_segment
                .as_ref()
                .is_some_and(|build| build.graph_call_entered);
            return result;
        }
        self.pending = true;
        Ok(())
    }

    fn retire_prepared_authority_without_graph(
        &mut self,
        steps: &[SemanticPreparedStep],
    ) -> Result<(), SemanticTransitionError> {
        let build = self
            .prepared_segment
            .as_mut()
            .ok_or(SemanticTransitionError::NotCaptured)?;
        if !build.submitted
            || build.completed
            || build.graph_call_entered
            || self.pending
            || steps.len() != build.tokens.len()
            || steps.iter().zip(&build.tokens).any(|(step, token)| {
                step.token != *token
                    || build
                        .check_retained(step, &self.publication_issuer)
                        .is_err()
            })
        {
            return Err(publication_input_error(
                "authority retirement requires its exact never-called original graph attempt",
            ));
        }
        if build.has_never_graph_called_proof() {
            return Ok(());
        }
        let attempt = build
            .launch_attempt
            .as_ref()
            .ok_or(SemanticTransitionError::ObservationMismatch)?;
        if !attempt.closed.load(Ordering::Acquire) {
            return Err(publication_input_error(
                "original graph launch frame remains open",
            ));
        }
        build
            .authority_upload
            .as_mut()
            .ok_or(SemanticTransitionError::ObservationMismatch)?
            .retire_without_result(&self.stream)
            .map_err(|error| runtime_error("original authority upload retirement", error))?;
        build.never_graph_called = Some(PreparedNeverGraphCalled {
            scope: Arc::clone(&build.scope),
            attempt: Arc::clone(attempt),
        });
        // Only this original ingress uncertainty is resolved. The submission
        // reservation, Program attempt and independent Session poison remain.
        build.execution_poisoned = false;
        Ok(())
    }

    /// True only after the full ordered roster, work certificates, publication
    /// lineage and terminal reader release have been reconciled successfully.
    /// Stream completion alone does not establish a recoverable result.
    pub fn prepared_segment_completion_known(&self) -> bool {
        self.prepared_segment
            .as_ref()
            .is_some_and(|build| build.completed)
    }

    pub fn prepared_segment_continuation(
        &self,
        steps: &[SemanticPreparedStep],
    ) -> Result<SemanticPreparedSegmentContinuation, SemanticTransitionError> {
        if self.poisoned || self.graph.ensure_not_poisoned().is_err() {
            return Err(SemanticTransitionError::Poisoned);
        }
        let build = self
            .prepared_segment
            .as_ref()
            .ok_or(SemanticTransitionError::NotCaptured)?;
        if !build.submitted
            || build.completed
            || build
                .launch_attempt
                .as_ref()
                .is_none_or(|attempt| !attempt.closed.load(Ordering::Acquire))
            || steps.len() != build.tokens.len()
            || steps.iter().zip(&build.tokens).any(|(step, token)| {
                step.token != *token
                    || build
                        .check_retained(step, &self.publication_issuer)
                        .is_err()
                    || self
                        .steps
                        .get(token)
                        .is_none_or(|owner| owner.prepared.is_none() || owner.identity.is_some())
            })
        {
            return Err(publication_input_error(
                "continuation requires its complete closed original prepared launch attempt",
            ));
        }
        Ok(if build.graph_call_entered {
            SemanticPreparedSegmentContinuation::GraphCallEntered
        } else {
            SemanticPreparedSegmentContinuation::NeverGraphCalled
        })
    }

    /// Close this exact construction before any graph call. A failed submission
    /// reservation must first retire its original authority DMA and close the
    /// original launch frame; a false pending flag alone cannot admit this join.
    /// No reader decrement, result row, allocation release or rights is issued.
    pub fn cancel_prepared_segment_before_submission(
        &mut self,
        steps: &[SemanticPreparedStep],
    ) -> Result<SemanticPreparedSegmentNonSubmission, SemanticTransitionError> {
        let build = self
            .prepared_segment
            .as_ref()
            .ok_or(SemanticTransitionError::NotCaptured)?;
        if build.completed
            || steps.len() != build.tokens.len()
            || steps.iter().zip(&build.tokens).any(|(step, token)| {
                step.token != *token
                    || build
                        .check_retained(step, &self.publication_issuer)
                        .is_err()
                    || self
                        .steps
                        .get(token)
                        .is_none_or(|owner| owner.prepared.is_none() || owner.identity.is_some())
            })
        {
            return Err(publication_input_error(
                "cancellation changed its original unused complete roster",
            ));
        }
        if build.submitted {
            self.retire_prepared_authority_without_graph(steps)?;
        }
        let build = self
            .prepared_segment
            .as_ref()
            .expect("original cancellation scope");
        #[cfg(feature = "semantic-policy")]
        let embedded = if let Some(staged) = &self.actor_refresh {
            let execution = staged.proof.inner.execution.lock().map_err(|_| {
                publication_input_error("original actor submission custody lock is poisoned")
            })?;
            if !matches!(
                *execution,
                actor_refresh::ActorRefreshParentExecution::NeverSubmitted
            ) || !Arc::ptr_eq(&build.cancelled, &staged.proof.inner.cancelled)
                || !Arc::ptr_eq(
                    &build.actor_refresh_execution,
                    &staged.proof.inner.execution,
                )
                || !build.cancelled.load(Ordering::Acquire)
            {
                return Err(publication_input_error(
                    "embedded cancellation requires its original outer non-submission",
                ));
            }
            true
        } else {
            false
        };
        #[cfg(not(feature = "semantic-policy"))]
        let embedded = false;
        let initialization_pending = self.has_pending_prepared_segment_preparation();
        let structural_only = build.structural_only;
        if initialization_pending || structural_only {
            self.retire_original_prepared_initialization(steps)?;
        }
        let metadata_pending = self.has_pending_prepared_metadata_freeze();
        if metadata_pending {
            self.retire_original_prepared_metadata(steps)?;
        }
        let build = self
            .prepared_segment
            .as_ref()
            .expect("original cancellation scope");
        let resuming = steps
            .iter()
            .any(|step| self.steps[&step.token].consumer_completion.is_some());
        if !resuming {
            if !embedded {
                build.require_cancellable(steps)?;
            }
            if initialization_pending {
                if !self.original_prepared_initialization_may_submit() {
                    return Err(SemanticTransitionError::Poisoned);
                }
            } else if metadata_pending {
                if !self.original_prepared_metadata_may_submit() {
                    return Err(SemanticTransitionError::Poisoned);
                }
            } else {
                if !self.original_completion_base_may_submit_for_cancellation(
                    #[cfg(feature = "semantic-policy")]
                    Some(build),
                ) || self
                    .readers
                    .values()
                    .any(|reader| reader.retirement_pending)
                    || self
                        .steps
                        .values()
                        .any(|step| step.consumer_completion.is_some())
                {
                    return Err(SemanticTransitionError::Poisoned);
                }
            }
        }
        let construction = Arc::clone(&build.construction);
        let _construction = construction.try_lock().map_err(|error| {
            runtime_error("unsubmitted preparation construction exclusion", error)
        })?;
        let _ordinary = crate::cuda_graph::reserve_uncaptured_stream(&self.stream)
            .map_err(|error| runtime_error("unsubmitted preparation capture exclusion", error))?;
        let scope = Arc::clone(
            &self
                .prepared_segment
                .as_ref()
                .expect("original cancellation scope")
                .scope,
        );
        if !resuming {
            // Allocate the full original event roster before installing any
            // owner or closing the construction. No join can lose its custody.
            let original = steps
                .iter()
                .map(|step| {
                    let requested = self.steps[&step.token].consumer_streams.clone();
                    let streams = self.step_consumer_streams(
                        step.token,
                        &requested.iter().copied().collect::<Vec<_>>(),
                    )?;
                    let mut original = OriginalStepConsumers::new(
                        &self.stream,
                        None,
                        streams,
                        requested,
                        OriginalConsumerPurpose::Cancellation,
                    )?;
                    original.cancellation_scope = Some(Arc::clone(&scope));
                    Ok((step.token, Arc::new(Mutex::new(original))))
                })
                .collect::<Result<Vec<_>, SemanticTransitionError>>()?;
            for (token, original) in original {
                self.steps
                    .get_mut(&token)
                    .expect("original cancelled step")
                    .consumer_completion = Some(original);
            }
        } else {
            for step in steps {
                let original = self.steps[&step.token]
                    .consumer_completion
                    .as_ref()
                    .ok_or(SemanticTransitionError::ObservationMismatch)?
                    .lock()
                    .map_err(|_| publication_input_error("original cancellation owner poisoned"))?;
                if original.identity.is_some()
                    || original.purpose != OriginalConsumerPurpose::Cancellation
                    || original
                        .cancellation_scope
                        .as_ref()
                        .is_none_or(|original| !Arc::ptr_eq(original, &scope))
                    || original.requested_streams != self.steps[&step.token].consumer_streams
                {
                    return Err(SemanticTransitionError::ObservationMismatch);
                }
            }
        }
        let build = self
            .prepared_segment
            .as_mut()
            .expect("original cancellation scope");
        if !build.cancelled.load(Ordering::Acquire) {
            build.cancel(steps)?;
        }
        let proof = SemanticPreparedSegmentNonSubmission {
            steps: steps.to_vec(),
        };
        build.require_non_submission(&proof)?;
        build.initialization_pending.store(false, Ordering::Release);
        build.metadata_pending.store(false, Ordering::Release);
        for step in steps {
            let streams = self.steps[&step.token]
                .consumer_streams
                .iter()
                .copied()
                .collect::<Vec<_>>();
            self.complete_original_step_consumers(
                step.token,
                &streams,
                OriginalConsumerPurpose::Cancellation,
            )?;
        }
        // Keep completed earlier owners until the whole original roster joins.
        // Only this boundary permits their removal and a non-submission result.
        for step in steps {
            self.steps
                .get_mut(&step.token)
                .expect("joined original cancelled step")
                .consumer_completion = None;
        }
        #[cfg(feature = "semantic-policy")]
        {
            *self
                .prepared_segment
                .as_ref()
                .expect("original cancelled construction")
                .actor_refresh_execution
                .lock()
                .map_err(|_| {
                    publication_input_error("original parent execution owner poisoned")
                })? = actor_refresh::ActorRefreshParentExecution::NeverSubmitted;
        }
        Ok(proof)
    }

    pub fn complete_prepared_segment(
        &mut self,
    ) -> Result<Vec<SemanticPreparedStepOutcome>, SemanticTransitionError> {
        #[cfg(feature = "semantic-policy")]
        if self.actor_refresh.is_some() {
            // A premature public join is not a failed observation of an
            // admitted child. Only the actual outer completion admits it.
            self.require_actor_refresh_parent_completion()?;
            let result = self.complete_embedded_actor_segment();
            match &result {
                Ok(_) => {
                    self.prepared_segment
                        .as_mut()
                        .expect("original embedded actor")
                        .execution_poisoned = false;
                }
                Err(SemanticTransitionError::Runtime { .. }) => {
                    self.prepared_segment
                        .as_mut()
                        .expect("original embedded actor")
                        .execution_poisoned = true;
                }
                // The retained native marker is an authenticated reached
                // refusal, not an integrity failure or permission to replay.
                Err(SemanticTransitionError::PublicationRefused { .. }) => {}
                Err(_) => self.poisoned = true,
            }
            return result;
        }
        if !self
            .prepared_segment
            .as_ref()
            .is_some_and(|build| build.submitted && build.graph_call_entered && !build.completed)
        {
            if self.is_poisoned() {
                return Err(SemanticTransitionError::Poisoned);
            }
            return Err(SemanticTransitionError::NoPendingLaunch);
        }
        // Continuation joins and observes this original submitted graph only.
        // Historical poison grants no new submission and is not cleared here.
        let result = self.complete_prepared_segment_inner();
        if let Err(error) = &result {
            self.prepared_segment
                .as_mut()
                .expect("original submitted segment")
                .execution_poisoned = true;
            if !matches!(error, SemanticTransitionError::Runtime { .. }) {
                self.poisoned = true;
            }
        } else {
            self.pending = false;
            self.publication_uploads.clear();
            self.continuation_base = None;
            self.admitted_transition = None;
            self.text_binding = None;
        }
        result
    }

    fn complete_prepared_segment_inner(
        &mut self,
    ) -> Result<Vec<SemanticPreparedStepOutcome>, SemanticTransitionError> {
        let _ordinary = crate::cuda_graph::reserve_uncaptured_stream(&self.stream)
            .map_err(|error| runtime_error("prepared completion stream admission", error))?;
        if self.prepared_segment_transfers_mut()?.terminal_wait
            != SemanticSegmentTerminalWait::Complete
        {
            self.prepared_segment_transfers_mut()?.terminal_wait =
                SemanticSegmentTerminalWait::CompletionUnknown;
            let mut wait_poison = false;
            wait_on_stream(
                &self.stream,
                &mut wait_poison,
                &mut self.stream_waits,
                "prepared graph terminal wait",
                CudaStream::synchronize,
            )?;
            let after_terminal_wait = self.host_io_stats();
            let transfers = self.prepared_segment_transfers_mut()?;
            transfers.after_terminal_wait = Some(after_terminal_wait);
            transfers.terminal_wait = SemanticSegmentTerminalWait::Complete;
        }
        self.observe_prepared_segment_results(None)
    }

    #[cfg(feature = "semantic-policy")]
    fn observe_prepared_model_calls(
        &mut self,
        actual: DeviceMemoryView<u64>,
        events: &[ModelWorkEvent],
        certificate: FrozenModelWorkRecording,
        consumed: u64,
        mut observations: impl FnMut(
            &mut PreparedSegmentCompletionObservations,
        ) -> &mut PreparedStepCompletionObservations,
    ) -> Result<(), SemanticTransitionError> {
        if u64::try_from(events.len()).ok() != Some(certificate.event_count())
            || consumed > certificate.event_count()
        {
            return Err(SemanticTransitionError::ObservationMismatch);
        }
        let consumed =
            usize::try_from(consumed).map_err(|_| SemanticTransitionError::ObservationMismatch)?;
        let mut calls = 0u64;
        for event in &events[..consumed] {
            if event.kind != ModelWorkKind::ModelInvocation as u64 {
                continue;
            }
            let offset = event
                .actual
                .checked_sub(*actual.device_ptr())
                .and_then(|bytes| usize::try_from(bytes).ok())
                .filter(|bytes| bytes % size_of::<u64>() == 0)
                .map(|bytes| bytes / size_of::<u64>())
                .ok_or(SemanticTransitionError::ObservationMismatch)?;
            let end = offset
                .checked_add(3)
                .ok_or(SemanticTransitionError::ObservationMismatch)?;
            let view = actual
                .try_slice(offset..end)
                .ok_or(SemanticTransitionError::ObservationMismatch)?;
            let receipt = self.prepared_completion_read(view, |bundle| {
                observations(bundle).model_calls.entry(offset).or_default()
            })?;
            if receipt.as_slice() != [1, 0, 1] {
                return Err(SemanticTransitionError::ObservationMismatch);
            }
            calls = calls
                .checked_add(1)
                .ok_or(SemanticTransitionError::ObservationMismatch)?;
        }
        if calls > certificate.model_call_count()
            || (consumed == events.len() && calls != certificate.model_call_count())
        {
            return Err(SemanticTransitionError::ObservationMismatch);
        }
        Ok(())
    }

    #[cfg(feature = "semantic-policy")]
    fn observe_prepared_policy_work(
        &mut self,
        step: &SemanticPreparedStep,
        bank: usize,
        target: &ExecutionWork,
    ) -> Result<[u64; 9], SemanticTransitionError> {
        let build = self
            .prepared_segment
            .as_ref()
            .ok_or(SemanticTransitionError::NotBound)?;
        build.check_retained(step, &self.publication_issuer)?;
        if !build.submitted
            || build.capturing
            || !build.transfers.as_ref().is_some_and(|transfers| {
                transfers.terminal_wait == SemanticSegmentTerminalWait::Complete
            })
        {
            return Err(publication_input_error(
                "policy work observation requires its original completed graph wait",
            ));
        }
        let components = self.steps[&step.token]
            .prepared
            .as_ref()
            .and_then(|prepared| prepared.policy_work.as_ref())
            .ok_or(SemanticTransitionError::NotBound)?
            .components(bank)?;
        let mut native = [0u64; 9];
        for component in components {
            let tally = self.prepared_completion_read(component.tally, |bundle| {
                bundle
                    .steps
                    .entry(step.token)
                    .or_default()
                    .policy_work
                    .entry(component.slot)
                    .or_default()
            })?;
            if tally.len() != 11
                || tally[10] != 0
                || tally[1..10]
                    .iter()
                    .try_fold(0u64, |sum, &value| sum.checked_add(value))
                    != Some(tally[0])
            {
                return Err(SemanticTransitionError::ObservationMismatch);
            }
            for (index, value) in tally[1..10].iter().copied().enumerate() {
                if value > component.ceiling[index] {
                    return Err(SemanticTransitionError::ObservationMismatch);
                }
                native[index] = native[index]
                    .checked_add(value)
                    .ok_or(SemanticTransitionError::ObservationMismatch)?;
            }
        }
        if native
            .iter()
            .zip(target.native_events)
            .any(|(&part, total)| part > total)
        {
            return Err(SemanticTransitionError::ObservationMismatch);
        }
        Ok(native)
    }

    #[cfg(feature = "semantic-policy")]
    fn observe_actor_refresh_work(
        &mut self,
        step: &SemanticPreparedStep,
        bank: usize,
        target: &ExecutionWork,
        policy_native: [u64; 9],
    ) -> Result<(Vec<FrozenModelWorkRecording>, u64), SemanticTransitionError> {
        let components = self.prepared_actor_refresh_work_components(step, bank)?;
        let mut certificates = Vec::new();
        certificates
            .try_reserve_exact(
                components
                    .len()
                    .checked_mul(2)
                    .ok_or(SemanticTransitionError::GenerationExhausted)?,
            )
            .map_err(|error| runtime_error("actor work certificate reservation", error))?;
        let mut model_once = 0u64;
        let mut model_bound = 0u64;
        let mut model_events = 0u64;
        let mut native = policy_native;
        for component in components {
            let key = (step.token, component.kind, component.member_ordinal);
            let cached = self
                .prepared_segment
                .as_mut()
                .ok_or(SemanticTransitionError::NotCaptured)?
                .completion_observations
                .actor_refresh
                .entry(key)
                .or_default();
            if let Some(original) = &cached._material_reservation {
                if !Arc::ptr_eq(original, &component.completion_reservation) {
                    return Err(SemanticTransitionError::ObservationMismatch);
                }
            } else {
                cached._material_reservation = Some(Arc::clone(&component.completion_reservation));
            }
            let marker = self.prepared_completion_read_with_owner(
                component.marker.clone(),
                Some(Arc::clone(&component.material_reservation)),
                |bundle| &mut bundle.actor_refresh.entry(key).or_default().marker,
            )?[0];
            // An entered target bank must have reached every original initializer.
            if marker.abi != 1
                || !matches!(marker.status, 0 | 2)
                || marker.role
                    != u64::from(
                        component.kind == SemanticSourceContentGeometryKind::CurrentDemonstration,
                    )
            {
                return Err(SemanticTransitionError::ObservationMismatch);
            }
            let tally = self.prepared_completion_read(component.native_work.clone(), |bundle| {
                &mut bundle.actor_refresh.entry(key).or_default().native_work
            })?;
            if tally.len() != 11
                || tally[10] != 0
                || tally[1..10]
                    .iter()
                    .try_fold(0u64, |sum, value| sum.checked_add(*value))
                    != Some(tally[0])
            {
                return Err(SemanticTransitionError::ObservationMismatch);
            }
            for (index, value) in tally[1..10].iter().copied().enumerate() {
                if value > component.native_ceiling[index] {
                    return Err(SemanticTransitionError::ObservationMismatch);
                }
                native[index] = native[index]
                    .checked_add(value)
                    .ok_or(SemanticTransitionError::ObservationMismatch)?;
            }
            if marker.status == 2 {
                // The original initializer refused; child model/output owners were never entered.
                component.retain_initializer_refusal(marker, &tally)?;
                continue;
            }
            if marker.acquired_generation == 0 {
                return Err(SemanticTransitionError::ObservationMismatch);
            }
            let mut previous = None;
            for index in 0..2 {
                let lease = self
                    .prepared_completion_read(component.readers[index].clone(), |bundle| {
                        &mut bundle.actor_refresh.entry(key).or_default().steps[index].lease
                    })?[0];
                let result = self
                    .prepared_completion_read(component.results[index].clone(), |bundle| {
                        &mut bundle.actor_refresh.entry(key).or_default().steps[index].result
                    })?[0];
                if result.abi == 0 {
                    if lease.active != 0
                        || lease.abi != 0
                        || lease.transition_kind != 0
                        || !matches!(lease.status, 1..=5 | 7)
                    {
                        return Err(SemanticTransitionError::ObservationMismatch);
                    }
                    continue;
                }
                let parent = self
                    .prepared_completion_read(component.parents[index].clone(), |bundle| {
                        &mut bundle.actor_refresh.entry(key).or_default().steps[index].parent
                    })?[0];
                let score = component.kind
                    == SemanticSourceContentGeometryKind::CurrentDemonstration
                    && index == 1;
                let transition = if score {
                    validate_prepared_policy_score(&lease, &parent, &result, component.instance)?;
                    SemanticTransitionKind::Proposal
                } else {
                    validate_prepared_completion(&lease, &parent, &result, component.instance)?
                };
                if transition
                    != [
                        SemanticTransitionKind::Recompute,
                        SemanticTransitionKind::Proposal,
                    ][index]
                    || lease.bank != index as u64
                    || parent.model_generation != marker.acquired_generation
                    || (index == 1 && previous != Some(parent))
                {
                    return Err(SemanticTransitionError::ObservationMismatch);
                }
                previous = Some(result.header);
                let state = self
                    .prepared_completion_read(component.states[index].clone(), |bundle| {
                        &mut bundle.actor_refresh.entry(key).or_default().steps[index].state
                    })?[0];
                if u64::from(state.model_generation) != parent.model_generation
                    || u64::from(state.family_id) != parent.family_id
                    || state.stream_serial != parent.stream_serial
                    || state.proposal != parent.proposal
                {
                    return Err(SemanticTransitionError::ObservationMismatch);
                }
                if score
                    && (state.blocks != 0
                        || state.next_proposal != parent.proposal
                        || state.status != result.refusal
                        || state.actor_eligible != 0
                        || state.action_batch.abi != 0)
                {
                    return Err(SemanticTransitionError::ObservationMismatch);
                }
                let work = state.execution_work;
                if work
                    .native_events
                    .iter()
                    .zip(component.transition_ceilings[index])
                    .any(|(actual, ceiling)| *actual > ceiling)
                {
                    return Err(SemanticTransitionError::ObservationMismatch);
                }
                if work.model_bound == 0 {
                    if !work.validate_model_certificates([], state.status == 11) {
                        return Err(SemanticTransitionError::ObservationMismatch);
                    }
                } else {
                    let certificate = component.model_recordings[index];
                    if !work.validate_model_certificates([certificate], state.status == 11) {
                        return Err(SemanticTransitionError::ObservationMismatch);
                    }
                    self.observe_prepared_model_calls(
                        component.model_actual[index].clone(),
                        &component.model_event_records[index],
                        certificate,
                        work.model_events,
                        |bundle| &mut bundle.actor_refresh.entry(key).or_default().steps[index],
                    )?;
                    certificates.push(certificate);
                }
                model_once = model_once
                    .checked_add(work.model_once)
                    .ok_or(SemanticTransitionError::ObservationMismatch)?;
                model_bound = model_bound
                    .checked_add(work.model_bound)
                    .ok_or(SemanticTransitionError::ObservationMismatch)?;
                model_events = model_events
                    .checked_add(work.model_events)
                    .ok_or(SemanticTransitionError::ObservationMismatch)?;
                for (sum, value) in native.iter_mut().zip(work.native_events) {
                    *sum = sum
                        .checked_add(value)
                        .ok_or(SemanticTransitionError::ObservationMismatch)?;
                }
            }
        }
        if model_once > target.model_once
            || model_bound > target.model_bound
            || model_events > target.model_events
            || native
                .iter()
                .zip(target.native_events)
                .any(|(child, total)| *child > total)
        {
            return Err(SemanticTransitionError::ObservationMismatch);
        }
        Ok((certificates, model_events))
    }

    fn observe_prepared_segment_results(
        &mut self,
        model_generation: Option<u64>,
    ) -> Result<Vec<SemanticPreparedStepOutcome>, SemanticTransitionError> {
        if let Some(token) = self
            .prepared_segment
            .as_ref()
            .expect("submitted segment")
            .parent_reader
        {
            let identity = self.steps[&token]
                .identity
                .ok_or(SemanticTransitionError::ObservationMismatch)?;
            let reader = self
                .prepared_completion_read(self.readers[&token].device.view(), |observations| {
                    &mut observations.parent_reader
                })?[0];
            if reader.abi != 1
                || reader.status != 0
                || reader.active != 0
                || reader.instance != identity.instance
                || reader.word != identity.word
            {
                return Err(SemanticTransitionError::ObservationMismatch);
            }
        }
        let handles = self
            .prepared_segment
            .as_ref()
            .expect("submitted segment")
            .handles()?;
        let storage = Arc::clone(
            self.publication
                .as_ref()
                .ok_or(SemanticTransitionError::NotBound)?,
        );
        let mut outcomes = Vec::new();
        outcomes
            .try_reserve_exact(handles.len())
            .map_err(|error| runtime_error("prepared outcome reservation", error))?;
        let mut previous = None;
        for step in handles {
            let prepared = self.steps[&step.token]
                .prepared
                .as_ref()
                .ok_or(SemanticTransitionError::ObservationMismatch)?;
            #[cfg(feature = "semantic-policy")]
            if let Some(outcome) = &prepared.observed_outcome {
                if let Some(result) = prepared.observed_result {
                    previous = Some(result.header);
                }
                outcomes.push(outcome.clone());
                continue;
            }
            let reader = prepared.reader.view();
            let result_view = prepared.result.view();
            let lease = self.prepared_completion_read(reader, |observations| {
                &mut observations.steps.entry(step.token).or_default().lease
            })?[0];
            let result = self.prepared_completion_read(result_view, |observations| {
                &mut observations.steps.entry(step.token).or_default().result
            })?[0];
            if result.abi == 0 {
                if lease.active != 0
                    || lease.abi != 0
                    || lease.transition_kind != 0
                    || !matches!(lease.status, 1..=5 | 7)
                {
                    return Err(SemanticTransitionError::ObservationMismatch);
                }
                #[cfg(feature = "semantic-policy")]
                let token = step.token;
                let outcome = SemanticPreparedStepOutcome::Skipped {
                    step,
                    status: lease.status,
                };
                #[cfg(feature = "semantic-policy")]
                {
                    self.steps
                        .get_mut(&token)
                        .expect("retained original step")
                        .prepared
                        .as_mut()
                        .expect("retained original prepared owner")
                        .observed_outcome = Some(outcome.clone());
                }
                outcomes.push(outcome);
                continue;
            }
            let inputs = Arc::clone(
                self.steps[&step.token]
                    .inputs
                    .as_ref()
                    .ok_or(SemanticTransitionError::ObservationMismatch)?,
            );
            let parent = self.prepared_completion_read(inputs.header.view(), |observations| {
                &mut observations.steps.entry(step.token).or_default().parent
            })?[0];
            if model_generation.is_some_and(|generation| parent.model_generation != generation) {
                return Err(SemanticTransitionError::ObservationMismatch);
            }
            if previous.is_some_and(|header| header != parent) {
                return Err(SemanticTransitionError::ObservationMismatch);
            }
            let score = result.abi == 2;
            let transition = if score {
                #[cfg(feature = "semantic-policy")]
                if self
                    .actor_refresh
                    .as_ref()
                    .is_none_or(|staged| !staged.proof.is_demonstration())
                {
                    return Err(SemanticTransitionError::ObservationMismatch);
                }
                #[cfg(not(feature = "semantic-policy"))]
                return Err(SemanticTransitionError::ObservationMismatch);
                validate_prepared_policy_score(&lease, &parent, &result, storage.instance)?;
                SemanticTransitionKind::Proposal
            } else {
                validate_prepared_completion(&lease, &parent, &result, storage.instance)?
            };
            let bank = u8::try_from(lease.bank)
                .map_err(|_| SemanticTransitionError::ObservationMismatch)?;
            let (state_view, receipts, update_refusal_view) =
                {
                    let prepared = self.steps[&step.token]
                        .prepared
                        .as_ref()
                        .expect("original prepared owner");
                    let branch = prepared
                        .branches
                        .get(usize::from(bank))
                        .ok_or(SemanticTransitionError::ObservationMismatch)?;
                    (
                        branch.state.view(),
                        branch
                            .receipts
                            .as_ref()
                            .ok_or(SemanticTransitionError::ObservationMismatch)?
                            .view(),
                        branch.model_update.as_ref().map(|update| {
                            (
                                update.refusal.view(),
                                update.canary_results.view(),
                                branch.continuation.as_ref().and_then(|continuation| {
                                    continuation.text_binding.capacity_refusal.as_ref().map(
                                        |cause| {
                                            (
                                                cause.snapshot.view(),
                                                cause.allocation_ordinal,
                                                cause.capacity_bytes,
                                            )
                                        },
                                    )
                                }),
                            )
                        }),
                    )
                };
            let (canary_refusal, capacity_refusal) = match (transition, update_refusal_view) {
                (SemanticTransitionKind::Update, Some((view, results, capacity))) => {
                    let results = self.prepared_completion_read(results, |observations| {
                        &mut observations
                            .steps
                            .entry(step.token)
                            .or_default()
                            .canary_results
                    })?;
                    let refusal = self.prepared_completion_read(view, |observations| {
                        &mut observations
                            .steps
                            .entry(step.token)
                            .or_default()
                            .canary_refusal
                    })?[0];
                    let capacity = if let Some((view, ordinal, bytes)) = capacity {
                        let record = self.prepared_completion_read(view, |observations| {
                            &mut observations
                                .steps
                                .entry(step.token)
                                .or_default()
                                .capacity_refusal
                        })?[0];
                        decode_capacity_refusal(record, (ordinal, bytes))?
                    } else {
                        None
                    };
                    (decode_canary_refusal(refusal, &results)?, capacity)
                }
                (SemanticTransitionKind::Update, None) | (_, Some(_)) => {
                    return Err(SemanticTransitionError::ObservationMismatch);
                }
                (_, None) => (None, None),
            };
            let state = self.prepared_completion_read(state_view, |observations| {
                &mut observations.steps.entry(step.token).or_default().state
            })?[0];
            if score
                && (state.blocks != 0
                    || state.next_proposal != parent.proposal
                    || state.proposal != parent.proposal
                    || state.status != result.refusal
                    || u64::from(state.model_generation) != parent.model_generation
                    || state.stream_serial != parent.stream_serial
                    || u64::from(state.family_id) != parent.family_id
                    || state.actor_eligible != 0
                    || state.action_batch.abi != 0)
            {
                return Err(SemanticTransitionError::ObservationMismatch);
            }
            if transition != SemanticTransitionKind::Drain {
                {
                    let (certificate, actual, events) = {
                        let work = self.steps[&step.token]
                            .prepared
                            .as_ref()
                            .expect("original prepared owner")
                            .model_work
                            .as_ref()
                            .ok_or(SemanticTransitionError::ObservationMismatch)?;
                        let recording = work.recording_for_bank(usize::from(bank));
                        (
                            recording
                                .frozen_certificate()
                                .map_err(publication_input_error)?,
                            work.actual.view(),
                            recording.events().to_vec(),
                        )
                    };
                    let policy_native = self.observe_prepared_policy_work(
                        &step,
                        usize::from(bank),
                        &state.execution_work,
                    )?;
                    let (mut certificates, child_events) =
                        if transition == SemanticTransitionKind::Update {
                            self.observe_actor_refresh_work(
                                &step,
                                usize::from(bank),
                                &state.execution_work,
                                policy_native,
                            )?
                        } else {
                            (Vec::new(), 0)
                        };
                    let own_events = state
                        .execution_work
                        .model_events
                        .checked_sub(child_events)
                        .ok_or(SemanticTransitionError::ObservationMismatch)?;
                    self.observe_prepared_model_calls(
                        actual,
                        &events,
                        certificate,
                        own_events,
                        |bundle| bundle.steps.entry(step.token).or_default(),
                    )?;
                    certificates.push(certificate);
                    if !state
                        .execution_work
                        .validate_model_certificates(certificates, state.status == 11)
                    {
                        return Err(SemanticTransitionError::ObservationMismatch);
                    }
                }
            }
            if score {
                #[cfg(feature = "semantic-policy")]
                self.take_prepared_policy_tape(
                    &step,
                    usize::from(bank),
                    parent.rng_binding()?,
                    None,
                )?;
                previous = Some(result.header);
                let outcome = SemanticPreparedStepOutcome::PolicyScore {
                    step: step.clone(),
                    bank,
                    status: state.status,
                };
                let prepared = self
                    .steps
                    .get_mut(&step.token)
                    .expect("retained original score")
                    .prepared
                    .as_mut()
                    .expect("retained original score owner");
                prepared.observed = true;
                #[cfg(feature = "semantic-policy")]
                {
                    prepared.observed_parent = Some(parent);
                    prepared.observed_result = Some(result);
                    prepared.observed_outcome = Some(outcome.clone());
                }
                outcomes.push(outcome);
                continue;
            }
            let components = if transition == SemanticTransitionKind::Proposal {
                self.prepared_completion_read(receipts, |observations| {
                    &mut observations.steps.entry(step.token).or_default().components
                })?
            } else {
                Vec::new()
            };
            let invocation = parent.rng_binding()?;
            let reconciled = self
                .prepared_segment
                .as_mut()
                .expect("original prepared segment")
                .completion_observations
                .steps
                .entry(step.token)
                .or_default()
                .reconciled
                .clone();
            let outcome = match reconciled {
                Some(outcome) => outcome,
                None => {
                    let outcome = self.reconcile_prepared_transition(
                        &step,
                        &parent,
                        &result,
                        state,
                        components,
                        invocation,
                        PreparedTransitionEvidence {
                            transition,
                            canary_refusal,
                            capacity_refusal,
                        },
                    )?;
                    self.prepared_segment
                        .as_mut()
                        .expect("original prepared segment")
                        .completion_observations
                        .steps
                        .entry(step.token)
                        .or_default()
                        .reconciled = Some(outcome.clone());
                    outcome
                }
            };
            previous = Some(result.header);
            #[cfg(feature = "semantic-policy")]
            if transition == SemanticTransitionKind::Proposal {
                self.take_prepared_policy_tape(
                    &step,
                    usize::from(bank),
                    invocation,
                    match &outcome {
                        SemanticTransitionOutcome::Refused(refusal) => Some(*refusal),
                        _ => None,
                    },
                )?;
            }
            self.steps
                .get_mut(&step.token)
                .expect("retained original step")
                .prepared
                .as_mut()
                .expect("retained original prepared owner")
                .observed = true;
            #[cfg(feature = "semantic-policy")]
            if transition == SemanticTransitionKind::Update
                && matches!(&outcome, SemanticTransitionOutcome::Published(_))
            {
                self.steps
                    .get_mut(&step.token)
                    .expect("retained original step")
                    .prepared
                    .as_mut()
                    .expect("retained original prepared owner")
                    .group_update_published = true;
            }
            #[cfg(feature = "semantic-policy")]
            let token = step.token;
            let outcome = SemanticPreparedStepOutcome::Completed {
                step,
                invocation,
                bank,
                transition,
                outcome,
            };
            #[cfg(feature = "semantic-policy")]
            {
                let prepared = self
                    .steps
                    .get_mut(&token)
                    .expect("retained original step")
                    .prepared
                    .as_mut()
                    .expect("retained original prepared owner");
                prepared.observed_parent = Some(parent);
                prepared.observed_result = Some(result);
                prepared.observed_outcome = Some(outcome.clone());
            }
            outcomes.push(outcome);
        }
        let control = self.prepared_completion_read(storage.control.view(), |observations| {
            &mut observations.control
        })?[0];
        if control.abi != 1
            || control.instance != storage.instance
            || control.reader_gate != 0
            || previous.is_some_and(|header| control.word != header.publication_word)
        {
            return Err(SemanticTransitionError::ObservationMismatch);
        }
        let after_completion_export = self.host_io_stats();
        if self
            .prepared_segment
            .as_ref()
            .is_some_and(|build| build.transfers.is_some())
        {
            self.prepared_segment_transfers_mut()?
                .after_completion_export = Some(after_completion_export);
        }
        #[cfg(feature = "semantic-policy")]
        {
            let execution = Arc::clone(
                &self
                    .prepared_segment
                    .as_ref()
                    .expect("submitted segment")
                    .actor_refresh_execution,
            );
            let mut execution = execution
                .lock()
                .map_err(|_| publication_input_error("original parent execution owner poisoned"))?;
            if outcomes.iter().all(|outcome| {
                matches!(
                    outcome,
                    SemanticPreparedStepOutcome::Completed {
                        outcome: SemanticTransitionOutcome::Published(_),
                        ..
                    }
                )
            }) {
                if let Some(header) = previous {
                    self.retain_original_model_context_source_boundary(header)?;
                }
                self.complete_segment_instruction()?;
            }
            *execution = actor_refresh::ActorRefreshParentExecution::Completed;
        }
        let build = self.prepared_segment.as_mut().expect("submitted segment");
        build.completed = true;
        build.execution_poisoned = false;
        Ok(outcomes)
    }

    #[cfg(feature = "semantic-policy")]
    fn complete_embedded_actor_segment(
        &mut self,
    ) -> Result<Vec<SemanticPreparedStepOutcome>, SemanticTransitionError> {
        // No child marker or output may be observed while the sole outer graph
        // is unsubmitted or has unknown completion.
        self.require_actor_refresh_parent_completion()?;
        let staged = self
            .actor_refresh
            .as_ref()
            .ok_or(SemanticTransitionError::NotBound)?;
        let build = self
            .prepared_segment
            .as_ref()
            .ok_or(SemanticTransitionError::NotCaptured)?;
        if staged.state != actor_refresh::ActorRefreshCaptureState::Frozen
            || !build.finished
            || build.submitted
            || build.graph_retirement.is_none()
            || !Arc::ptr_eq(
                &build.actor_refresh_execution,
                &staged.proof.inner.execution,
            )
            || !Arc::ptr_eq(&build.cancelled, &staged.proof.inner.cancelled)
            || build.transitions
                != [
                    SemanticTransitionKind::Recompute,
                    SemanticTransitionKind::Proposal,
                ]
        {
            return Err(publication_input_error(
                "embedded completion requires its original frozen actor and outer execution",
            ));
        }
        if build.completed {
            let outcomes = build
                .tokens
                .iter()
                .map(|token| {
                    self.steps
                        .get(token)
                        .and_then(|step| step.prepared.as_ref())
                        .and_then(|prepared| prepared.observed_outcome.clone())
                        .ok_or(SemanticTransitionError::ObservationMismatch)
                })
                .collect::<Result<Vec<_>, _>>()?;
            self.finish_actor_refresh_policy_invocations()?;
            return Ok(outcomes);
        }
        let device = Arc::clone(&staged.device);
        if build.actor_refresh_observation.is_none() {
            if self.poisoned || self.graph.ensure_not_poisoned().is_err() {
                return Err(SemanticTransitionError::Poisoned);
            }
            let original = Arc::new(Mutex::new(self.stage_publication_read_with_owner(
                device.view(),
                Some(staged.proof.material_reservation()),
            )?));
            self.prepared_segment
                .as_mut()
                .expect("retained original actor")
                .actor_refresh_observation = Some(original);
        }
        let original = Arc::clone(
            self.prepared_segment
                .as_ref()
                .expect("retained original actor")
                .actor_refresh_observation
                .as_ref()
                .expect("installed original actor observation"),
        );
        let actual = {
            let mut original = original.lock().map_err(|_| {
                publication_input_error("original actor observation custody lock is poisoned")
            })?;
            if original.read.source().len() != 1
                || original.read.source().device_ptr() != device.view().device_ptr()
            {
                return Err(SemanticTransitionError::ObservationMismatch);
            }
            if !original.read.entered()
                && (self.poisoned || self.graph.ensure_not_poisoned().is_err())
            {
                return Err(SemanticTransitionError::Poisoned);
            }
            self.prepared_segment
                .as_mut()
                .expect("original embedded actor")
                .execution_poisoned = true;
            let mut read_poison = false;
            self.resolve_publication_read_with_poison(&mut original, &mut read_poison)?[0]
        };
        if actual.abi != 1 {
            return Err(SemanticTransitionError::ObservationMismatch);
        }
        match actual.status {
            1 => {
                let handles = self
                    .prepared_segment
                    .as_ref()
                    .expect("original actor")
                    .handles()?;
                let mut outcomes = Vec::with_capacity(handles.len());
                for step in handles {
                    let token = step.token;
                    let outcome = SemanticPreparedStepOutcome::Skipped {
                        step,
                        status: actual.status,
                    };
                    let prepared = self
                        .steps
                        .get_mut(&token)
                        .and_then(|owner| owner.prepared.as_mut())
                        .ok_or(SemanticTransitionError::ObservationMismatch)?;
                    prepared.observed_outcome = Some(outcome.clone());
                    outcomes.push(outcome);
                }
                self.prepared_segment
                    .as_mut()
                    .expect("original actor")
                    .completed = true;
                Ok(outcomes)
            }
            2 => {
                // The same outer completion already authenticated this marker
                // and its reached native tally. Retain its distinct final-use
                // certificate without fabricating child model outcomes.
                self.retain_actor_refresh_initializer_refusal(actual)?;
                self.prepared_segment
                    .as_mut()
                    .expect("original embedded actor")
                    .execution_poisoned = false;
                Err(SemanticTransitionError::PublicationRefused {
                    status: actual.status,
                })
            }
            0 if actual.acquired_generation != 0 => {
                let generation = u32::try_from(actual.acquired_generation)
                    .map_err(|_| SemanticTransitionError::ObservationMismatch)?;
                self.rng
                    .as_mut()
                    .ok_or(SemanticTransitionError::ObservationMismatch)?
                    .model_generation = generation;
                let outcomes =
                    self.observe_prepared_segment_results(Some(actual.acquired_generation))?;
                self.finish_actor_refresh_policy_invocations()?;
                Ok(outcomes)
            }
            _ => Err(SemanticTransitionError::ObservationMismatch),
        }
    }

    fn prepared_segment_transfers_mut(
        &mut self,
    ) -> Result<&mut SemanticPreparedSegmentTransfers, SemanticTransitionError> {
        self.prepared_segment
            .as_mut()
            .and_then(|build| build.transfers.as_mut())
            .and_then(Arc::get_mut)
            .ok_or(SemanticTransitionError::ObservationMismatch)
    }

    fn reconcile_prepared_transition(
        &mut self,
        step: &SemanticPreparedStep,
        parent: &PublicationHeader,
        result: &PreparedStepResult,
        state: DeviceState,
        components: Vec<SemanticTransitionReceipt>,
        invocation: SemanticRngBinding,
        evidence: PreparedTransitionEvidence,
    ) -> Result<SemanticTransitionOutcome, SemanticTransitionError> {
        let PreparedTransitionEvidence {
            transition,
            canary_refusal,
            capacity_refusal,
        } = evidence;
        if result.refusal != 0 || state.status == 10 {
            return Err(SemanticTransitionError::PublicationRefused {
                status: result.refusal,
            });
        }
        if (state.status == 16
            && (transition != SemanticTransitionKind::Update || capacity_refusal.is_none()))
            || (capacity_refusal.is_some() && !matches!(state.status, 11..=14 | 16))
        {
            return Err(SemanticTransitionError::ObservationMismatch);
        }
        if matches!(state.status, 2 | 5 | 11 | 12..=16) {
            let canary_refusal = if state.status == 15 {
                Some(canary_refusal.ok_or(SemanticTransitionError::ObservationMismatch)?)
            } else {
                None
            };
            let refusal = refused_terminal(
                &state,
                invocation,
                SemanticActionCatalogue::current().binding(),
                self.binding().digest,
                canary_refusal,
                capacity_refusal,
            )?;
            if result.word != parent.publication_word || result.header != *parent {
                return Err(SemanticTransitionError::ObservationMismatch);
            }
            let (root, snapshot) = self.observe_publication_root(&state, parent, 0)?;
            refused_root_cleanup(
                &state,
                self.graph.transition_arena()[1],
                u64::from(root.slot()),
                root.generation(),
            )?;
            self.root = root;
            self.base_snapshot = snapshot;
            self.next_proposal = parent.proposal;
            return Ok(SemanticTransitionOutcome::Refused(refusal));
        }
        match state.status {
            7 => return Err(SemanticTransitionError::InvalidTaskBank),
            8 => return Err(SemanticTransitionError::InvalidTaskBase),
            9 => return Err(SemanticTransitionError::TaskOwnerFailure),
            _ => {}
        }
        let next = parent
            .proposal
            .checked_add(u64::from(transition == SemanticTransitionKind::Proposal))
            .ok_or(SemanticTransitionError::GenerationExhausted)?;
        if state.status != 0
            || result.word == parent.publication_word
            || result.header.proposal != next
        {
            return Err(SemanticTransitionError::ObservationMismatch);
        }
        let winner = if transition == SemanticTransitionKind::Proposal {
            state.task_evaluation.winner
        } else {
            0
        };
        let index = match winner {
            0 => 0,
            1 => 3,
            2 => 6,
            _ => return Err(SemanticTransitionError::ObservationMismatch),
        };
        if winner > 0 && state.retired_roots_mask & (1 << (winner - 1)) != 0 {
            return Err(SemanticTransitionError::ObservationMismatch);
        }
        let root = self.observe_publication_root(&state, &result.header, index)?;
        self.finish_observed_transition(
            state,
            components,
            invocation,
            Some((result.header, root, transition)),
            true,
            Some((step, (parent.publication_word & 1) as usize)),
        )
    }
}

#[cfg(test)]
mod prepared_completion_tests {
    use super::*;

    #[test]
    fn prepared_allocation_plan_counts_original_banks_before_expanding_bound() {
        let schema = SemanticFeedbackSchema::new([&[1u8; 64], &[2u8; 64], &[3u8; 64]]).unwrap();
        let feedback = FeedbackAllocationPlan::new(&schema, 2, 3).unwrap();
        let expected_feedback = 2 * schema.feature_width * size_of::<f32>()
            + 2 * 9
            + (2 * 42 + 2 + 3 + 3 * SEMANTIC_FEEDBACK_SUPPORT_FIELDS.len()) * size_of::<u64>()
            + 6 * 4 * size_of::<u64>();
        assert_eq!(feedback.bytes, expected_feedback);
        let input_bytes = PreparedStepInputs::allocation_bytes(&[]).unwrap();
        assert_eq!(
            input_bytes,
            size_of::<PublicationHeader>() + 32 * size_of::<SourceSlot>() + u64::BITS as usize
        );
        let plans = [
            StepInputPlan {
                role: 1,
                index: 0,
                layout: SemanticTensorLayout::default(),
                banks: [
                    StepInputBankPlan {
                        storage_slot: 0,
                        span: 0..1024,
                    },
                    StepInputBankPlan {
                        storage_slot: 0,
                        span: 0..1024,
                    },
                ],
            },
            StepInputPlan {
                role: 2,
                index: 0,
                layout: SemanticTensorLayout::default(),
                banks: [
                    StepInputBankPlan {
                        storage_slot: 1,
                        span: 0..32,
                    },
                    StepInputBankPlan {
                        storage_slot: 2,
                        span: 0..32,
                    },
                ],
            },
        ];
        assert_eq!(
            PreparedStepInputs::allocation_bytes(&plans).unwrap(),
            input_bytes
                + 2 * (size_of::<PublicationRange>() + 2 * size_of::<PublicationStepInput>())
                + 32
        );
        assert!(PreparedStepInputs::allocation_bytes(&[StepInputPlan {
            banks: [
                StepInputBankPlan {
                    storage_slot: 1,
                    span: 0..usize::MAX,
                },
                StepInputBankPlan {
                    storage_slot: 2,
                    span: 0..usize::MAX,
                },
            ],
            ..plans[1].clone()
        }])
        .is_err());
        let step_bytes = prepared_step_allocation_bytes(input_bytes, feedback.bytes, 0).unwrap();
        assert_eq!(
            step_bytes,
            (input_bytes
                + feedback.bytes
                + size_of::<PublicationLease>()
                + size_of::<PreparedStepResult>()) as u64
        );
        assert_eq!(
            prepared_segment_allocation_bytes(step_bytes, 3, 0).unwrap(),
            3 * step_bytes
        );
        assert!(prepared_segment_allocation_bytes(step_bytes, 0, 0).is_err());
        assert!(prepared_segment_allocation_bytes(step_bytes, usize::MAX, 0).is_err());
    }

    #[test]
    fn prepared_scope_blocks_ordinary_rebinding_until_retirement() {
        let issuer = Arc::new(());
        let mut build = PreparedSegmentState::new(
            Arc::clone(&issuer),
            vec![1],
            std::iter::once(SemanticTransitionKind::Proposal),
            SemanticSegmentColdCapacity {
                segment_capacity_bytes: 1,
                other_external_cuda_bytes: 0,
            },
        )
        .unwrap();
        assert!(validate_rebinding_ownership(None, false).is_ok());
        assert!(validate_rebinding_ownership(None, true).is_err());
        assert!(validate_rebinding_ownership(Some(&build), false).is_err());
        let step = build.handles().unwrap().remove(0);
        build.enter(&step, &issuer).unwrap();
        build.leave(&step, &issuer).unwrap();
        build.finish().unwrap();
        build.submit().unwrap();
        build.completed = true;
        assert!(validate_rebinding_ownership(Some(&build), false).is_err());
    }

    #[test]
    fn prepared_submission_is_once_only_after_complete_construction() {
        let issuer = Arc::new(());
        let mut build = PreparedSegmentState::new(
            Arc::clone(&issuer),
            vec![1],
            std::iter::once(SemanticTransitionKind::Proposal),
            SemanticSegmentColdCapacity {
                segment_capacity_bytes: 1,
                other_external_cuda_bytes: 0,
            },
        )
        .unwrap();
        assert!(build.submit().is_err());
        let step = build.handles().unwrap().remove(0);
        build.enter(&step, &issuer).unwrap();
        build.leave(&step, &issuer).unwrap();
        build.finish().unwrap();
        build.submit().unwrap();
        assert!(build.submit().is_err());
        build.completed = true;
        assert!(build.submit().is_err());
    }

    #[test]
    fn completion_uses_original_parent_and_requires_device_release() {
        let parent = PublicationHeader {
            abi: 1,
            publication_word: 2,
            // Proposal publication and model-weight banks advance separately.
            neural_bank: 1,
            sealed_epoch: 1,
            proposal: 37,
            model_generation: 9,
            family_id: 3,
            stream_serial: 91,
            ..PublicationHeader::default()
        };
        let mut lease = PublicationLease {
            abi: 1,
            word: 2,
            epoch: 1,
            transition_kind: 1,
            ..PublicationLease::default()
        };
        let mut result = PreparedStepResult {
            abi: 1,
            word: 5,
            advanced: 1,
            header: PublicationHeader {
                abi: 1,
                base_word: 2,
                publication_word: 5,
                sealed_epoch: 2,
                proposal: 38,
                ..parent
            },
            attempt: AttemptReceipt {
                abi: 2,
                transition_kind: 1,
                instance: parent.instance,
                base_word: 2,
                next_word: 5,
                logical_digest: parent.logical_digest,
                ..AttemptReceipt::default()
            },
            ..PreparedStepResult::default()
        };
        assert_eq!(
            validate_prepared_completion(&lease, &parent, &result, parent.instance).unwrap(),
            SemanticTransitionKind::Proposal
        );
        assert_eq!(parent.rng_binding().unwrap().proposal, 37);
        lease.active = 1;
        assert!(validate_prepared_completion(&lease, &parent, &result, parent.instance).is_err());
        lease.active = 0;
        result.word = 8;
        assert!(validate_prepared_completion(&lease, &parent, &result, parent.instance).is_err());
        result.word = 5;
        lease.transition_kind = 0;
        assert!(validate_prepared_completion(&lease, &parent, &result, parent.instance).is_err());
    }
}

